export const app = express();
app.disable("x-powered-by");
app.set("trust proxy", isHostedRuntime ? 1 : false);
const largeJsonUploadPathPattern =
  /^\/api\/(?:advertiser\/(?:brand-image|campaign-image)|influencer\/public-profile\/avatar|verification\/(?:advertiser|influencer)|contracts\/[^/]+\/(?:deliverables|signatures\/influencer))$/;
const standardJsonParser = express.json({ limit: "256kb" });
const largeUploadJsonParser = express.json({ limit: "14mb" });
const largeUploadBodyLimitBytes = 14 * 1024 * 1024;
const largeUploadPreBodyWindowMs = 60 * 1000;
const largeUploadPreBodyMaxRequests = 30;
const largeUploadPreBodyMaxTrackedNetworks = 5_000;
const largeUploadPreBodyBuckets = new Map<
  string,
  { count: number; resetAt: number }
>();
const instagramWebhookJsonParser = express.json({
  limit: "1mb",
  verify: (request, _response, buffer) => {
    (request as express.Request & { rawBody?: Buffer }).rawBody =
      Buffer.from(buffer);
  },
});
app.use((request, response, next) => {
  if (!largeJsonUploadPathPattern.test(request.path)) {
    next();
    return;
  }

  const declaredLength = Number(request.header("content-length"));
  if (
    Number.isFinite(declaredLength) &&
    declaredLength > largeUploadBodyLimitBytes
  ) {
    response.setHeader("Cache-Control", "private, no-store");
    response.status(413).json({ error: "Request body is too large" });
    return;
  }

  const now = Date.now();
  const networkKey = createHash("sha256")
    .update(getClientIp(request))
    .digest("hex")
    .slice(0, 32);
  if (
    !largeUploadPreBodyBuckets.has(networkKey) &&
    largeUploadPreBodyBuckets.size >= largeUploadPreBodyMaxTrackedNetworks
  ) {
    for (const [key, candidate] of largeUploadPreBodyBuckets) {
      if (candidate.resetAt <= now) largeUploadPreBodyBuckets.delete(key);
    }
    while (
      largeUploadPreBodyBuckets.size >= largeUploadPreBodyMaxTrackedNetworks
    ) {
      const oldestKey = largeUploadPreBodyBuckets.keys().next().value;
      if (typeof oldestKey !== "string") break;
      largeUploadPreBodyBuckets.delete(oldestKey);
    }
  }
  const current = largeUploadPreBodyBuckets.get(networkKey);
  const bucket =
    !current || current.resetAt <= now
      ? { count: 0, resetAt: now + largeUploadPreBodyWindowMs }
      : current;
  bucket.count += 1;
  largeUploadPreBodyBuckets.set(networkKey, bucket);
  if (bucket.count > largeUploadPreBodyMaxRequests) {
    response.setHeader("Cache-Control", "private, no-store");
    response.setHeader(
      "Retry-After",
      String(Math.max(1, Math.ceil((bucket.resetAt - now) / 1000))),
    );
    response.status(429).json({ error: "Too many upload requests" });
    return;
  }

  next();
});
app.use((request, response, next) => {
  if (request.path === "/api/webhooks/instagram") {
    instagramWebhookJsonParser(request, response, next);
    return;
  }
  if (largeJsonUploadPathPattern.test(request.path)) {
    largeUploadJsonParser(request, response, next);
    return;
  }
  standardJsonParser(request, response, next);
});

type OperationalAuthMetricRequest = express.Request & {
  authMetricOperation?: AuthMetricOperation;
  authMetricRole?: AuthMetricRole;
  authMetricOutcome?: AuthMetricOutcome;
  authMetricDataOrigin?: AuthMetricDataOrigin;
};

const authMetricRoutes = new Map<
  string,
  { operation: AuthMetricOperation; role: AuthMetricRole }
>([
  ["/api/advertiser/login", { operation: "user_login", role: "marketer" }],
  ["/api/influencer/login", { operation: "user_login", role: "influencer" }],
  ["/api/admin/login", { operation: "admin_login", role: "admin" }],
  ["/api/admin/mfa/verify", { operation: "admin_mfa_verify", role: "admin" }],
  ["/api/auth/recent", { operation: "recent_auth_issue", role: "anonymous" }],
  ["/api/advertiser/logout", { operation: "session_logout", role: "marketer" }],
  ["/api/influencer/logout", { operation: "session_logout", role: "influencer" }],
  ["/api/admin/logout", { operation: "session_logout", role: "admin" }],
  ["/api/auth/password-reset/request", { operation: "password_reset", role: "anonymous" }],
  ["/api/auth/password-reset/complete", { operation: "password_reset", role: "anonymous" }],
]);

app.use((request, response, next) => {
  const config = authMetricRoutes.get(request.path);
  if (!config) {
    next();
    return;
  }
  const metricRequest = request as OperationalAuthMetricRequest;
  const startedAt = Date.now();
  metricRequest.authMetricOperation = config.operation;
  metricRequest.authMetricRole = config.role;
  metricRequest.authMetricDataOrigin = classifyAuthMetricDataOrigin({
    identifier: normalizeOptionalText(request.body?.email),
  });
  response.once("finish", () => {
    const status = response.statusCode;
    const outcome =
      metricRequest.authMetricOutcome ??
      (status >= 200 && status < 300
        ? "success"
        : status === 428
          ? "required"
          : status === 429
            ? "rate_limited"
            : status === 401
              ? "rejected"
              : status === 403
                ? "invalid"
                : status >= 500
                  ? "provider_error"
                  : "rejected");
    observeOperationalAuthMetric({
      operation: metricRequest.authMetricOperation ?? config.operation,
      role: metricRequest.authMetricRole ?? config.role,
      outcome,
      latencyMs: Date.now() - startedAt,
      dataOrigin: metricRequest.authMetricDataOrigin,
    });
  });
  next();
});

const stateChangingMethods = new Set(["POST", "PUT", "PATCH", "DELETE"]);
const allowedConfiguredOrigins = [
  process.env.PUBLIC_SITE_URL,
  process.env.SITE_URL,
  process.env.VITE_SITE_URL,
  process.env.VITE_API_BASE_URL,
]
  .map((value) => {
    if (typeof value !== "string" || value.trim().length === 0) return undefined;
    try {
      return new URL(value).origin;
    } catch {
      return undefined;
    }
  })
  .filter((value): value is string => typeof value === "string" && value.length > 0);

const isAllowedRequestOrigin = (request: express.Request) => {
  const origin = request.header("origin");
  if (typeof origin !== "string" || origin.trim().length === 0) return true;

  let originUrl: URL;
  try {
    originUrl = new URL(origin);
  } catch {
    return false;
  }

  if (allowedConfiguredOrigins.includes(originUrl.origin)) return true;

  const requestHost =
    request.header("x-forwarded-host") ?? request.header("host") ?? "";
  const requestProto =
    request.header("x-forwarded-proto") ?? request.protocol ?? "http";
  return `${requestProto}://${requestHost}` === originUrl.origin;
};

app.use((request, response, next) => {
  if (
    stateChangingMethods.has(request.method.toUpperCase()) &&
    !isAllowedRequestOrigin(request)
  ) {
    response.status(403).json({ error: "Cross-site request origin is not allowed" });
    return;
  }

  next();
});

