const hasText = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0;

const getInstagramDmChallengeCipherKey = () =>
  shareTokenEncryptionSecret
    ? createHash("sha256")
        .update(`instagram-dm-challenge:${shareTokenEncryptionSecret}`)
        .digest()
    : undefined;

const hashInstagramDmChallengeCode = (value: string) => {
  const key = getInstagramDmChallengeCipherKey();
  if (!key) {
    throw new Error("Instagram DM challenge encryption is not configured");
  }
  return createHmac("sha256", key)
    .update(normalizeChallengeCode(value))
    .digest("hex");
};

const encryptInstagramDmChallengeCode = (value: string, requestId: string) => {
  const key = getInstagramDmChallengeCipherKey();
  if (!key) {
    throw new Error("Instagram DM challenge encryption is not configured");
  }
  const iv = randomBytes(12);
  const cipher = createCipheriv("aes-256-gcm", key, iv);
  cipher.setAAD(Buffer.from(requestId, "utf8"));
  const ciphertext = Buffer.concat([
    cipher.update(value, "utf8"),
    cipher.final(),
  ]);
  const payload = Buffer.concat([iv, cipher.getAuthTag(), ciphertext]);
  return `${instagramDmChallengeCipherPrefix}${payload.toString("base64url")}`;
};

const decryptInstagramDmChallengeCode = (
  value: string | undefined,
  requestId: string,
) => {
  if (!hasText(value) || !value.startsWith(instagramDmChallengeCipherPrefix)) {
    return undefined;
  }
  const key = getInstagramDmChallengeCipherKey();
  if (!key) return undefined;
  try {
    const payload = Buffer.from(
      value.slice(instagramDmChallengeCipherPrefix.length),
      "base64url",
    );
    const iv = payload.subarray(0, 12);
    const authTag = payload.subarray(12, 28);
    const ciphertext = payload.subarray(28);
    const decipher = createDecipheriv("aes-256-gcm", key, iv);
    decipher.setAAD(Buffer.from(requestId, "utf8"));
    decipher.setAuthTag(authTag);
    const challengeCode = Buffer.concat([
      decipher.update(ciphertext),
      decipher.final(),
    ]).toString("utf8");
    return ownershipChallengePattern.test(challengeCode)
      ? challengeCode
      : undefined;
  } catch {
    return undefined;
  }
};

const createInstagramDmChallengeCode = () => {
  const values = randomBytes(8);
  const token = Array.from(
    values,
    (value) => instagramDmChallengeAlphabet[value & 31],
  );
  return `DS-${token.slice(0, 4).join("")}-${token.slice(4).join("")}`;
};

type InfluencerOwnershipChallengeTokenPayload = {
  version: 1;
  challenge_id: string;
  profile_id: string;
  platform: InfluencerPlatform;
  challenge_code: string;
  platform_handle_hash: string;
  platform_url_hash: string;
  issued_at: number;
  expires_at: number;
};

type InfluencerOwnershipChallengeConsumeResult = {
  consumed: boolean;
  reason: "consumed" | "already_consumed" | "expired" | "invalid_time";
};

const signInfluencerOwnershipChallengePayload = (
  encodedPayload: string,
  secret: string,
) =>
  createHmac("sha256", secret)
    .update(`${influencerOwnershipChallengeSignatureDomain}:${encodedPayload}`)
    .digest("base64url");

export const issueInfluencerOwnershipChallenge = ({
  secret,
  profileId,
  platform,
  platformHandle,
  platformUrl,
  nowMs = Date.now(),
}: {
  secret: string;
  profileId: string;
  platform: InfluencerPlatform;
  platformHandle: string;
  platformUrl: string;
  nowMs?: number;
}) => {
  if (!hasText(secret) || !hasText(profileId) || !influencerPlatforms.has(platform)) {
    throw new Error("Influencer ownership challenge requires exact server values");
  }

  const binding = buildInfluencerOwnershipChallengeBinding({
    platform,
    platformHandle,
    platformUrl,
  });
  if (binding.ok === false) {
    throw new Error(binding.error);
  }

  const challengeCode = createInstagramDmChallengeCode();
  const payload: InfluencerOwnershipChallengeTokenPayload = {
    version: 1,
    challenge_id: randomUUID(),
    profile_id: profileId,
    platform,
    challenge_code: challengeCode,
    platform_handle_hash: binding.platformHandleHash,
    platform_url_hash: binding.platformUrlHash,
    issued_at: nowMs,
    expires_at: nowMs + influencerOwnershipChallengeTtlMs,
  };
  const encodedPayload = Buffer.from(JSON.stringify(payload), "utf8").toString(
    "base64url",
  );
  const signature = signInfluencerOwnershipChallengePayload(
    encodedPayload,
    secret,
  );

  return {
    code: challengeCode,
    token: `${encodedPayload}.${signature}`,
    expiresAt: payload.expires_at,
  };
};

export const verifyInfluencerOwnershipChallengeToken = ({
  token,
  secret,
  profileId,
  platform,
  challengeCode,
  platformHandle,
  platformUrl,
  nowMs = Date.now(),
}: {
  token: string | undefined;
  secret: string;
  profileId: string;
  platform: InfluencerPlatform;
  challengeCode: string;
  platformHandle: string;
  platformUrl: string;
  nowMs?: number;
}) => {
  const binding = buildInfluencerOwnershipChallengeBinding({
    platform,
    platformHandle,
    platformUrl,
  });
  if (
    !hasText(token) ||
    token.length > 2_048 ||
    !hasText(secret) ||
    !hasText(profileId) ||
    !influencerPlatforms.has(platform) ||
    !ownershipChallengePattern.test(challengeCode) ||
    !binding.ok
  ) {
    return undefined;
  }

  const [encodedPayload, signature, extra] = token.split(".");
  if (!encodedPayload || !signature || extra) return undefined;
  const expectedSignature = signInfluencerOwnershipChallengePayload(
    encodedPayload,
    secret,
  );
  if (!safeEqual(signature, expectedSignature)) return undefined;

  try {
    const payload = JSON.parse(
      Buffer.from(encodedPayload, "base64url").toString("utf8"),
    ) as Partial<InfluencerOwnershipChallengeTokenPayload>;
    if (
      payload.version !== 1 ||
      !hasText(payload.challenge_id) ||
      !/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
        payload.challenge_id,
      ) ||
      payload.profile_id !== profileId ||
      payload.platform !== platform ||
      payload.challenge_code !== challengeCode ||
      payload.platform_handle_hash !== binding.platformHandleHash ||
      payload.platform_url_hash !== binding.platformUrlHash ||
      !Number.isFinite(payload.issued_at) ||
      !Number.isFinite(payload.expires_at) ||
      payload.issued_at! > nowMs + influencerOwnershipChallengeClockSkewMs ||
      payload.expires_at! <= nowMs ||
      payload.expires_at! - payload.issued_at! !==
        influencerOwnershipChallengeTtlMs
    ) {
      return undefined;
    }
    return payload as InfluencerOwnershipChallengeTokenPayload;
  } catch {
    return undefined;
  }
};

const getShareTokenCipherKey = () => {
  if (!shareTokenEncryptionSecret) return undefined;
  return createHash("sha256").update(shareTokenEncryptionSecret).digest();
};

const encryptShareTokenForLegacyStore = (value: string | undefined | null) => {
  if (!hasText(value)) return undefined;
  if (value.startsWith(shareTokenCipherPrefix)) return value;

  const key = getShareTokenCipherKey();
  if (!key) return value;

  const iv = randomBytes(12);
  const cipher = createCipheriv("aes-256-gcm", key, iv);
  const ciphertext = Buffer.concat([
    cipher.update(value, "utf8"),
    cipher.final(),
  ]);
  const payload = Buffer.concat([iv, cipher.getAuthTag(), ciphertext]);
  return `${shareTokenCipherPrefix}${payload.toString("base64url")}`;
};

const decryptShareTokenFromLegacyStore = (value: string | undefined | null) => {
  if (!hasText(value)) return undefined;
  if (!value.startsWith(shareTokenCipherPrefix)) return value;

  const key = getShareTokenCipherKey();
  if (!key) return undefined;

  try {
    const payload = Buffer.from(value.slice(shareTokenCipherPrefix.length), "base64url");
    const iv = payload.subarray(0, 12);
    const authTag = payload.subarray(12, 28);
    const ciphertext = payload.subarray(28);
    const decipher = createDecipheriv("aes-256-gcm", key, iv);
    decipher.setAuthTag(authTag);
    return Buffer.concat([
      decipher.update(ciphertext),
      decipher.final(),
    ]).toString("utf8");
  } catch {
    if (logLegacyShareTokenDecryptWarnings) {
      const fingerprint = createHash("sha256").update(value).digest("hex").slice(0, 12);
      if (!loggedLegacyShareTokenDecryptFailures.has(fingerprint)) {
        if (
          loggedLegacyShareTokenDecryptFailures.size >=
          maxLoggedLegacyShareTokenDecryptFailures
        ) {
          loggedLegacyShareTokenDecryptFailures.clear();
        }
        loggedLegacyShareTokenDecryptFailures.add(fingerprint);
        console.warn(`[yeollock.me] failed to decrypt legacy share token ${fingerprint}`);
      }
    }
    return undefined;
  }
};

const googleTokenCipherPrefix = "gws:v1:";

const getGoogleWorkspaceCipherKey = () => {
  const secret =
    googleWorkspaceTokenSecret ?? shareTokenEncryptionSecret;
  return secret ? createHash("sha256").update(secret).digest() : undefined;
};

const encryptGoogleWorkspaceToken = (value: string | undefined | null) => {
  if (!hasText(value)) return undefined;
  if (value.startsWith(googleTokenCipherPrefix)) return value;

  const key = getGoogleWorkspaceCipherKey();
  if (!key) return undefined;

  const iv = randomBytes(12);
  const cipher = createCipheriv("aes-256-gcm", key, iv);
  const ciphertext = Buffer.concat([
    cipher.update(value, "utf8"),
    cipher.final(),
  ]);
  const payload = Buffer.concat([iv, cipher.getAuthTag(), ciphertext]);
  return `${googleTokenCipherPrefix}${payload.toString("base64url")}`;
};

const decryptGoogleWorkspaceToken = (value: string | undefined | null) => {
  if (!hasText(value)) return undefined;
  if (!value.startsWith(googleTokenCipherPrefix)) return undefined;

  const key = getGoogleWorkspaceCipherKey();
  if (!key) return undefined;

  try {
    const payload = Buffer.from(value.slice(googleTokenCipherPrefix.length), "base64url");
    const iv = payload.subarray(0, 12);
    const authTag = payload.subarray(12, 28);
    const ciphertext = payload.subarray(28);
    const decipher = createDecipheriv("aes-256-gcm", key, iv);
    decipher.setAuthTag(authTag);
    return Buffer.concat([
      decipher.update(ciphertext),
      decipher.final(),
    ]).toString("utf8");
  } catch {
    return undefined;
  }
};

const normalizeContract = (contract: Contract): Contract => {
  const influencerEmail = (
    contract.influencer_info?.email ?? contract.influencer_info?.contact ?? ""
  )
    .trim()
    .toLowerCase();
  const influencerPhone = contract.influencer_info?.phone?.trim();
  const normalizedContract: Contract = {
    ...contract,
    campaign_name: hasText(contract.campaign_name)
      ? contract.campaign_name.trim()
      : contract.title,
    post_link: hasText(contract.post_link) ? contract.post_link.trim() : undefined,
    influencer_info: {
      ...contract.influencer_info,
      contact: influencerEmail,
      email: influencerEmail,
      phone: influencerPhone || undefined,
    },
  };

  if (!contract.evidence) return normalizedContract;

  const shareToken =
    contract.evidence.share_token_status === "active" &&
    hasText(contract.evidence.share_token)
      ? contract.evidence.share_token
      : undefined;

  return {
    ...normalizedContract,
    evidence: {
      ...contract.evidence,
      share_token: shareToken,
    },
  };
};

const normalizeStore = (store: ContractStoreFile): ContractStoreFile => ({
  contracts: store.contracts.map(normalizeContract),
});

