const requireSupabaseConfig = () => {
  if (!supabaseUrl || !supabaseServiceRoleKey) {
    throw new Error("Supabase is not configured");
  }

  return {
    url: supabaseUrl,
    key: supabaseServiceRoleKey,
  };
};

const supabaseHeaders = () => {
  const { key } = requireSupabaseConfig();

  return {
    apikey: key,
    Authorization: `Bearer ${key}`,
    "Content-Type": "application/json",
  };
};

const supabaseAuthHeaders = (accessToken?: string) => {
  const key = supabasePublishableKey;

  if (!supabaseUrl || !key) {
    throw new Error("Supabase Auth is not configured");
  }

  return {
    apikey: key,
    ...(accessToken ? { Authorization: `Bearer ${accessToken}` } : {}),
    "Content-Type": "application/json",
  };
};

const supabaseStorageHeaders = (contentType?: string) => {
  const { key } = requireSupabaseConfig();

  return {
    apikey: key,
    Authorization: `Bearer ${key}`,
    ...(contentType ? { "Content-Type": contentType } : {}),
  };
};

const supabaseRestUrl = (table: string, query = "") => {
  const { url } = requireSupabaseConfig();
  return `${url}/rest/v1/${table}${query}`;
};

const supabaseAuthUrl = (pathName: string) => {
  if (!supabaseUrl) {
    throw new Error("Supabase Auth is not configured");
  }

  return `${supabaseUrl}/auth/v1${pathName}`;
};

const supabaseAuthWarmupMinIntervalMs = 30 * 1000;
const supabaseRequestTimeoutMs = parsePositiveNumberEnv(
  process.env.SUPABASE_REQUEST_TIMEOUT_MS,
  8,
) * 1000;
const authenticatedMarketplaceInfluencerDirectoryTimeoutMs = Math.min(
  supabaseRequestTimeoutMs,
  4_500,
);
let supabaseAuthWarmupStartedAt = 0;
let supabaseAuthWarmupPromise: Promise<void> | undefined;

const createSupabaseTimeoutSignal = () => AbortSignal.timeout(supabaseRequestTimeoutMs);

const warmSupabaseAuthConnection = async () => {
  if (!supabaseUrl || !supabasePublishableKey) return;

  const now = Date.now();
  if (supabaseAuthWarmupPromise) {
    await supabaseAuthWarmupPromise;
    return;
  }
  if (now - supabaseAuthWarmupStartedAt < supabaseAuthWarmupMinIntervalMs) return;

  supabaseAuthWarmupStartedAt = now;
  supabaseAuthWarmupPromise = fetch(supabaseAuthUrl("/settings"), {
    headers: supabaseAuthHeaders(),
    cache: "no-store",
    signal: createSupabaseTimeoutSignal(),
  })
    .then(async (warmupResponse) => {
      if (!warmupResponse.ok) {
        throw new Error(
          `Supabase Auth warmup failed (${warmupResponse.status}): ${await parseSupabaseError(
            warmupResponse,
          )}`,
        );
      }
    })
    .finally(() => {
      supabaseAuthWarmupPromise = undefined;
    });

  await supabaseAuthWarmupPromise;
};

const supabaseStorageUrl = (pathName: string) => {
  if (!supabaseUrl) {
    throw new Error("Supabase Storage is not configured");
  }

  return `${supabaseUrl}/storage/v1${pathName}`;
};

const protectLegacyContractForSupabase = (contract: Contract): Contract => {
  if (!contract.evidence?.share_token) return contract;

  return {
    ...contract,
    evidence: {
      ...contract.evidence,
      share_token: encryptShareTokenForLegacyStore(contract.evidence.share_token),
    },
  };
};

const restoreLegacyContractFromSupabase = (
  row: Pick<SupabaseContractRow, "contract" | "share_token"> &
    Partial<
      Pick<
        SupabaseContractRow,
        "brand_profile_id" | "campaign_name" | "post_link" | "data_origin"
      >
    >,
) => {
  const fallbackToken = decryptShareTokenFromLegacyStore(row.share_token);
  const contractToken = decryptShareTokenFromLegacyStore(
    row.contract?.evidence?.share_token,
  );
  const shareToken = contractToken ?? fallbackToken;

  const restoredContract = row.contract
    ? {
        ...row.contract,
        data_origin: row.data_origin ?? row.contract.data_origin ?? undefined,
        brand_profile_id:
          row.contract.brand_profile_id ?? row.brand_profile_id ?? undefined,
        campaign_name: row.contract.campaign_name ?? row.campaign_name ?? undefined,
        post_link: row.contract.post_link ?? row.post_link ?? undefined,
      }
    : row.contract;

  if (!restoredContract?.evidence || !shareToken) return restoredContract;

  return {
    ...restoredContract,
    evidence: {
      ...restoredContract.evidence,
      share_token: shareToken,
    },
  };
};

const toLegacySupabaseStatus = (status: Contract["status"]) =>
  status === "CLOSED" ? "SIGNED" : status;

const toSupabaseRow = (contract: Contract): SupabaseContractRow => {
  const normalizedContract = normalizeContract(contract);
  const protectedContract = protectLegacyContractForSupabase(normalizedContract);

  return {
    id: normalizedContract.id,
    advertiser_id: normalizedContract.advertiser_id,
    brand_profile_id: normalizedContract.brand_profile_id ?? null,
    campaign_name: normalizedContract.campaign_name ?? normalizedContract.title,
    post_link: normalizedContract.post_link ?? null,
    title: normalizedContract.title,
    status: toLegacySupabaseStatus(normalizedContract.status),
    influencer_name: normalizedContract.influencer_info?.name,
    share_token:
      encryptShareTokenForLegacyStore(normalizedContract.evidence?.share_token) ??
      null,
    share_token_status:
      normalizedContract.evidence?.share_token_status ?? "not_issued",
    data_origin: normalizedContract.data_origin ?? null,
    contract: protectedContract,
    created_at: normalizedContract.created_at,
    updated_at: normalizedContract.updated_at,
  };
};

const parseSupabaseError = async (response: Response) => {
  const body = await response.text();
  try {
    const parsed = JSON.parse(body) as {
      message?: string;
      error?: string;
      msg?: string;
      error_code?: string;
    };
    return parsed.message ?? parsed.msg ?? parsed.error ?? parsed.error_code ?? body;
  } catch {
    return body;
  }
};

const parseSupabaseAuthError = async (response: Response) => {
  const body = await response.text();
  try {
    const parsed = JSON.parse(body) as {
      code?: string;
      error_code?: string;
      error?: string;
      error_description?: string;
      message?: string;
      msg?: string;
    };
    const code = parsed.code ?? parsed.error_code ?? parsed.error;
    const message = [
      parsed.message,
      parsed.msg,
      parsed.error_description,
      parsed.error,
      parsed.code,
      parsed.error_code,
    ]
      .filter((value): value is string => hasText(value))
      .filter((value, index, values) => values.indexOf(value) === index)
      .join(": ");
    return { code, message: message || body };
  } catch {
    return { message: body };
  }
};

type SupabaseRequestInit = Omit<RequestInit, "headers"> & {
  headers?: Record<string, string>;
};

const fetchSupabase = (table: string, query = "", init: SupabaseRequestInit = {}) =>
  fetch(supabaseRestUrl(table, query), {
    ...init,
    signal: init.signal ?? createSupabaseTimeoutSignal(),
    headers: {
      ...supabaseHeaders(),
      ...(init.headers ?? {}),
    },
  });

const fetchSupabaseAsUser = (
  table: string,
  accessToken: string,
  query = "",
  init: SupabaseRequestInit = {},
) => {
  if (!supabaseUrl || !hasText(accessToken)) {
    throw new Error("Authenticated Supabase REST is not configured");
  }

  return fetch(`${supabaseUrl}/rest/v1/${table}${query}`, {
    ...init,
    cache: "no-store",
    signal: init.signal ?? createSupabaseTimeoutSignal(),
    headers: {
      ...supabaseAuthHeaders(accessToken),
      ...(init.headers ?? {}),
    },
  });
};

const assertSupabaseOk = async (response: Response, label: string) => {
  if (!response.ok) {
    throw new Error(
      `${label} failed (${response.status}): ${await parseSupabaseError(response)}`,
    );
  }
};

const isMissingLegacyCampaignColumnError = (message: string) =>
  /campaign_name|post_link|data_origin/i.test(message) &&
  /column|schema cache|Could not find/i.test(message);

const readSupabaseRows = async <T>(table: string, query = "", label = table) => {
  const response = await fetchSupabase(table, query);
  await assertSupabaseOk(response, `Supabase ${label} read`);
  return (await response.json()) as T[];
};

const callSupabaseRpc = async <T>(
  functionName: string,
  params: Record<string, unknown>,
  label = functionName,
  init: SupabaseRequestInit = {},
) => {
  const response = await fetchSupabase(`rpc/${functionName}`, "", {
    ...init,
    method: "POST",
    body: JSON.stringify(params),
  });
  await assertSupabaseOk(response, `Supabase ${label}`);
  return (await response.json()) as T;
};

const readNaverSearchBudgetNumber = (
  value: string | undefined,
  fallback: number,
  maximum?: number,
) => {
  const parsed = value?.trim() ? Number(value) : fallback;
  return Number.isFinite(parsed) && parsed > 0 && (maximum === undefined || parsed <= maximum)
    ? parsed
    : fallback;
};

const reserveNaverSearchVerificationRequest = () =>
  callSupabaseRpc<{
    allowed: boolean;
    reason?: string;
    date_kst: string;
    expires_at: string;
    cap: number;
    used: number;
    remaining: number;
    reserved?: number;
  }>(
    "reserve_naver_search_verification_request",
    {
      p_endpoint: "blog_verification",
      p_daily_limit: Math.floor(
        readNaverSearchBudgetNumber(
          process.env.NAVER_SEARCH_DAILY_LIMIT,
          25_000,
          1_000_000,
        ),
      ),
      p_budget_ratio: readNaverSearchBudgetNumber(
        process.env.NAVER_SEARCH_VERIFICATION_DAILY_BUDGET_RATIO,
        0.05,
        0.05,
      ),
    },
    "NAVER Search verification budget reservation",
  );

type NaverSearchVerificationReservation = Awaited<
  ReturnType<typeof reserveNaverSearchVerificationRequest>
>;

const consumeInfluencerOwnershipChallengeRpc = (
  payload: InfluencerOwnershipChallengeTokenPayload,
) =>
  callSupabaseRpc<InfluencerOwnershipChallengeConsumeResult>(
    "consume_influencer_ownership_challenge",
    {
      p_challenge_id: payload.challenge_id,
      p_profile_id: payload.profile_id,
      p_platform: payload.platform,
      p_code_digest: sha256Hex(
        `${influencerOwnershipChallengeSignatureDomain}:code:${payload.challenge_code}`,
      ),
      p_platform_handle_hash: payload.platform_handle_hash,
      p_platform_url_hash: payload.platform_url_hash,
      p_issued_at: new Date(payload.issued_at).toISOString(),
      p_expires_at: new Date(payload.expires_at).toISOString(),
    },
    "influencer ownership challenge consume",
  );

export const consumeInfluencerOwnershipChallenge = async ({
  payload,
  consumeRpc = useSupabase
    ? consumeInfluencerOwnershipChallengeRpc
    : undefined,
  nowMs = Date.now(),
}: {
  payload: InfluencerOwnershipChallengeTokenPayload;
  consumeRpc?: (
    value: InfluencerOwnershipChallengeTokenPayload,
  ) => Promise<InfluencerOwnershipChallengeConsumeResult>;
  nowMs?: number;
}): Promise<InfluencerOwnershipChallengeConsumeResult> => {
  if (consumeRpc) {
    const result = await consumeRpc(payload);
    if (
      !result ||
      typeof result.consumed !== "boolean" ||
      !["consumed", "already_consumed", "expired", "invalid_time"].includes(
        result.reason,
      ) ||
      result.consumed !== (result.reason === "consumed")
    ) {
      throw new Error("Influencer ownership challenge consume result was invalid");
    }
    return result;
  }

  let cleaned = 0;
  for (const [challengeId, expiresAt] of locallyConsumedInfluencerOwnershipChallenges) {
    if (
      cleaned >= 500 ||
      expiresAt + influencerOwnershipChallengeLedgerRetentionMs >= nowMs
    ) {
      continue;
    }
    locallyConsumedInfluencerOwnershipChallenges.delete(challengeId);
    cleaned += 1;
  }
  if (
    payload.expires_at <= nowMs ||
    payload.issued_at > nowMs + influencerOwnershipChallengeClockSkewMs ||
    payload.expires_at - payload.issued_at !== influencerOwnershipChallengeTtlMs
  ) {
    return {
      consumed: false,
      reason: payload.expires_at <= nowMs ? "expired" : "invalid_time",
    };
  }
  if (locallyConsumedInfluencerOwnershipChallenges.has(payload.challenge_id)) {
    return { consumed: false, reason: "already_consumed" };
  }
  locallyConsumedInfluencerOwnershipChallenges.set(
    payload.challenge_id,
    payload.expires_at,
  );
  return { consumed: true, reason: "consumed" };
};

export const isMissingInfluencerOwnershipChallengeConsumeRpcError = (
  error: unknown,
) =>
  error instanceof Error &&
  /PGRST202|Could not find the function[^\n]*consume_influencer_ownership_challenge|schema cache[^\n]*consume_influencer_ownership_challenge/i.test(
    error.message,
  );

const getKstDate = (nowMs: number) =>
  new Date(nowMs + 9 * 60 * 60 * 1000).toISOString().slice(0, 10);

const getKstDayExpiry = (dateKst: string) => {
  try {
    const nextDay = new Date(`${dateKst}T00:00:00.000+09:00`);
    if (!Number.isFinite(nextDay.getTime())) return undefined;
    if (getKstDate(nextDay.getTime()) !== dateKst) return undefined;
    nextDay.setUTCDate(nextDay.getUTCDate() + 1);
    return nextDay.toISOString();
  } catch {
    return undefined;
  }
};

export const validateNaverSearchVerificationReservation = (
  value: unknown,
  nowMs = Date.now(),
) => {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const reservation = value as Partial<NaverSearchVerificationReservation>;
  if (
    typeof reservation.allowed !== "boolean" ||
    !/^\d{4}-\d{2}-\d{2}$/.test(reservation.date_kst ?? "") ||
    !Number.isSafeInteger(reservation.cap) ||
    Number(reservation.cap) < 1 ||
    !Number.isSafeInteger(reservation.used) ||
    Number(reservation.used) < 0 ||
    !Number.isSafeInteger(reservation.remaining) ||
    Number(reservation.remaining) < 0 ||
    reservation.expires_at !== getKstDayExpiry(reservation.date_kst!) ||
    !Number.isFinite(Date.parse(reservation.expires_at))
  ) {
    return false;
  }
  if (
    reservation.allowed &&
    (reservation.reserved !== 1 ||
      reservation.used! > reservation.cap! ||
      reservation.remaining !== reservation.cap! - reservation.used!)
  ) {
    return false;
  }
  if (
    !reservation.allowed &&
    (reservation.remaining !== 0 || reservation.used! < reservation.cap!)
  ) {
    return false;
  }
  return Date.parse(reservation.expires_at) > nowMs - 24 * 60 * 60 * 1000;
};

export const prepareNaverSearchVerificationReservationForFetch = async ({
  reservation,
  reserve = reserveNaverSearchVerificationRequest,
  nowMs = Date.now(),
  guardMs = naverSearchMidnightGuardMs,
}: {
  reservation: unknown;
  reserve?: () => Promise<NaverSearchVerificationReservation>;
  nowMs?: number;
  guardMs?: number;
}): Promise<
  | { allowed: true; reservation: NaverSearchVerificationReservation }
  | { allowed: false; reason: string }
> => {
  if (!Number.isSafeInteger(nowMs) || !Number.isSafeInteger(guardMs) || guardMs < 0) {
    return { allowed: false, reason: "invalid_reservation" };
  }
  let current = reservation;
  if (!validateNaverSearchVerificationReservation(current, nowMs)) {
    return { allowed: false, reason: "invalid_reservation" };
  }
  let typed = current as NaverSearchVerificationReservation;
  const currentDateKst = getKstDate(nowMs);
  if (typed.date_kst !== currentDateKst || Date.parse(typed.expires_at) <= nowMs) {
    current = await reserve();
    if (!validateNaverSearchVerificationReservation(current, nowMs)) {
      return { allowed: false, reason: "invalid_reservation" };
    }
    typed = current as NaverSearchVerificationReservation;
  }
  if (!typed.allowed) {
    return { allowed: false, reason: typed.reason ?? "budget_exhausted" };
  }
  if (
    typed.date_kst !== getKstDate(nowMs) ||
    Date.parse(typed.expires_at) - nowMs <= guardMs
  ) {
    return { allowed: false, reason: "midnight_guard" };
  }
  return { allowed: true, reservation: typed };
};

