const fetchJsonWithTimeout = async <T>(
  url: string,
  init: RequestInit = {},
  timeoutMs = 6500,
): Promise<{ status: number; ok: boolean; payload: T; body: string }> => {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const apiResponse = await fetch(url, {
      ...init,
      signal: controller.signal,
    });
    const body = await apiResponse.text();
    let payload = {} as T;

    try {
      payload = body ? (JSON.parse(body) as T) : ({} as T);
    } catch {
      payload = {} as T;
    }

    return {
      status: apiResponse.status,
      ok: apiResponse.ok,
      payload,
      body,
    };
  } finally {
    clearTimeout(timeout);
  }
};

const normalizeDateCompact = (value: string | undefined) => {
  if (!value) return undefined;
  const digits = value.replace(/\D/g, "");
  if (digits.length !== 8) return undefined;
  const year = Number(digits.slice(0, 4));
  const month = Number(digits.slice(4, 6));
  const day = Number(digits.slice(6, 8));
  if (
    !Number.isInteger(year) ||
    year < 1900 ||
    month < 1 ||
    month > 12 ||
    day < 1 ||
    day > 31
  ) {
    return undefined;
  }
  return digits;
};

const normalizeHandleForComparison = (value: string | undefined) =>
  normalizeRequiredText(value)
    .replace(/^@+/, "")
    .replace(/^https?:\/\/(www\.)?/i, "")
    .replace(/\/+$/, "")
    .toLowerCase();

const extractNaverBlogId = (value: string | undefined) => {
  const raw = normalizeRequiredText(value);
  if (!raw) return "";

  try {
    const url = new URL(raw);
    const host = url.hostname.toLowerCase();
    if (host === "blog.naver.com" || host === "m.blog.naver.com") {
      const queryBlogId = normalizeHandleForComparison(
        url.searchParams.get("blogId") ?? undefined,
      );
      if (queryBlogId) return queryBlogId;

      return normalizeHandleForComparison(url.pathname.split("/").filter(Boolean)[0]);
    }
  } catch {
    // Fall through to direct handle normalization.
  }

  return normalizeHandleForComparison(raw);
};

const extractTikTokUsername = (value: string | undefined) => {
  const raw = normalizeRequiredText(value);
  if (!raw) return "";
  try {
    const url = new URL(raw);
    if (!/(^|\.)tiktok\.com$/i.test(url.hostname)) return "";
    const usernamePart = url.pathname
      .split("/")
      .filter(Boolean)
      .find((part) => part.startsWith("@"));
    return normalizeHandleForComparison(usernamePart);
  } catch {
    return normalizeHandleForComparison(raw);
  }
};

const extractYoutubeHandle = (value: string | undefined) => {
  const raw = normalizeRequiredText(value);
  if (!raw) return "";
  try {
    const url = new URL(raw);
    if (!/(^|\.)youtube\.com$/i.test(url.hostname)) return "";
    const handlePart = url.pathname
      .split("/")
      .filter(Boolean)
      .find((part) => part.startsWith("@"));
    return normalizeHandleForComparison(handlePart);
  } catch {
    return normalizeHandleForComparison(raw);
  }
};

const stripHtmlTags = (value: string | undefined) =>
  normalizeRequiredText(value).replace(/<[^>]*>/g, " ");

const buildAutomationOwnershipStatus = (
  status: VerificationAutomationStatus,
): OwnershipCheckStatus => {
  if (status === "matched") return "matched";
  if (status === "pending") return "not_run";
  if (status === "not_found" || status === "invalid_input") return "not_found";
  if (status === "blocked" || status === "not_configured") return "blocked";
  return "failed";
};

const shouldAutoApproveBusinessVerification = (
  check: VerificationAutomationResult,
) =>
  process.env.VERIFICATION_AUTO_APPROVE_BUSINESS !== "false" &&
  check.status === "matched" &&
  check.profile?.business_status_code === "01" &&
  check.profile?.validate_status === "matched";

type AdvertiserVerificationFallbackReason =
  | "not_matched"
  | "service_unavailable"
  | "inactive";

const buildAdvertiserVerificationFallback = (
  check: VerificationAutomationResult,
): {
  reason: AdvertiserVerificationFallbackReason;
  message: string;
  retryable: boolean;
} => {
  const validateHttpStatus = Number(check.profile?.validate_http_status);
  const providerUnavailable =
    !check.configured ||
    check.status === "blocked" ||
    check.status === "failed" ||
    check.status === "not_configured" ||
    (typeof check.http_status === "number" &&
      (check.http_status < 200 || check.http_status >= 300)) ||
    (Number.isFinite(validateHttpStatus) &&
      (validateHttpStatus < 200 || validateHttpStatus >= 300));

  if (providerUnavailable) {
    return {
      reason: "service_unavailable",
      message:
        "지금 국세청 자동 확인을 완료하지 못했습니다. 다시 시도하거나 서류로 인증해 주세요.",
      retryable: true,
    };
  }

  const businessStatusCode = normalizeRequiredText(
    check.profile?.business_status_code,
  );
  const businessStatusLabel = normalizeRequiredText(
    check.profile?.business_status_label,
  );
  if (
    (businessStatusCode && businessStatusCode !== "01") ||
    (!businessStatusCode &&
      businessStatusLabel &&
      !businessStatusLabel.includes("계속"))
  ) {
    return {
      reason: "inactive",
      message:
        "국세청에서 휴업 또는 폐업 상태로 조회됩니다. 현재 계속사업자라면 최신 증빙을 제출해 주세요.",
      retryable: false,
    };
  }

  return {
    reason: "not_matched",
    message:
      "입력 정보가 국세청 등록 정보와 일치하지 않거나 신규 등록 정보가 아직 반영되지 않았습니다. 서류로 이어서 인증할 수 있습니다.",
    retryable: false,
  };
};

const shouldAutoApprovePlatformVerification = (
  check: VerificationAutomationResult,
) =>
  process.env.VERIFICATION_AUTO_APPROVE_PLATFORM === "true" &&
  check.status === "matched";

const runBusinessRegistrationAutomationCheck = async (
  businessRegistrationNumber: string,
  options: {
    businessStartDate?: string;
    representativeName?: string;
  } = {},
): Promise<VerificationAutomationResult> => {
  const checkedAt = new Date().toISOString();
  const normalizedNumber = normalizeBusinessRegistrationNumber(
    businessRegistrationNumber,
  );
  const serviceKey =
    process.env.NTS_BUSINESS_STATUS_API_KEY?.trim() ||
    process.env.NTS_BUSINESS_VALIDATE_API_KEY?.trim() ||
    "";
  const statusServiceKey =
    process.env.NTS_BUSINESS_STATUS_API_KEY?.trim() || serviceKey;
  const validateServiceKey =
    process.env.NTS_BUSINESS_VALIDATE_API_KEY?.trim() || serviceKey;
  const businessStartDate = normalizeDateCompact(options.businessStartDate);
  const representativeName = normalizeRequiredText(options.representativeName);

  if (!isValidBusinessRegistrationNumber(normalizedNumber)) {
    return {
      provider: "nts_businessman",
      configured: Boolean(serviceKey),
      mode: serviceKey ? "api_ready" : "manual_fallback",
      status: "invalid_input",
      checked_at: checkedAt,
      message: "사업자등록번호 체크섬이 유효하지 않아 자동 조회를 건너뛰었습니다.",
    };
  }

  if (!serviceKey) {
    return {
      provider: "nts_businessman",
      configured: false,
      mode: "manual_fallback",
      status: "not_configured",
      checked_at: checkedAt,
      message:
        "국세청 사업자등록정보 API 키가 없어 자동 조회를 실행하지 못했습니다. API 등록 후 NTS_BUSINESS_STATUS_API_KEY를 설정하기 전에는 서류 인증 경로를 안내합니다.",
    };
  }

  if (!businessStartDate || !representativeName) {
    return {
      provider: "nts_businessman",
      configured: true,
      mode: "api_ready",
      status: "invalid_input",
      checked_at: checkedAt,
      message: "대표자명과 개업일자가 없어 국세청 진위확인을 실행하지 않았습니다.",
    };
  }

  try {
    const statusUrl = new URL(
      "https://api.odcloud.kr/api/nts-businessman/v1/status",
    );
    statusUrl.searchParams.set("serviceKey", statusServiceKey);
    const validateUrl = new URL(
      "https://api.odcloud.kr/api/nts-businessman/v1/validate",
    );
    validateUrl.searchParams.set("serviceKey", validateServiceKey);

    const [statusResponse, validateResponse] = await Promise.all([
      fetchJsonWithTimeout<{
        data?: Array<{
          b_no?: string;
          b_stt?: string;
          b_stt_cd?: string;
          tax_type?: string;
          end_dt?: string;
        }>;
      }>(
        statusUrl.toString(),
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Accept: "application/json",
          },
          body: JSON.stringify({ b_no: [normalizedNumber] }),
        },
        6500,
      ),
      fetchJsonWithTimeout<{
        data?: Array<{
          valid?: string;
          valid_msg?: string;
          request_param?: Record<string, unknown>;
          status?: Record<string, unknown>;
        }>;
      }>(
        validateUrl.toString(),
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Accept: "application/json",
          },
          body: JSON.stringify({
            businesses: [
              {
                b_no: normalizedNumber,
                start_dt: businessStartDate,
                p_nm: representativeName,
              },
            ],
          }),
        },
        6500,
      ),
    ]);
    const statusPayload = statusResponse.payload as {
      data?: Array<{
        b_no?: string;
        b_stt?: string;
        b_stt_cd?: string;
        tax_type?: string;
        end_dt?: string;
      }>;
    };
    const statusResult = statusPayload.data?.[0];
    const validateResult = validateResponse.payload.data?.[0];
    const statusPayloadValid =
      statusResponse.ok && hasText(statusResult?.b_stt_cd);
    const validatePayloadValid =
      validateResponse.ok && hasText(validateResult?.valid);
    const validateStatus: VerificationAutomationStatus = !validatePayloadValid
      ? "failed"
      : validateResult?.valid === "01"
        ? "matched"
        : "not_found";
    const isActive = statusResult?.b_stt_cd === "01";
    const automationStatus: VerificationAutomationStatus =
      !statusPayloadValid || !validatePayloadValid
        ? "failed"
        : isActive && validateStatus === "matched"
          ? "matched"
          : "not_found";

    return {
      provider: "nts_businessman",
      configured: true,
      mode: "api_ready",
      status: automationStatus,
      checked_at: checkedAt,
      http_status: statusResponse.status,
      result_hash: sha256Hex(
        JSON.stringify({
          status: statusResponse.payload,
          validate: validateResponse.payload,
        }),
      ),
      profile: {
        business_status_code: statusResult?.b_stt_cd,
        business_status_label: statusResult?.b_stt,
        tax_type: statusResult?.tax_type,
        validate_status: validateStatus,
        validate_http_status: validateResponse.status,
        validate_attempted: true,
        validate_input_ready: true,
      },
      message:
        automationStatus === "matched"
          ? "국세청에서 계속사업자 상태와 제출한 세 가지 등록 정보가 일치했습니다."
          : automationStatus === "failed"
            ? "국세청 응답을 완료된 확인 결과로 판정할 수 없습니다."
            : "국세청 등록 정보가 일치하지 않거나 계속사업자 상태가 아닙니다.",
    };
  } catch (error) {
    return {
      provider: "nts_businessman",
      configured: true,
      mode: "api_ready",
      status: "failed",
      checked_at: checkedAt,
      message:
        error instanceof Error
          ? `국세청 사업자등록 상태 자동 조회 실패: ${error.message}`
          : "국세청 사업자등록 상태 자동 조회에 실패했습니다.",
    };
  }
};

const buildNotConfiguredAutomationResult = (
  plan: ReturnType<typeof buildVerificationAutomationPlan>,
  checkedAt: string,
  message?: string,
): VerificationAutomationResult => ({
  provider: plan.provider,
  configured: false,
  mode: plan.mode,
  status: "not_configured",
  checked_at: checkedAt,
  message: message ?? plan.note,
  next_action: plan.fallback,
  plan,
});

const runPublicChallengeAutomation = async (
  proofUrl: string | undefined,
  challengeCode: string,
) => {
  if (!proofUrl) {
    return {
      status: "not_run" as OwnershipCheckStatus,
      checked_at: new Date().toISOString(),
      error: "Proof URL is missing",
    };
  }

  return checkOwnershipChallenge(proofUrl, challengeCode);
};

const parseYoutubeChannelTarget = (
  platformUrl: string,
  platformHandle: string,
) => {
  try {
    const url = new URL(platformUrl);
    const parts = url.pathname.split("/").filter(Boolean);
    const channelIndex = parts.findIndex((part) => part === "channel");
    if (channelIndex >= 0 && parts[channelIndex + 1]) {
      return { type: "id" as const, value: parts[channelIndex + 1] };
    }
    const handlePart = parts.find((part) => part.startsWith("@"));
    if (handlePart) {
      return { type: "handle" as const, value: handlePart.replace(/^@/, "") };
    }
  } catch {
    // Fall back to the submitted handle.
  }

  return {
    type: "handle" as const,
    value: normalizeHandleForComparison(platformHandle),
  };
};

export const canonicalizeInfluencerOwnershipUrl = (value: string) => {
  const raw = typeof value === "string" ? value.trim() : "";
  if (!raw || raw.length > 2_048) return undefined;
  try {
    const url = new URL(raw);
    if (
      url.protocol !== "https:" ||
      (url.port !== "" && url.port !== "443") ||
      url.username ||
      url.password ||
      !hasPublicHttpUrlHost(url.toString())
    ) {
      return undefined;
    }
    url.hostname = url.hostname.toLowerCase();
    url.port = "";
    url.pathname = url.pathname.replace(/\/{2,}/g, "/");
    url.searchParams.sort();
    url.hash = "";
    return url.toString();
  } catch {
    return undefined;
  }
};

const canonicalizeInfluencerOwnershipHandle = (
  platform: InfluencerPlatform,
  value: string,
) => {
  const raw = normalizeRequiredText(value);
  if (!raw || raw.length > 160) return "";
  if (platform === "instagram") return normalizeInstagramUsername(raw);
  if (platform === "naver_blog") return extractNaverBlogId(raw);
  if (platform === "tiktok") return extractTikTokUsername(raw);
  if (platform === "youtube" && /^UC[a-zA-Z0-9_-]{20,}$/.test(raw)) {
    return raw;
  }
  return normalizeHandleForComparison(raw);
};

const buildInfluencerOwnershipChallengeBinding = ({
  platform,
  platformHandle,
  platformUrl,
}: {
  platform: InfluencerPlatform;
  platformHandle: string;
  platformUrl: string;
}):
  | {
      ok: true;
      canonicalHandle: string;
      canonicalPlatformUrl: string;
      platformHandleHash: string;
      platformUrlHash: string;
    }
  | { ok: false; error: string } => {
  const canonicalHandle = canonicalizeInfluencerOwnershipHandle(
    platform,
    platformHandle,
  );
  const canonicalPlatformUrl = canonicalizeInfluencerOwnershipUrl(platformUrl);
  if (!canonicalHandle || !canonicalPlatformUrl) {
    return { ok: false, error: "Valid handle and profile URL are required" };
  }
  if (!isExpectedPlatformUrl(platform, canonicalPlatformUrl)) {
    return { ok: false, error: "Profile URL does not match the selected platform" };
  }
  if (
    platform === "instagram" &&
    canonicalHandle !== normalizeInstagramUsername(canonicalPlatformUrl)
  ) {
    return { ok: false, error: "Instagram handle and profile URL must match" };
  }
  if (
    platform === "tiktok" &&
    extractTikTokUsername(canonicalPlatformUrl) !==
      normalizeHandleForComparison(canonicalHandle)
  ) {
    return { ok: false, error: "TikTok handle and profile URL must match" };
  }
  if (
    platform === "naver_blog" &&
    extractNaverBlogId(canonicalPlatformUrl) !== extractNaverBlogId(canonicalHandle)
  ) {
    return { ok: false, error: "Naver Blog id and profile URL must match" };
  }
  if (platform === "youtube") {
    const youtubeTarget = parseYoutubeChannelTarget(
      canonicalPlatformUrl,
      canonicalHandle,
    );
    const normalizedHandle = normalizeHandleForComparison(canonicalHandle);
    if (
      (youtubeTarget.type === "handle" &&
        normalizeHandleForComparison(youtubeTarget.value) !== normalizedHandle) ||
      (youtubeTarget.type === "id" &&
        /^UC[a-zA-Z0-9_-]{20,}$/.test(canonicalHandle) &&
        youtubeTarget.value !== canonicalHandle)
    ) {
      return { ok: false, error: "YouTube handle and channel URL must match" };
    }
  }

  return {
    ok: true,
    canonicalHandle,
    canonicalPlatformUrl,
    platformHandleHash: sha256Hex(canonicalHandle),
    platformUrlHash: sha256Hex(canonicalPlatformUrl),
  };
};

export const validateInfluencerOwnershipProofUrl = ({
  platform,
  platformHandle,
  proofUrl,
}: {
  platform: InfluencerPlatform;
  platformHandle: string;
  proofUrl: string;
}): string | undefined => {
  const canonicalProofUrl = canonicalizeInfluencerOwnershipUrl(proofUrl);
  if (!canonicalProofUrl || !isExpectedPlatformUrl(platform, canonicalProofUrl)) {
    return "Proof URL must be an HTTPS URL for the selected platform";
  }
  if (
    platform === "naver_blog" &&
    extractNaverBlogId(canonicalProofUrl) !== extractNaverBlogId(platformHandle)
  ) {
    return "Naver Blog proof URL must belong to the submitted blog";
  }
  if (platform === "instagram") {
    const proofUsername = normalizeInstagramUsername(canonicalProofUrl);
    if (proofUsername && proofUsername !== normalizeInstagramUsername(platformHandle)) {
      return "Instagram proof URL must belong to the submitted account";
    }
  }
  if (platform === "tiktok") {
    const proofUsername = extractTikTokUsername(canonicalProofUrl);
    if (
      proofUsername &&
      proofUsername !== normalizeHandleForComparison(platformHandle)
    ) {
      return "TikTok proof URL must belong to the submitted account";
    }
  }
  return undefined;
};

const parseYoutubeVideoId = (value: string | undefined) => {
  if (!hasText(value)) return undefined;

  try {
    const url = new URL(value);
    const hostname = url.hostname.toLowerCase();
    const parts = url.pathname.split("/").filter(Boolean);
    const directVideoId =
      hostname === "youtu.be" ? parts[0] : url.searchParams.get("v") ?? undefined;
    const pathVideoId =
      parts[0] && ["shorts", "embed", "live"].includes(parts[0])
        ? parts[1]
        : undefined;
    const candidate = directVideoId ?? pathVideoId;
    return candidate && /^[a-zA-Z0-9_-]{6,}$/.test(candidate)
      ? candidate
      : undefined;
  } catch {
    return undefined;
  }
};

const containsChallengeCode = (
  value: string | undefined | null,
  challengeCode: string,
) =>
  normalizeRequiredText(value)
    .toUpperCase()
    .includes(challengeCode.toUpperCase());

type YoutubeChannelItem = {
  id?: string;
  snippet?: {
    title?: string;
    description?: string;
    customUrl?: string;
    publishedAt?: string;
  };
  statistics?: {
    subscriberCount?: string;
    videoCount?: string;
    viewCount?: string;
    hiddenSubscriberCount?: boolean;
  };
};

type YoutubeVideoItem = {
  id?: string;
  snippet?: {
    channelId?: string;
    channelTitle?: string;
    title?: string;
    description?: string;
    publishedAt?: string;
  };
  status?: {
    privacyStatus?: string;
    uploadStatus?: string;
  };
};

const fetchYoutubeChannelForTarget = async (
  apiKey: string,
  target: ReturnType<typeof parseYoutubeChannelTarget>,
  timeoutMs = 6500,
  includeStatistics = false,
) => {
  const url = new URL("https://www.googleapis.com/youtube/v3/channels");
  url.searchParams.set("part", includeStatistics ? "snippet,statistics" : "snippet");
  url.searchParams.set("key", apiKey);
  if (target.type === "id") {
    url.searchParams.set("id", target.value);
  } else {
    url.searchParams.set(
      "forHandle",
      target.value.startsWith("@") ? target.value : `@${target.value}`,
    );
  }

  return fetchJsonWithTimeout<{
    items?: YoutubeChannelItem[];
    error?: unknown;
  }>(url.toString(), {}, timeoutMs);
};

const fetchYoutubeVideoForProof = async (apiKey: string, videoId: string) => {
  const url = new URL("https://www.googleapis.com/youtube/v3/videos");
  url.searchParams.set("part", "snippet,status");
  url.searchParams.set("id", videoId);
  url.searchParams.set("key", apiKey);

  return fetchJsonWithTimeout<{
    items?: YoutubeVideoItem[];
    error?: unknown;
  }>(url.toString());
};

const runYoutubeAutomationCheck = async ({
  platformUrl,
  platformHandle,
  proofUrl,
  ownershipMethod,
  challengeCode,
}: {
  platformUrl: string;
  platformHandle: string;
  proofUrl?: string;
  ownershipMethod: InfluencerVerificationMethod;
  challengeCode: string;
}): Promise<VerificationAutomationResult> => {
  const checkedAt = new Date().toISOString();
  const plan = buildVerificationAutomationPlan("youtube");
  const apiKey = process.env.YOUTUBE_DATA_API_KEY?.trim();

  if (!apiKey) {
    const publicChallenge = await runPublicChallengeAutomation(
      proofUrl ?? platformUrl,
      challengeCode,
    );
    const expectedHandle = normalizeHandleForComparison(platformHandle);
    const publicProofHandle = extractYoutubeHandle(proofUrl ?? platformUrl);
    const publicProofMatched =
      publicChallenge.status === "matched" &&
      Boolean(expectedHandle) &&
      publicProofHandle === expectedHandle;
    const publicOwnershipCheck = {
      ...publicChallenge,
      status: bindOwnershipStatusToSubmittedIdentity(
        publicChallenge.status,
        publicProofMatched,
      ),
    };

    return {
      ...buildNotConfiguredAutomationResult(
        plan,
        publicChallenge.checked_at,
        publicChallenge.status === "matched"
          ? "YouTube 공개 증빙 URL에서 인증코드를 확인했습니다. API 키가 연결되면 채널 일치 여부까지 자동 확인합니다."
          : "YOUTUBE_DATA_API_KEY가 없어 YouTube 공개 증빙 URL만 확인했습니다. 관리자 검수가 필요합니다.",
      ),
      status:
        publicProofMatched ? "matched" : "not_configured",
      http_status: publicChallenge.http_status,
      matched_fields:
        publicProofMatched ? ["public_url"] : undefined,
      ownership_check: publicOwnershipCheck,
      public_challenge: publicChallenge,
    };
  }

  const target = parseYoutubeChannelTarget(platformUrl, platformHandle);
  if (!target.value) {
    return {
      provider: plan.provider,
      configured: true,
      mode: "api_ready",
      status: "invalid_input",
      checked_at: checkedAt,
      message: "YouTube channel handle or channel id is required.",
      plan,
    };
  }

  try {
    const channelResponse = await fetchYoutubeChannelForTarget(apiKey, target);
    const channel = channelResponse.payload.items?.[0];
    const proofVideoId = parseYoutubeVideoId(proofUrl);
    const videoResponse = proofVideoId
      ? await fetchYoutubeVideoForProof(apiKey, proofVideoId)
      : undefined;
    const video = videoResponse?.payload.items?.[0];
    const expectedHandle = normalizeHandleForComparison(platformHandle);
    const apiHandle = normalizeHandleForComparison(channel?.snippet?.customUrl);
    const submittedAsChannelId = Boolean(
      channel?.id &&
        /^UC[a-zA-Z0-9_-]{20,}$/.test(platformHandle.trim()) &&
        platformHandle.trim() === channel.id,
    );
    const channelIdentityMatches = Boolean(
      expectedHandle &&
        (apiHandle === expectedHandle || submittedAsChannelId),
    );
    const channelDescriptionMatched =
      channelIdentityMatches &&
      containsChallengeCode(channel?.snippet?.description, challengeCode);
    const videoTitleMatched = containsChallengeCode(
      video?.snippet?.title,
      challengeCode,
    );
    const videoDescriptionMatched = containsChallengeCode(
      video?.snippet?.description,
      challengeCode,
    );
    const videoChannelMatches =
      Boolean(channel?.id && video?.snippet?.channelId) &&
      channel?.id === video?.snippet?.channelId;
    const videoProofMatched =
      Boolean(video) &&
      channelIdentityMatches &&
      videoChannelMatches &&
      (videoTitleMatched || videoDescriptionMatched);
    const shouldTryPublicProof =
      !channelDescriptionMatched &&
      !videoProofMatched &&
      ownershipMethod !== "channel_description_code" &&
      hasText(proofUrl);
    const publicChallenge = shouldTryPublicProof
      ? await runPublicChallengeAutomation(proofUrl, challengeCode)
      : undefined;
    const publicProofHandle = extractYoutubeHandle(proofUrl);
    const publicProofMatched = Boolean(
      publicChallenge?.status === "matched" &&
        expectedHandle &&
        apiHandle === expectedHandle &&
        publicProofHandle === expectedHandle,
    );
    const matched =
      channelDescriptionMatched || videoProofMatched || publicProofMatched;
    const ownershipCheck = {
      status: matched ? "matched" : ("not_found" as OwnershipCheckStatus),
      checked_at: publicChallenge?.checked_at ?? checkedAt,
      http_status: videoResponse?.status ?? channelResponse.status,
    };

    return {
      provider: plan.provider,
      configured: true,
      mode: "api_ready",
      status: channelResponse.ok && matched ? "matched" : "not_found",
      checked_at: checkedAt,
      http_status: videoResponse?.status ?? channelResponse.status,
      message:
        channelResponse.ok && matched
          ? videoProofMatched
            ? "YouTube 영상/쇼츠 증빙이 제출 채널과 일치하고 인증코드를 포함합니다."
            : channelDescriptionMatched
              ? "YouTube 채널 설명에서 인증코드를 확인했습니다."
              : "YouTube 공개 증빙 URL에서 인증코드를 확인했습니다."
          : "YouTube 채널 또는 제출 증빙에서 인증코드를 확인하지 못했습니다.",
      ownership_check: {
        ...ownershipCheck,
        status: channelResponse.ok ? ownershipCheck.status : "failed",
      },
      public_challenge: publicChallenge,
      plan,
    };
  } catch (error) {
    return {
      provider: plan.provider,
      configured: true,
      mode: "api_ready",
      status: "failed",
      checked_at: checkedAt,
      message: error instanceof Error ? error.message : "YouTube API check failed.",
      plan,
    };
  }
};

const runNaverBlogAutomationCheck = async ({
  platformHandle,
  platformUrl,
  proofUrl,
  challengeCode,
}: {
  platformHandle: string;
  platformUrl: string;
  proofUrl?: string;
  challengeCode: string;
}): Promise<VerificationAutomationResult> => {
  const checkedAt = new Date().toISOString();
  const plan = buildVerificationAutomationPlan("naver_blog");
  const expectedBlogId =
    extractNaverBlogId(platformHandle) ||
    extractNaverBlogId(platformUrl);
  const publicChallenge = await runPublicChallengeAutomation(proofUrl, challengeCode);
  const proofBlogId = extractNaverBlogId(proofUrl);
  const publicProofMatched =
    publicChallenge.status === "matched" &&
    Boolean(expectedBlogId) &&
    proofBlogId === expectedBlogId;
  const publicOwnershipCheck = {
    ...publicChallenge,
    status: bindOwnershipStatusToSubmittedIdentity(
      publicChallenge.status,
      publicProofMatched,
    ),
  };
  if (publicProofMatched) {
    return {
      provider: plan.provider,
      configured: plan.configured,
      mode: plan.mode,
      status: "matched",
      checked_at: publicChallenge.checked_at,
      http_status: publicChallenge.http_status,
      message: "네이버 블로그 공개 증빙 URL에서 인증코드를 확인했습니다.",
      matched_fields: ["public_url"],
      ownership_check: publicOwnershipCheck,
      public_challenge: publicChallenge,
      profile: {
        blog_id: expectedBlogId || undefined,
        proof_source: "public_url",
      },
      plan,
    };
  }

  const clientId = process.env.NAVER_CLIENT_ID?.trim();
  const clientSecret = process.env.NAVER_CLIENT_SECRET?.trim();
  if (!clientId || !clientSecret) {
    return {
      ...buildNotConfiguredAutomationResult(
        plan,
        publicChallenge.checked_at,
        "NAVER_CLIENT_ID/NAVER_CLIENT_SECRET이 없어 공개 증빙 URL만 확인했습니다. 자동 확인이 막히면 관리자 검수가 필요합니다.",
      ),
      public_challenge: publicChallenge,
      ownership_check: publicOwnershipCheck,
      profile: {
        blog_id: expectedBlogId || undefined,
      },
    };
  }

  try {
    const reservation = await reserveNaverSearchVerificationRequest();
    if (!reservation.allowed) {
      return {
        provider: plan.provider,
        configured: true,
        mode: "manual_fallback",
        status: "blocked",
        checked_at: checkedAt,
        message:
          "네이버 자동 확인을 잠시 사용할 수 없습니다. 공개 증빙을 다시 확인하거나 수기 인증을 요청해 주세요.",
        next_action: "manual_review",
        public_challenge: publicChallenge,
        ownership_check: publicOwnershipCheck,
        profile: {
          blog_id: expectedBlogId || undefined,
        },
        plan,
      };
    }
    const url = new URL("https://openapi.naver.com/v1/search/blog.json");
    url.searchParams.set("query", `${challengeCode} ${expectedBlogId || platformHandle}`);
    url.searchParams.set("display", "10");
    url.searchParams.set("sort", "date");
    const providerReservation =
      await prepareNaverSearchVerificationReservationForFetch({ reservation });
    if (!providerReservation.allowed) {
      return {
        provider: plan.provider,
        configured: true,
        mode: "manual_fallback",
        status: "blocked",
        checked_at: checkedAt,
        message: "NAVER automatic verification is temporarily unavailable.",
        next_action: "manual_review",
        public_challenge: publicChallenge,
        ownership_check: publicOwnershipCheck,
        profile: { blog_id: expectedBlogId || undefined },
        plan,
      };
    }
    const apiResponse = await fetchJsonWithTimeout<{
      items?: Array<{
        title?: string;
        link?: string;
        description?: string;
        bloggername?: string;
        bloggerlink?: string;
      }>;
      errorMessage?: string;
    }>(url.toString(), {
      headers: {
        "X-Naver-Client-Id": clientId,
        "X-Naver-Client-Secret": clientSecret,
        Accept: "application/json",
      },
    }, naverSearchProviderTimeoutMs);
    const items = apiResponse.payload.items ?? [];
    const matchedItem = items.find((item) => {
      const haystack = [
        stripHtmlTags(item.title),
        stripHtmlTags(item.description),
        item.link,
        item.bloggerlink,
        item.bloggername,
      ]
        .filter(Boolean)
        .join(" ");
      const bloggerId = extractNaverBlogId(item.bloggerlink);
      const linkBlogId = extractNaverBlogId(item.link);
      const handleMatches = Boolean(
        expectedBlogId &&
          (bloggerId === expectedBlogId || linkBlogId === expectedBlogId),
      );
      return containsChallengeCode(haystack, challengeCode) && handleMatches;
    });

    return {
      provider: plan.provider,
      configured: true,
      mode: "api_ready",
      status: apiResponse.ok && matchedItem ? "matched" : "not_found",
      checked_at: checkedAt,
      http_status: apiResponse.status,
      message: matchedItem
        ? "네이버 블로그 검색 API에서 제출 블로그의 인증코드를 확인했습니다."
        : "네이버 블로그 검색 API에서 제출 블로그의 인증코드를 찾지 못했습니다.",
      ownership_check: {
        status: apiResponse.ok && matchedItem ? "matched" : "not_found",
        checked_at: checkedAt,
        http_status: apiResponse.status,
      },
      public_challenge: publicChallenge,
      plan,
    };
  } catch (error) {
    return {
      provider: plan.provider,
      configured: true,
      mode: "api_ready",
      status: "failed",
      checked_at: checkedAt,
      message: error instanceof Error ? error.message : "Naver blog API check failed.",
      public_challenge: publicChallenge,
      ownership_check: publicOwnershipCheck,
      plan,
    };
  }
};

const runInstagramAutomationCheck = async ({
  platformHandle,
  proofUrl,
  challengeCode,
}: {
  platformHandle: string;
  proofUrl?: string;
  challengeCode: string;
}): Promise<VerificationAutomationResult> => {
  const checkedAt = new Date().toISOString();
  const plan = buildVerificationAutomationPlan("instagram");
  const accessToken = process.env.META_GRAPH_ACCESS_TOKEN?.trim();
  const igUserId = process.env.META_IG_USER_ID?.trim();
  const graphVersion = process.env.META_GRAPH_API_VERSION?.trim() || "v24.0";
  const username = normalizeHandleForComparison(platformHandle).replace(/[^a-z0-9._]/g, "");
  const publicChallenge = await runPublicChallengeAutomation(proofUrl, challengeCode);

  if (!accessToken || !igUserId) {
    return {
      ...buildNotConfiguredAutomationResult(
        plan,
        publicChallenge.checked_at,
        publicChallenge.status === "matched"
          ? "Instagram 공개 증빙 URL에서 인증코드를 확인했습니다. Graph API 연결 전에는 관리자 검수와 함께 사용합니다."
          : "Instagram Graph API가 없어 공개 증빙 URL만 확인했습니다. Instagram이 접근을 막으면 스크린샷 검수가 필요합니다.",
      ),
      status:
        publicChallenge.status === "matched" ? "matched" : "not_configured",
      http_status: publicChallenge.http_status,
      matched_fields:
        publicChallenge.status === "matched" ? ["public_url"] : undefined,
      public_challenge: publicChallenge,
      ownership_check: publicChallenge,
      profile: {
        username: username || undefined,
        proof_source:
          publicChallenge.status === "matched" ? "public_url" : undefined,
      },
    };
  }
  if (!username) {
    return {
      provider: plan.provider,
      configured: true,
      mode: "api_ready",
      status: "invalid_input",
      checked_at: checkedAt,
      message: "Instagram username is required.",
      plan,
    };
  }

  try {
    const url = new URL(`https://graph.facebook.com/${graphVersion}/${igUserId}`);
    url.searchParams.set(
      "fields",
      `business_discovery.username(${username}){id,username,followers_count,media_count,biography,website,profile_picture_url}`,
    );
    url.searchParams.set("access_token", accessToken);
    const apiResponse = await fetchJsonWithTimeout<{
      business_discovery?: {
        id?: string;
        username?: string;
        followers_count?: number;
        media_count?: number;
        biography?: string;
        website?: string;
        profile_picture_url?: string;
      };
      error?: { code?: string; message?: string; log_id?: string };
    }>(url.toString());
    const profile = apiResponse.payload.business_discovery;
    const bioMatched = containsChallengeCode(profile?.biography, challengeCode);
    const publicMatched = publicChallenge.status === "matched";
    const matched = bioMatched || publicMatched;

    return {
      provider: plan.provider,
      configured: true,
      mode: "api_ready",
      status: apiResponse.ok && matched ? "matched" : "not_found",
      checked_at: publicMatched ? publicChallenge.checked_at : checkedAt,
      http_status: apiResponse.status,
      result_hash: sha256Hex(
        JSON.stringify({
          graph: apiResponse.payload,
          public_challenge: publicChallenge,
        }),
      ),
      message: matched
        ? bioMatched
          ? "Instagram Graph API에서 프로필 소개의 인증코드를 확인했습니다."
          : "Instagram 공개 증빙 URL에서 인증코드를 확인했습니다."
        : "Instagram 프로필 또는 공개 증빙에서 인증코드를 확인하지 못했습니다.",
      matched_fields: [
        bioMatched ? "business_discovery.biography" : undefined,
        publicMatched ? "public_url" : undefined,
      ].filter((value): value is string => Boolean(value)),
      ownership_check: {
        status: apiResponse.ok && matched ? "matched" : "not_found",
        checked_at: publicMatched ? publicChallenge.checked_at : checkedAt,
        http_status: apiResponse.status,
      },
      public_challenge: publicChallenge,
      profile: profile
        ? {
            id: profile.id,
            username: profile.username,
            followers_count: profile.followers_count,
            media_count: profile.media_count,
            website: profile.website,
            proof_source: bioMatched
              ? "instagram_graph_api"
              : publicMatched
                ? "public_url"
                : undefined,
          }
        : {
            username,
            proof_source: publicMatched ? "public_url" : undefined,
          },
      plan,
    };
  } catch (error) {
    const publicFallback = publicChallenge.status === "matched";
    return {
      provider: plan.provider,
      configured: true,
      mode: "api_ready",
      status: publicFallback ? "matched" : "failed",
      checked_at: publicFallback ? publicChallenge.checked_at : checkedAt,
      message: publicFallback
        ? "Instagram Graph API 확인은 실패했지만 공개 증빙 URL에서 인증코드를 확인했습니다."
        : error instanceof Error
          ? error.message
          : "Instagram API check failed.",
      matched_fields: publicFallback ? ["public_url"] : undefined,
      public_challenge: publicChallenge,
      ownership_check: publicChallenge,
      profile: {
        username,
        proof_source: publicFallback ? "public_url" : undefined,
      },
      plan,
    };
  }
};

const isInstagramDmWebhookConfigured = () =>
  Boolean(
    process.env.META_WEBHOOK_VERIFY_TOKEN?.trim() &&
      process.env.META_APP_SECRET?.trim() &&
      process.env.META_IG_USER_ID?.trim() &&
      metaInstagramAccessToken,
  );

const isInstagramDmAccessTokenCurrent = () => {
  if (!metaInstagramAccessTokenExpiresAt) return false;
  const expiresAt = new Date(metaInstagramAccessTokenExpiresAt).getTime();
  return Number.isFinite(expiresAt) && expiresAt > Date.now();
};

const isInstagramDmAutomationReady = () =>
  isInstagramDmWebhookConfigured() &&
  isInstagramDmAccessTokenCurrent() &&
  instagramDmAutoApproveEnabled;

const runInstagramDmWebhookCheck = (
  challengeCodeHash: string,
): VerificationAutomationResult => {
  const checkedAt = new Date().toISOString();
  const plan = buildVerificationAutomationPlan("instagram");
  const webhookConfigured = isInstagramDmWebhookConfigured();

  return {
    provider: "instagram_messaging_webhook",
    configured: webhookConfigured,
    mode: webhookConfigured ? "webhook_ready" : "manual_fallback",
    status: "pending",
    checked_at: checkedAt,
    message: "Waiting for the signed inbound Instagram DM webhook.",
    next_action: "Keep the challenge active while the server checks the webhook.",
    matched_fields: [],
    ownership_check: {
      status: "not_run",
      checked_at: checkedAt,
    },
    profile: {
      challenge_code_hash: challengeCodeHash,
      review_channel: "instagram_dm",
      webhook_configured: webhookConfigured,
    },
    plan,
  };
};

const runTikTokAutomationCheck = async ({
  platformHandle,
  proofUrl,
  challengeCode,
  accessToken,
}: {
  platformHandle: string;
  proofUrl?: string;
  challengeCode: string;
  accessToken?: string;
}): Promise<VerificationAutomationResult> => {
  const checkedAt = new Date().toISOString();
  const plan = buildVerificationAutomationPlan("tiktok");
  const submittedUserAccessToken = accessToken?.trim();
  const token =
    submittedUserAccessToken || process.env.TIKTOK_ACCOUNT_ACCESS_TOKEN?.trim();
  const publicChallenge = await runPublicChallengeAutomation(proofUrl, challengeCode);
  const expectedHandle = normalizeHandleForComparison(platformHandle);
  const publicProofHandle = extractTikTokUsername(proofUrl);
  const publicProofMatched =
    publicChallenge.status === "matched" &&
    Boolean(expectedHandle) &&
    publicProofHandle === expectedHandle;
  const publicOwnershipCheck = {
    ...publicChallenge,
    status: bindOwnershipStatusToSubmittedIdentity(
      publicChallenge.status,
      publicProofMatched,
    ),
  };

  if (!token) {
    return {
      ...buildNotConfiguredAutomationResult(
        plan,
        publicChallenge.checked_at,
        publicChallenge.status === "matched"
          ? "TikTok 공개 증빙 URL에서 인증코드를 확인했습니다. OAuth 연결 전에는 관리자 검수와 함께 사용합니다."
          : "TikTok OAuth 토큰이 없어 공개 증빙 URL만 확인했습니다. TikTok이 접근을 막으면 스크린샷 검수가 필요합니다.",
      ),
      status:
        publicProofMatched ? "matched" : "not_configured",
      http_status: publicChallenge.http_status,
      matched_fields:
        publicProofMatched ? ["public_url"] : undefined,
      public_challenge: publicChallenge,
      ownership_check: publicOwnershipCheck,
      profile: {
        username: normalizeHandleForComparison(platformHandle) || undefined,
        proof_source:
          publicProofMatched ? "public_url" : undefined,
      },
    };
  }

  try {
    const url = new URL("https://open.tiktokapis.com/v2/user/info/");
    url.searchParams.set(
      "fields",
      [
        "open_id",
        "union_id",
        "display_name",
        "username",
        "bio_description",
        "profile_deep_link",
        "is_verified",
        "follower_count",
        "following_count",
        "likes_count",
        "video_count",
      ].join(","),
    );
    const apiResponse = await fetchJsonWithTimeout<{
      data?: {
        user?: {
          open_id?: string;
          union_id?: string;
          display_name?: string;
          username?: string;
          bio_description?: string;
          profile_deep_link?: string;
          is_verified?: boolean;
          follower_count?: number;
          following_count?: number;
          likes_count?: number;
          video_count?: number;
        };
      };
      error?: { code?: string; message?: string; log_id?: string };
    }>(url.toString(), {
      headers: {
        Authorization: `Bearer ${token}`,
        Accept: "application/json",
      },
    });
    const user = apiResponse.payload.data?.user;
    const tikTokErrorCode = normalizeRequiredText(apiResponse.payload.error?.code);
    const userInfoApiSucceeded =
      apiResponse.ok && (!tikTokErrorCode || tikTokErrorCode === "ok");
    const userHandle = normalizeHandleForComparison(user?.username);
    const handleMatches = expectedHandle ? expectedHandle === userHandle : true;
    const bioMatched = Boolean(
      handleMatches && containsChallengeCode(user?.bio_description, challengeCode),
    );
    const publicMatched = publicProofMatched;
    const matched = bioMatched || publicMatched;

    return {
      provider: plan.provider,
      configured: true,
      mode: "api_ready",
      status: userInfoApiSucceeded && matched ? "matched" : "not_found",
      checked_at: checkedAt,
      http_status: apiResponse.status,
      result_hash: sha256Hex(
        JSON.stringify({
          user_info: apiResponse.payload,
          public_challenge: publicChallenge,
        }),
      ),
      message: matched
        ? bioMatched
          ? "TikTok OAuth 사용자 정보에서 핸들과 프로필 소개 인증코드를 확인했습니다."
          : "TikTok 공개 증빙 URL에서 인증코드를 확인했습니다."
        : "TikTok OAuth 사용자 정보 또는 공개 증빙에서 인증코드를 확인하지 못했습니다.",
      matched_fields: [
        bioMatched ? "data.user.username" : undefined,
        bioMatched ? "data.user.bio_description" : undefined,
        publicMatched ? "public_url" : undefined,
      ].filter((value): value is string => Boolean(value)),
      ownership_check: {
        status: userInfoApiSucceeded && matched ? "matched" : "not_found",
        checked_at: publicMatched ? publicChallenge.checked_at : checkedAt,
        http_status: apiResponse.status,
      },
      public_challenge: publicChallenge,
      profile: user
        ? {
            user_info_api_succeeded: userInfoApiSucceeded,
            oauth_token_source: submittedUserAccessToken
              ? "submitted_user_access_token"
              : "server_fallback",
            open_id_hash: user.open_id ? sha256Hex(user.open_id) : undefined,
            union_id_hash: user.union_id ? sha256Hex(user.union_id) : undefined,
            display_name: user.display_name,
            username: user.username,
            profile_deep_link: user.profile_deep_link,
            is_verified: user.is_verified,
            follower_count: user.follower_count,
            following_count: user.following_count,
            likes_count: user.likes_count,
            video_count: user.video_count,
            proof_source: bioMatched
              ? "tiktok_oauth"
              : publicMatched
                ? "public_url"
                : undefined,
          }
        : {
            username: expectedHandle || undefined,
            proof_source: publicMatched ? "public_url" : undefined,
          },
      plan,
    };
  } catch (error) {
    const publicFallback = publicProofMatched;
    return {
      provider: plan.provider,
      configured: true,
      mode: "api_ready",
      status: publicFallback ? "matched" : "failed",
      checked_at: publicFallback ? publicChallenge.checked_at : checkedAt,
      message: publicFallback
        ? "TikTok OAuth 확인은 실패했지만 공개 증빙 URL에서 인증코드를 확인했습니다."
        : error instanceof Error
          ? error.message
          : "TikTok API check failed.",
      matched_fields: publicFallback ? ["public_url"] : undefined,
      public_challenge: publicChallenge,
      ownership_check: publicOwnershipCheck,
      profile: {
        username: normalizeHandleForComparison(platformHandle) || undefined,
        proof_source: publicFallback ? "public_url" : undefined,
      },
      plan,
    };
  }
};

const runPlatformAccountAutomationCheck = async ({
  platform,
  platformHandle,
  platformUrl,
  proofUrl,
  ownershipMethod,
  challengeCode,
  platformAccessToken,
}: {
  platform: InfluencerPlatform;
  platformHandle: string;
  platformUrl: string;
  proofUrl?: string;
  ownershipMethod: InfluencerVerificationMethod;
  challengeCode: string;
  platformAccessToken?: string;
}): Promise<VerificationAutomationResult> => {
  const checkedAt = new Date().toISOString();
  const plan = buildVerificationAutomationPlan(platform);

  if (platform === "instagram" && ownershipMethod === "instagram_dm_code") {
    return runInstagramDmWebhookCheck(hashInstagramDmChallengeCode(challengeCode));
  }

  if (ownershipMethod === "screenshot_review") {
    return {
      provider: plan.provider,
      configured: plan.configured,
      mode: plan.mode,
      status: "blocked",
      checked_at: checkedAt,
      message: "Screenshot review cannot be fully automated.",
      next_action: "Operator must review the submitted evidence file.",
      ownership_check: { status: "not_run", checked_at: checkedAt },
      plan,
    };
  }

  if (platform === "youtube") {
    const apiResult = await runYoutubeAutomationCheck({
      platformUrl,
      platformHandle,
      proofUrl,
      ownershipMethod,
      challengeCode,
    });
    return apiResult;
  }

  if (platform === "naver_blog") {
    return runNaverBlogAutomationCheck({
      platformHandle,
      platformUrl,
      proofUrl,
      challengeCode,
    });
  }

  if (platform === "instagram") {
    return runInstagramAutomationCheck({ platformHandle, proofUrl, challengeCode });
  }

  if (platform === "tiktok") {
    return runTikTokAutomationCheck({
      platformHandle,
      proofUrl,
      challengeCode,
      accessToken: platformAccessToken,
    });
  }

  const publicChallenge = await runPublicChallengeAutomation(proofUrl, challengeCode);
  return {
    provider: plan.provider,
    configured: false,
    mode: plan.mode,
    status: publicChallenge.status === "matched" ? "matched" : "not_configured",
    checked_at: publicChallenge.checked_at,
    http_status: publicChallenge.http_status,
    message:
      publicChallenge.status === "matched"
        ? "Public proof URL contains the challenge code."
        : "No platform API is configured; operator review is required.",
    ownership_check: publicChallenge,
    public_challenge: publicChallenge,
    plan,
  };
};

export const parseEvidenceFile = (value: unknown) => {
  if (!value || typeof value !== "object") return undefined;

  const input = value as {
    name?: unknown;
    type?: unknown;
    size?: unknown;
    data_url?: unknown;
  };
  const name = normalizeRequiredText(input.name);
  const type = normalizeRequiredText(input.type);
  const size = input.size;
  const dataUrl = normalizeRequiredText(input.data_url);

  if (
    !name ||
    !type ||
    typeof size !== "number" ||
    !Number.isSafeInteger(size) ||
    !dataUrl
  ) {
    return undefined;
  }

  return {
    name,
    type,
    size,
    data_url: dataUrl,
  };
};

export const validateEvidenceFile = (
  file: ReturnType<typeof parseEvidenceFile> | undefined,
) => {
  if (!file) return "Verification evidence file is required";
  if (
    file.name.length > 255 ||
    Array.from(file.name).some((character) => {
      const codePoint = character.codePointAt(0) ?? 0;
      return codePoint <= 31 || codePoint === 127;
    })
  ) {
    return "Verification evidence filename must be 255 characters or fewer";
  }
  if (!evidenceFileMimeTypes.has(file.type)) {
    return "Only PDF, PNG, JPG, or WebP files are allowed";
  }
  if (file.size <= 0 || file.size > maxVerificationFileSize) {
    return "Verification evidence file must be 10MB or smaller";
  }
  if (!file.data_url.startsWith("data:")) {
    return "Verification evidence file is invalid";
  }

  try {
    const { contentType, buffer } = dataUrlToBuffer(file.data_url);
    if (
      contentType !== file.type ||
      buffer.byteLength !== file.size ||
      !assertDeclaredMimeMatchesContent(contentType, buffer, evidenceFileMimeTypes)
    ) {
      return "Verification evidence file metadata does not match its content";
    }
  } catch {
    return "Verification evidence file is invalid";
  }

  return undefined;
};

const dataUrlToBuffer = (dataUrl: string) => {
  const match = dataUrl.match(/^data:([^;,]+)(;base64)?,([\s\S]*)$/);
  if (!match) {
    throw new Error("Evidence file data is invalid");
  }

  const contentType = match[1];
  const isBase64 = Boolean(match[2]);
  const payload = match[3];
  if (
    isBase64 &&
    (!/^[A-Za-z0-9+/]*={0,2}$/.test(payload) || payload.length % 4 !== 0)
  ) {
    throw new Error("Evidence file data is invalid");
  }
  const buffer = isBase64
    ? Buffer.from(payload, "base64")
    : Buffer.from(decodeURIComponent(payload), "utf8");

  return { contentType, buffer };
};

const detectAllowedFileMimeType = (buffer: Buffer) => {
  if (buffer.length >= 4 && buffer.subarray(0, 4).toString("ascii") === "%PDF") {
    return "application/pdf";
  }
  if (
    buffer.length >= 8 &&
    buffer[0] === 0x89 &&
    buffer[1] === 0x50 &&
    buffer[2] === 0x4e &&
    buffer[3] === 0x47 &&
    buffer[4] === 0x0d &&
    buffer[5] === 0x0a &&
    buffer[6] === 0x1a &&
    buffer[7] === 0x0a
  ) {
    return "image/png";
  }
  if (buffer.length >= 3 && buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff) {
    return "image/jpeg";
  }
  if (
    buffer.length >= 12 &&
    buffer.subarray(0, 4).toString("ascii") === "RIFF" &&
    buffer.subarray(8, 12).toString("ascii") === "WEBP"
  ) {
    return "image/webp";
  }
  return undefined;
};

const assertDeclaredMimeMatchesContent = (
  declaredType: string,
  buffer: Buffer,
  allowedTypes: ReadonlySet<string>,
) => {
  const detectedType = detectAllowedFileMimeType(buffer);
  return (
    allowedTypes.has(declaredType) &&
    detectedType === declaredType
  );
};

const sanitizeStorageSegment = (value: string) =>
  value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9._-]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 80) || "file";

const extensionForMimeType = (mimeType: string) => {
  if (mimeType === "application/pdf") return "pdf";
  if (mimeType === "image/png") return "png";
  if (mimeType === "image/jpeg") return "jpg";
  if (mimeType === "image/webp") return "webp";
  return "bin";
};

const buildPrivateStoragePath = ({
  area,
  ownerId,
  fileId,
  fileName,
  mimeType,
}: {
  area: string;
  ownerId: string;
  fileId: string;
  fileName: string;
  mimeType: string;
}) => {
  const extension = extensionForMimeType(mimeType);
  const baseName = sanitizeStorageSegment(fileName.replace(/\.[^.]+$/, ""));
  return `${sanitizeStorageSegment(area)}/${sanitizeStorageSegment(
    ownerId,
  )}/${sanitizeStorageSegment(fileId)}-${baseName}.${extension}`;
};

const ensurePrivateStorageBucket = async (allowCreate = true) => {
  if (!useSupabase) return;

  const checkResponse = await fetch(
    supabaseStorageUrl(`/bucket/${encodeURIComponent(privateStorageBucket)}`),
    { headers: supabaseStorageHeaders() },
  );

  if (checkResponse.ok) {
    const bucket = (await checkResponse.json()) as {
      public?: unknown;
      file_size_limit?: unknown;
      allowed_mime_types?: unknown;
    };
    const fileSizeLimit = Number(bucket.file_size_limit);
    const allowedMimeTypes = Array.isArray(bucket.allowed_mime_types)
      ? new Set(
          bucket.allowed_mime_types.filter(
            (value): value is string => typeof value === "string",
          ),
        )
      : new Set<string>();
    const bucketIsPrivateAndBounded =
      bucket.public === false &&
      Number.isFinite(fileSizeLimit) &&
      fileSizeLimit > 0 &&
      fileSizeLimit === maxVerificationFileSize &&
      allowedMimeTypes.size === evidenceFileMimeTypes.size &&
      Array.from(evidenceFileMimeTypes).every((type) =>
        allowedMimeTypes.has(type),
      );
    if (!bucketIsPrivateAndBounded) {
      throw new Error("Supabase private storage bucket security policy mismatch");
    }
    return;
  }
  const checkBody = await checkResponse.text();
  const bucketMissing =
    checkResponse.status === 404 ||
    (checkResponse.status === 400 &&
      (checkBody.includes('"statusCode":"404"') ||
        checkBody.toLowerCase().includes("bucket not found")));

  if (!bucketMissing) {
    throw new Error(
      `Supabase storage bucket check failed (${checkResponse.status})`,
    );
  }

  if (!allowCreate) {
    throw new Error("Supabase private storage bucket creation could not be verified");
  }

  const createResponse = await fetch(supabaseStorageUrl("/bucket"), {
    method: "POST",
    headers: supabaseStorageHeaders("application/json"),
    body: JSON.stringify({
      id: privateStorageBucket,
      name: privateStorageBucket,
      public: false,
      file_size_limit: maxVerificationFileSize,
      allowed_mime_types: Array.from(evidenceFileMimeTypes),
    }),
  });

  if (!createResponse.ok && createResponse.status !== 409) {
    throw new Error(
      `Supabase storage bucket create failed (${createResponse.status})`,
    );
  }
  await ensurePrivateStorageBucket(false);
};

const uploadSupabasePrivateFile = async ({
  objectPath,
  contentType,
  buffer,
}: {
  objectPath: string;
  contentType: string;
  buffer: Buffer;
}) => {
  await ensurePrivateStorageBucket();

  const response = await fetch(
    supabaseStorageUrl(
      `/object/${encodeURIComponent(privateStorageBucket)}/${objectPath}`,
    ),
    {
      method: "POST",
      headers: {
        ...supabaseStorageHeaders(contentType),
        "x-upsert": "false",
      },
      body: buffer,
    },
  );

  if (!response.ok) {
    throw new Error(`Supabase storage upload failed (${response.status})`);
  }
};

const storePrivateBuffer = async ({
  area,
  ownerId,
  fileId,
  fileName,
  contentType,
  buffer,
}: {
  area: string;
  ownerId: string;
  fileId: string;
  fileName: string;
  contentType: string;
  buffer: Buffer;
}): Promise<StoredPrivateFile> => {
  const objectPath = buildPrivateStoragePath({
    area,
    ownerId,
    fileId,
    fileName,
    mimeType: contentType,
  });
  const sha256 = createHash("sha256").update(buffer).digest("hex");
  const storedAt = new Date().toISOString();

  if (useSupabase) {
    try {
      await uploadSupabasePrivateFile({ objectPath, contentType, buffer });
      return {
        provider: "supabase_storage",
        bucket: privateStorageBucket,
        path: objectPath,
        file_name: fileName,
        content_type: contentType,
        byte_size: buffer.byteLength,
        sha256,
        stored_at: storedAt,
      };
    } catch (error) {
      if (!allowLocalPrivateFileFallback) {
        throw error;
      }
      console.warn(
        `[${productName}] Supabase Storage unavailable, storing private file locally: ${
          operationalErrorLabel(error)
        }`,
      );
    }
  }

  if (!allowLocalPrivateFileFallback) {
    throw new Error(
      "Private file storage requires Supabase Storage in production. Set Supabase storage env vars or enable demo mode for non-production testing.",
    );
  }

  const absolutePath = path.resolve(privateFilesDir, objectPath);
  if (!absolutePath.startsWith(path.resolve(privateFilesDir))) {
    throw new Error("Private file path is invalid");
  }

  await fs.mkdir(path.dirname(absolutePath), { recursive: true });
  await fs.writeFile(absolutePath, buffer);

  return {
    provider: "local_file",
    bucket: "local",
    path: objectPath,
    file_name: fileName,
    content_type: contentType,
    byte_size: buffer.byteLength,
    sha256,
    stored_at: storedAt,
  };
};

const storeEvidenceFile = async ({
  requestId,
  ownerId,
  area,
  file,
}: {
  requestId: string;
  ownerId: string;
  area: string;
  file: NonNullable<ReturnType<typeof parseEvidenceFile>>;
}) => {
  const { contentType, buffer } = dataUrlToBuffer(file.data_url);

  if (
    contentType !== file.type ||
    !assertDeclaredMimeMatchesContent(contentType, buffer, evidenceFileMimeTypes)
  ) {
    throw new Error("Evidence file content type is invalid");
  }
  if (
    buffer.byteLength <= 0 ||
    buffer.byteLength > maxVerificationFileSize ||
    buffer.byteLength !== file.size
  ) {
    throw new Error("Evidence file size is invalid");
  }

  return storePrivateBuffer({
    area,
    ownerId,
    fileId: requestId,
    fileName: file.name,
    contentType,
    buffer,
  });
};

const validateMarketplaceImageFile = (
  file: ReturnType<typeof parseEvidenceFile> | undefined,
) => {
  if (!file) return "Image file is required";
  if (!marketplaceImageMimeTypes.has(file.type)) {
    return "Only PNG, JPG, or WebP images are allowed";
  }
  if (file.size <= 0 || file.size > maxMarketplaceImageSize) {
    return "Image file must be 3MB or smaller";
  }
  if (!file.data_url.startsWith("data:")) {
    return "Image file is invalid";
  }

  return undefined;
};

const buildMarketplacePublicStoragePath = ({
  area,
  ownerId,
  fileId,
  fileName,
  mimeType,
}: {
  area: string;
  ownerId: string;
  fileId: string;
  fileName: string;
  mimeType: string;
}) => {
  const extension = extensionForMimeType(mimeType);
  const baseName = sanitizeStorageSegment(fileName.replace(/\.[^.]+$/, ""));
  return `${sanitizeStorageSegment(area)}/${sanitizeStorageSegment(
    ownerId,
  )}/${sanitizeStorageSegment(fileId)}-${baseName}.${extension}`;
};

const isAllowedPrivateStorageObjectPath = (value: string) => {
  if (!value || value.includes("\\") || value.startsWith("/")) return false;
  const segments = value.split("/");
  if (segments.length !== 3 || segments.some((segment) => !segment)) return false;
  if (!privateStorageAreas.has(segments[0])) return false;
  return segments.every(
    (segment) =>
      segment !== "." &&
      segment !== ".." &&
      /^[a-z0-9._-]+$/.test(segment),
  );
};

const isAllowedMarketplaceStorageObjectPath = (value: string) => {
  if (!value || value.includes("\\") || value.startsWith("/")) return false;
  const segments = value.split("/");
  if (segments.length !== 3 || segments.some((segment) => !segment)) return false;
  return segments.every(
    (segment) =>
      segment !== "." &&
      segment !== ".." &&
      /^[a-z0-9._-]+$/.test(segment),
  );
};

const deleteQueuedSupabaseStorageObject = async ({
  bucket,
  objectPath,
  signal,
}: {
  bucket: string;
  objectPath: string;
  signal?: AbortSignal;
}) => {
  const allowed =
    (bucket === privateStorageBucket &&
      isAllowedPrivateStorageObjectPath(objectPath)) ||
    (bucket === marketplacePublicStorageBucket &&
      isAllowedMarketplaceStorageObjectPath(objectPath));
  if (!allowed) {
    throw new Error("Privacy storage deletion target is outside the allowlist");
  }

  const encodedPath = objectPath
    .split("/")
    .map((segment) => encodeURIComponent(segment))
    .join("/");
  const deletionResponse = await fetch(
    supabaseStorageUrl(
      `/object/${encodeURIComponent(bucket)}/${encodedPath}`,
    ),
    {
      method: "DELETE",
      headers: supabaseStorageHeaders(),
      signal: signal ?? createSupabaseTimeoutSignal(),
    },
  );
  if (!deletionResponse.ok && deletionResponse.status !== 404) {
    throw new Error(
      `Supabase privacy storage deletion failed (${deletionResponse.status})`,
    );
  }
};

const enqueueVerificationStorageCompensation = ({
  requestId,
  bucket,
  objectPath,
}: {
  requestId: string;
  bucket: string;
  objectPath: string;
}) =>
  callSupabaseRpc<{ queued: boolean; queue_id: string }>(
    "enqueue_verification_storage_compensation",
    {
      p_request_id: requestId,
      p_bucket: bucket,
      p_object_path: objectPath,
      p_error_code: "verification_insert_failed",
    },
    "verification storage compensation enqueue",
  );

export const compensateFailedVerificationEvidenceInsert = async ({
  requestId,
  storedFile,
  deleteSupabaseObject = deleteQueuedSupabaseStorageObject,
  enqueueSupabaseDeletion = enqueueVerificationStorageCompensation,
  deleteLocalObject = async (objectPath: string) => {
    if (!isAllowedPrivateStorageObjectPath(objectPath)) {
      throw new Error("Local verification compensation target is outside the allowlist");
    }
    const root = path.resolve(privateFilesDir);
    const absolutePath = path.resolve(root, objectPath);
    if (!absolutePath.startsWith(`${root}${path.sep}`)) {
      throw new Error("Local verification compensation target is invalid");
    }
    await fs.unlink(absolutePath).catch((error: NodeJS.ErrnoException) => {
      if (error.code !== "ENOENT") throw error;
    });
  },
}: {
  requestId: string;
  storedFile: StoredPrivateFile;
  deleteSupabaseObject?: typeof deleteQueuedSupabaseStorageObject;
  enqueueSupabaseDeletion?: typeof enqueueVerificationStorageCompensation;
  deleteLocalObject?: (objectPath: string) => Promise<void>;
}) => {
  if (storedFile.provider === "local_file") {
    await deleteLocalObject(storedFile.path);
    return { deleted: true, queued: false };
  }
  try {
    await deleteSupabaseObject({
      bucket: storedFile.bucket,
      objectPath: storedFile.path,
    });
    return { deleted: true, queued: false };
  } catch (deleteError) {
    try {
      const queued = await enqueueSupabaseDeletion({
        requestId,
        bucket: storedFile.bucket,
        objectPath: storedFile.path,
      });
      if (!queued?.queued) {
        throw new Error("Verification storage compensation was not queued", {
          cause: deleteError,
        });
      }
      return { deleted: false, queued: true };
    } catch (queueError) {
      throw new AggregateError(
        [deleteError, queueError],
        "Verification evidence compensation failed",
        { cause: queueError },
      );
    }
  }
};

const marketplacePublicObjectUrl = (objectPath: string) => {
  if (!supabaseUrl) return undefined;
  const encodedPath = objectPath.split("/").map(encodeURIComponent).join("/");
  return `${supabaseUrl}/storage/v1/object/public/${encodeURIComponent(
    marketplacePublicStorageBucket,
  )}/${encodedPath}`;
};

const ensureMarketplacePublicStorageBucket = async (allowCreate = true) => {
  if (!useSupabase) return;

  const checkResponse = await fetch(
    supabaseStorageUrl(
      `/bucket/${encodeURIComponent(marketplacePublicStorageBucket)}`,
    ),
    { headers: supabaseStorageHeaders() },
  );

  if (checkResponse.ok) {
    const bucket = (await checkResponse.json()) as {
      public?: unknown;
      file_size_limit?: unknown;
      allowed_mime_types?: unknown;
    };
    const fileSizeLimit = Number(bucket.file_size_limit);
    const allowedMimeTypes = Array.isArray(bucket.allowed_mime_types)
      ? new Set(
          bucket.allowed_mime_types.filter(
            (value): value is string => typeof value === "string",
          ),
        )
      : new Set<string>();
    const bucketIsPublicAndImageOnly =
      bucket.public === true &&
      Number.isFinite(fileSizeLimit) &&
      fileSizeLimit > 0 &&
      fileSizeLimit === maxMarketplaceImageSize &&
      allowedMimeTypes.size === marketplaceImageMimeTypes.size &&
      Array.from(marketplaceImageMimeTypes).every((type) =>
        allowedMimeTypes.has(type),
      );
    if (!bucketIsPublicAndImageOnly) {
      throw new Error("Supabase public storage bucket security policy mismatch");
    }
    return;
  }
  const checkBody = await checkResponse.text();
  const bucketMissing =
    checkResponse.status === 404 ||
    (checkResponse.status === 400 &&
      (checkBody.includes('"statusCode":"404"') ||
        checkBody.toLowerCase().includes("bucket not found")));

  if (!bucketMissing) {
    throw new Error(
      `Supabase public storage bucket check failed (${checkResponse.status})`,
    );
  }

  if (!allowCreate) {
    throw new Error("Supabase public storage bucket creation could not be verified");
  }

  const createResponse = await fetch(supabaseStorageUrl("/bucket"), {
    method: "POST",
    headers: supabaseStorageHeaders("application/json"),
    body: JSON.stringify({
      id: marketplacePublicStorageBucket,
      name: marketplacePublicStorageBucket,
      public: true,
      file_size_limit: maxMarketplaceImageSize,
      allowed_mime_types: Array.from(marketplaceImageMimeTypes),
    }),
  });

  if (!createResponse.ok && createResponse.status !== 409) {
    throw new Error(
      `Supabase public storage bucket create failed (${createResponse.status})`,
    );
  }
  await ensureMarketplacePublicStorageBucket(false);
};

const uploadSupabaseMarketplacePublicImage = async ({
  objectPath,
  contentType,
  buffer,
}: {
  objectPath: string;
  contentType: string;
  buffer: Buffer;
}) => {
  await ensureMarketplacePublicStorageBucket();

  const response = await fetch(
    supabaseStorageUrl(
      `/object/${encodeURIComponent(marketplacePublicStorageBucket)}/${objectPath}`,
    ),
    {
      method: "POST",
      headers: {
        ...supabaseStorageHeaders(contentType),
        "x-upsert": "true",
      },
      body: buffer,
    },
  );

  if (!response.ok) {
    throw new Error(
      `Supabase public storage upload failed (${response.status})`,
    );
  }
};

const storeMarketplacePublicImage = async ({
  area,
  ownerId,
  file,
}: {
  area: string;
  ownerId: string;
  file: NonNullable<ReturnType<typeof parseEvidenceFile>>;
}) => {
  const { contentType, buffer } = dataUrlToBuffer(file.data_url);

  if (
    contentType !== file.type ||
    !assertDeclaredMimeMatchesContent(contentType, buffer, marketplaceImageMimeTypes)
  ) {
    throw new Error("Image file content type is invalid");
  }
  if (buffer.byteLength <= 0 || buffer.byteLength > maxMarketplaceImageSize) {
    throw new Error("Image file size is invalid");
  }

  const objectPath = buildMarketplacePublicStoragePath({
    area,
    ownerId,
    fileId: randomUUID(),
    fileName: file.name,
    mimeType: contentType,
  });

  if (useSupabase) {
    try {
      await uploadSupabaseMarketplacePublicImage({
        objectPath,
        contentType,
        buffer,
      });
      const publicUrl = marketplacePublicObjectUrl(objectPath);
      if (publicUrl) return publicUrl;
    } catch (error) {
      if (!allowLocalMarketplacePublicFileFallback) {
        throw error;
      }
      console.warn(
        `[${productName}] Supabase public storage unavailable, storing marketplace image locally: ${
          operationalErrorLabel(error)
        }`,
      );
    }
  }

  if (!allowLocalMarketplacePublicFileFallback) {
    throw new Error("Marketplace image storage requires Supabase Storage.");
  }

  const absolutePath = path.resolve(marketplacePublicFilesDir, objectPath);
  if (!absolutePath.startsWith(path.resolve(marketplacePublicFilesDir))) {
    throw new Error("Marketplace image path is invalid");
  }

  await fs.mkdir(path.dirname(absolutePath), { recursive: true });
  await fs.writeFile(absolutePath, buffer);

  return `/marketplace-assets/${objectPath
    .split("/")
    .map(encodeURIComponent)
    .join("/")}`;
};

const readStoredPrivateFile = async (storedFile: StoredPrivateFile) => {
  if (!isAllowedPrivateStorageObjectPath(storedFile.path)) {
    throw new Error("Private file path is outside the allowed storage areas");
  }
  if (storedFile.provider === "supabase_storage") {
    if (storedFile.bucket !== privateStorageBucket) {
      throw new Error("Private file bucket is not allowed");
    }
    await ensurePrivateStorageBucket();
    const response = await fetch(
      supabaseStorageUrl(
        `/object/${encodeURIComponent(storedFile.bucket)}/${storedFile.path}`,
      ),
      { headers: supabaseStorageHeaders() },
    );

    if (!response.ok) {
      throw new Error(`Supabase storage download failed (${response.status})`);
    }

    return Buffer.from(await response.arrayBuffer());
  }

  if (storedFile.bucket !== "local") {
    throw new Error("Private local file bucket is not allowed");
  }
  const privateFilesRoot = path.resolve(privateFilesDir);
  const absolutePath = path.resolve(privateFilesRoot, storedFile.path);
  const relativePath = path.relative(privateFilesRoot, absolutePath);
  if (relativePath.startsWith("..") || path.isAbsolute(relativePath)) {
    throw new Error("Private file path is invalid");
  }
  return fs.readFile(absolutePath);
};

const parseStoredPrivateFile = (value: unknown): StoredPrivateFile | undefined => {
  if (!value || typeof value !== "object") return undefined;
  const file = value as Partial<StoredPrivateFile>;
  if (
    (file.provider !== "supabase_storage" && file.provider !== "local_file") ||
    !hasText(file.bucket) ||
    !hasText(file.path) ||
    !hasText(file.file_name) ||
    !hasText(file.content_type) ||
    typeof file.byte_size !== "number" ||
    !hasText(file.sha256) ||
    !hasText(file.stored_at)
  ) {
    return undefined;
  }

  return file as StoredPrivateFile;
};

const buildVerificationEvidenceSnapshot = (
  requestId: string,
  storedFile: StoredPrivateFile | undefined,
  extra: Record<string, unknown>,
) => ({
  ...extra,
  evidence_file: storedFile
    ? {
        ...storedFile,
        download_path: `/api/admin/verification-requests/${requestId}/evidence`,
      }
    : undefined,
});

const parseAdminTransportEvidenceFile = (
  request: VerificationRequestRecord,
): StoredPrivateFile | undefined => {
  const storedFile = parseStoredPrivateFile(
    request.evidence_snapshot_json?.evidence_file,
  );
  if (
    !storedFile ||
    !isAllowedPrivateStorageObjectPath(storedFile.path) ||
    storedFile.file_name.length > 255 ||
    !evidenceFileMimeTypes.has(storedFile.content_type) ||
    !Number.isSafeInteger(storedFile.byte_size) ||
    storedFile.byte_size < 1 ||
    storedFile.byte_size > maxVerificationFileSize ||
    !/^[0-9a-f]{64}$/.test(storedFile.sha256) ||
    !Number.isFinite(Date.parse(storedFile.stored_at)) ||
    (storedFile.provider === "supabase_storage" &&
      storedFile.bucket !== privateStorageBucket) ||
    (storedFile.provider === "local_file" && storedFile.bucket !== "local")
  ) {
    return undefined;
  }
  return storedFile;
};

const buildAdminTransportHandleClaimSnapshot = (
  request: VerificationRequestRecord,
) => {
  const snapshot = request.evidence_snapshot_json ?? {};
  if (snapshot.request_type !== "public_profile_handle_claim") return undefined;
  const claimedHandle = normalizePublicProfileHandle(
    normalizeOptionalText(snapshot.claimed_handle) ?? "",
  );
  const alternateHandle = normalizePublicProfileHandle(
    normalizeOptionalText(snapshot.requested_alternate_handle) ?? "",
  );
  const currentOwnerProfileId = normalizeOptionalText(
    snapshot.current_owner_profile_id,
  );
  const currentMarketplaceProfileId = normalizeOptionalText(
    snapshot.current_marketplace_profile_id,
  );
  const requestedByProfileId = normalizeOptionalText(
    snapshot.requested_by_profile_id,
  );
  const reason = boundPublicHandleAppealReason(
    normalizeOptionalText(snapshot.reason) ?? "",
  );
  if (!claimedHandle || !requestedByProfileId || !isUuidText(requestedByProfileId)) {
    return undefined;
  }
  return {
    request_type: "public_profile_handle_claim",
    claim_type: "platform_handle_conflict",
    claimed_handle: claimedHandle,
    claimed_profile_url: buildInfluencerPublicProfileUrl(claimedHandle),
    requested_alternate_handle: alternateHandle || null,
    current_owner_profile_id:
      currentOwnerProfileId && isUuidText(currentOwnerProfileId)
        ? currentOwnerProfileId
        : null,
    current_marketplace_profile_id:
      currentMarketplaceProfileId && isUuidText(currentMarketplaceProfileId)
        ? currentMarketplaceProfileId
        : null,
    requested_by_profile_id: requestedByProfileId,
    submitted_from: "public_profile_settings",
    platform: request.platform,
    platform_handle: request.platform_handle,
    platform_url: request.platform_url,
    reason,
    created_at: request.created_at,
  };
};

export const sanitizeVerificationRequestForAdminTransport = (
  request: VerificationRequestRecord,
): VerificationRequestRecord => {
  if (!minimizesPlatformVerificationProviderEvidence(request.platform ?? "")) {
    return request;
  }
  const sanitizedRequest = {
    ...request,
  } as VerificationRequestRecord & Record<string, unknown>;
  const legacyNaverTrafficMetricField = [
    "naver",
    "blog",
    "recent",
    "4d",
    "average",
    "visitors",
  ].join("_");
  delete sanitizedRequest[legacyNaverTrafficMetricField];
  const handleClaim = buildAdminTransportHandleClaimSnapshot(request);
  if (handleClaim) {
    return { ...sanitizedRequest, evidence_snapshot_json: handleClaim };
  }
  const status = request.ownership_check_status ?? "not_run";
  const checkedAt = request.ownership_checked_at;
  const existingDecision = (
    (request.evidence_snapshot_json?.ownership_verification as
      | Record<string, unknown>
      | undefined)?.automation as Record<string, unknown> | undefined
  )?.platform_account as Record<string, unknown> | undefined;
  const retainedOwnershipCheck = buildRetainedOwnershipCheck(
    request.platform!,
    { status, checked_at: checkedAt },
  );
  const retainedDecision = buildRetainedPlatformAutomationDecision(
    request.platform!,
    {
      mode: existingDecision?.mode,
      status: status === "not_run" ? "pending" : status,
      checked_at: checkedAt,
    },
  );
  const evidenceSnapshot = buildVerificationEvidenceSnapshot(
    request.id,
    parseAdminTransportEvidenceFile(request),
    {
      ownership_verification: {
        platform: request.platform,
        platform_handle: request.platform_handle,
        platform_url: request.platform_url,
        method: request.ownership_verification_method,
        ...(request.ownership_challenge_code &&
        ownershipChallengePattern.test(request.ownership_challenge_code)
          ? { challenge_code: request.ownership_challenge_code }
          : {}),
        ...(request.ownership_challenge_url
          ? { challenge_url: request.ownership_challenge_url }
          : {}),
        automated_check: retainedOwnershipCheck,
        automation: {
          platform_account: retainedDecision,
          ownership_challenge: retainedOwnershipCheck,
        },
      },
    },
  );
  return { ...sanitizedRequest, evidence_snapshot_json: evidenceSnapshot };
};

const loadSignedPdfFont = async () => {
  if (signedPdfFontCache) return signedPdfFontCache;

  for (const candidate of signedPdfFontCandidates) {
    try {
      const fontBuffer = await fs.readFile(candidate);
      signedPdfFontCache = {
        fileName: path.basename(candidate),
        familyName: "SignedPdfKR",
        base64: fontBuffer.toString("base64"),
      };
      return signedPdfFontCache;
    } catch {
      // Try the next configured/system font candidate.
    }
  }

  return undefined;
};

type ContractDocumentSignatureEvidence = {
  signedAt: string;
  contractHash: string;
  signatureHash: string;
  signatureDataUrl?: string;
  signatureContentType?: string;
  signerName: string;
  signerEmail: string;
  clientIp: string;
  consentText?: string;
};

const pdfPlatformLabels: Record<ContractPlatform, string> = {
  INSTAGRAM: "인스타그램",
  YOUTUBE: "유튜브",
  NAVER_BLOG: "네이버 블로그",
  TIKTOK: "틱톡",
  OTHER: "기타",
};

const pdfPaymentMethodLabels: Record<string, string> = {
  external_bank_transfer: "외부 계좌입금",
  advertiser_direct: "광고주 직접 지급",
  other_direct: "기타 직접 정산",
};

const formatPdfPaymentMethod = (value: unknown) =>
  typeof value === "string" && pdfPaymentMethodLabels[value]
    ? pdfPaymentMethodLabels[value]
    : formatPdfValue(value, "당사자 직접 정산");

const formatPdfValue = (value: unknown, fallback = "-") => {
  if (Array.isArray(value)) {
    const normalized = value
      .map((item) => String(item ?? "").trim())
      .filter(Boolean)
      .join(", ");
    return normalized || fallback;
  }
  const normalized = String(value ?? "").trim();
  return normalized || fallback;
};

const formatContractPdfDate = (value: string | undefined) => {
  if (!hasText(value)) return "-";
  const dateOnly = toDateOnly(value);
  return dateOnly ?? value;
};

const _buildLegacyContractDocumentPdf = async ({
  contract,
  signatureEvidence,
}: {
  contract: Contract;
  signatureEvidence?: ContractDocumentSignatureEvidence;
}) => {
  const { jsPDF } = await import("jspdf");
  const pdf = new jsPDF({ unit: "pt", format: "a4" });
  const signedPdfFont = await loadSignedPdfFont();
  const fontFamily = signedPdfFont?.familyName ?? "helvetica";
  if (signedPdfFont) {
    pdf.addFileToVFS(signedPdfFont.fileName, signedPdfFont.base64);
    pdf.addFont(signedPdfFont.fileName, signedPdfFont.familyName, "normal");
  }
  const margin = 40;
  const pageWidth = pdf.internal.pageSize.getWidth();
  const pageHeight = pdf.internal.pageSize.getHeight();
  const contentWidth = pageWidth - margin * 2;
  let y = 48;

  const ensureSpace = (height: number) => {
    if (y + height <= pageHeight - margin) return;
    pdf.addPage();
    y = margin;
  };

  const setTextColor = (color: number) => {
    pdf.setTextColor(color, color, color);
  };

  const addHeading = (text: string, top = 28) => {
    ensureSpace(top + 24);
    y += top;
    pdf.setDrawColor(226, 226, 226);
    pdf.line(margin, y - 13, pageWidth - margin, y - 13);
    pdf.setFont(fontFamily, signedPdfFont ? "normal" : "bold");
    pdf.setFontSize(13);
    setTextColor(18);
    pdf.text(text, margin, y);
    y += 18;
  };

  const addLine = (text: string, indent = 0) => {
    const chunks = pdf.splitTextToSize(
      formatPdfValue(text),
      contentWidth - indent,
    ) as string[];
    chunks.forEach((chunk) => {
      ensureSpace(16);
      pdf.setFont(fontFamily, "normal");
      pdf.setFontSize(10);
      setTextColor(70);
      pdf.text(chunk, margin + indent, y);
      y += 14;
    });
  };

  const addParagraph = (text: string, fallback = "-") => {
    const chunks = pdf.splitTextToSize(formatPdfValue(text, fallback), contentWidth) as string[];
    chunks.forEach((chunk) => {
      ensureSpace(16);
      pdf.setFont(fontFamily, "normal");
      pdf.setFontSize(10);
      setTextColor(70);
      pdf.text(chunk, margin, y);
      y += 14;
    });
  };

  const addRows = (rows: Array<[string, string]>) => {
    const labelWidth = 118;
    rows.forEach(([label, value]) => {
      const valueLines = pdf.splitTextToSize(
        formatPdfValue(value),
        contentWidth - labelWidth - 22,
      ) as string[];
      const rowHeight = Math.max(32, valueLines.length * 13 + 18);
      ensureSpace(rowHeight);

      pdf.setDrawColor(220, 220, 220);
      pdf.setFillColor(248, 248, 248);
      pdf.rect(margin, y, labelWidth, rowHeight, "FD");
      pdf.rect(margin + labelWidth, y, contentWidth - labelWidth, rowHeight, "S");

      pdf.setFont(fontFamily, "normal");
      pdf.setFontSize(9);
      setTextColor(90);
      pdf.text(label, margin + 10, y + 20);

      pdf.setFont(fontFamily, signedPdfFont ? "normal" : "bold");
      pdf.setFontSize(10);
      setTextColor(24);
      valueLines.forEach((line, index) => {
        pdf.text(line, margin + labelWidth + 12, y + 20 + index * 13);
      });
      y += rowHeight;
    });
    y += 4;
  };

  const addBoxedItems = (items: string[], emptyText: string) => {
    if (!items.length) {
      addParagraph(emptyText);
      return;
    }

    items.forEach((item) => {
      const lines = pdf.splitTextToSize(formatPdfValue(item), contentWidth - 24) as string[];
      const boxHeight = Math.max(38, lines.length * 14 + 20);
      ensureSpace(boxHeight + 6);
      pdf.setDrawColor(226, 226, 226);
      pdf.setFillColor(250, 250, 250);
      pdf.rect(margin, y, contentWidth, boxHeight, "FD");
      pdf.setFont(fontFamily, signedPdfFont ? "normal" : "bold");
      pdf.setFontSize(10);
      setTextColor(24);
      lines.forEach((line, index) => {
        pdf.text(line, margin + 12, y + 21 + index * 14);
      });
      y += boxHeight + 6;
    });
  };

  const addSignatureBoxes = () => {
    const gap = 14;
    const boxWidth = (contentWidth - gap) / 2;
    const boxHeight = 74;
    ensureSpace(boxHeight + 8);

    const boxes: Array<[string, string]> = [
      ["광고주", formatPdfValue(contract.advertiser_info?.name ?? contract.advertiser_id)],
      [
        "인플루언서",
        formatPdfValue(signatureEvidence?.signerName ?? contract.influencer_info.name, "서명 전"),
      ],
    ];

    boxes.forEach(([label, value], index) => {
      const x = margin + index * (boxWidth + gap);
      pdf.setDrawColor(220, 220, 220);
      pdf.rect(x, y, boxWidth, boxHeight, "S");
      pdf.setFont(fontFamily, "normal");
      pdf.setFontSize(9);
      setTextColor(120);
      pdf.text(label, x + 12, y + 18);
      pdf.setDrawColor(232, 232, 232);
      pdf.line(x + 12, y + 50, x + boxWidth - 12, y + 50);
      pdf.setFont(fontFamily, signedPdfFont ? "normal" : "bold");
      pdf.setFontSize(10);
      setTextColor(42);
      pdf.text(value, x + 12, y + 64);
    });

    y += boxHeight + 4;
  };

  const campaign = contract.campaign ?? {};
  pdf.setFont(fontFamily, signedPdfFont ? "normal" : "bold");
  pdf.setFontSize(20);
  setTextColor(18);
  const titleLines = pdf.splitTextToSize(
    formatPdfValue(contract.title, "계약서 초안"),
    contentWidth,
  ) as string[];
  titleLines.forEach((line) => {
    ensureSpace(26);
    pdf.text(line, margin, y);
    y += 24;
  });
  pdf.setFont(fontFamily, "normal");
  pdf.setFontSize(10);
  setTextColor(110);
  pdf.text(`작성일 ${formatContractPdfDate(contract.created_at)}`, margin, y + 3);
  y += 16;

  addHeading("계약 개요", 26);
  addRows([
    ["계약 종류", formatPdfValue(contract.type)],
    ["광고주", formatPdfValue(contract.advertiser_info?.name ?? contract.advertiser_id)],
    ["광고주 담당자", formatPdfValue(contract.advertiser_info?.manager)],
    ["인플루언서", formatPdfValue(contract.influencer_info.name)],
    [
      "이메일",
      formatPdfValue(
        contract.influencer_info.email ?? contract.influencer_info.contact,
      ),
    ],
    ...(contract.influencer_info.phone
      ? [["휴대전화", formatPdfValue(contract.influencer_info.phone)] as [string, string]]
      : []),
    ["대표 채널", formatPdfValue(contract.influencer_info.channel_url)],
  ]);

  addHeading("제1조 제공 매체 및 콘텐츠 조건");
  addBoxedItems(
    (campaign.deliverables ?? []).map((item) => formatPdfValue(item)).filter((item) => item !== "-"),
    "제공 매체와 콘텐츠 조건이 입력되지 않았습니다.",
  );
  addRows([
    [
      "플랫폼",
      formatPdfValue(
        (campaign.platforms ?? []).map((platform) => pdfPlatformLabels[platform] ?? platform),
      ),
    ],
  ]);

  addHeading("제2조 일정 및 검수");
  addRows([
    [
      "캠페인 기간",
      formatPdfValue(
        campaign.period ??
          [formatContractPdfDate(campaign.start_date), formatContractPdfDate(campaign.end_date)]
            .filter((value) => value !== "-")
            .join(" - "),
      ),
    ],
    ["업로드 마감일", formatPdfValue(campaign.upload_due_at ?? campaign.deadline)],
    ["광고주 검수 회신", formatPdfValue(campaign.review_due_at)],
    ["수정 가능 횟수", formatPdfValue(campaign.revision_limit)],
    ["수정 요청 기준", formatPdfValue(campaign.revision_request_policy)],
  ]);

  addHeading("제3조 광고 표시 및 추적");
  addParagraph(
    formatPdfValue(
      campaign.disclosure_text,
      "광고 표시 조건이 입력되지 않았습니다.",
    ),
  );
  if (hasText(campaign.tracking_link)) {
    addRows([["추적 링크", campaign.tracking_link]]);
  }
  if ((campaign.reference_links ?? []).length) {
    addRows([["예시 레퍼런스", formatPdfValue(campaign.reference_links)]]);
  }
  if ((campaign.required_hashtags ?? []).length || (campaign.brand_account_tags ?? []).length) {
    addRows([
      ["필수 해시태그", formatPdfValue(campaign.required_hashtags)],
      ["브랜드 태그", formatPdfValue(campaign.brand_account_tags)],
    ]);
  }

  addHeading("제4조 지급 조건");
  addRows([
    ["지급 방식", formatPdfPaymentMethod(campaign.payment_method)],
    [
      "원천징수",
      campaign.withholding_tax_enabled === true
        ? "3.3% 원천징수/소득신고 확인"
        : "당사자 직접 확인",
    ],
  ]);
  addParagraph(formatPdfValue(campaign.budget, "지급 조건이 입력되지 않았습니다."));

  addHeading("특약 및 자동 생성 조항");
  if (contract.clauses.length > 0) {
    contract.clauses.forEach((clause, index) => {
      ensureSpace(48);
      pdf.setFont(fontFamily, "normal");
      pdf.setFontSize(9);
      setTextColor(150);
      pdf.text(String(index + 1).padStart(2, "0"), margin, y);
      pdf.setFont(fontFamily, signedPdfFont ? "normal" : "bold");
      pdf.setFontSize(10);
      setTextColor(24);
      pdf.text(formatPdfValue(clause.category), margin + 28, y);
      y += 16;
      addLine(clause.content, 28);
      y += 4;
    });
  } else {
    addParagraph("계약 조항이 입력되지 않았습니다.");
  }

  addHeading("서명란");
  addSignatureBoxes();

  if (signatureEvidence) {
    addHeading("전자서명 증빙");
    addRows([
      ["서명자", signatureEvidence.signerName],
      ["서명자 이메일", signatureEvidence.signerEmail],
      ["서명 시각", signatureEvidence.signedAt],
      ["서명 IP", signatureEvidence.clientIp],
      ["계약 해시", signatureEvidence.contractHash],
      ["서명 이미지 해시", signatureEvidence.signatureHash],
      ["동의 문구 버전", signatureConsentVersion],
      [
        "동의 문구",
        signatureEvidence.consentText ||
          "서명자는 계약 내용을 확인하고 전자서명에 동의했습니다.",
      ],
    ]);

    if (signatureEvidence.signatureDataUrl && signatureEvidence.signatureContentType) {
    try {
      const imageType =
          signatureEvidence.signatureContentType === "image/png"
          ? "PNG"
            : signatureEvidence.signatureContentType === "image/jpeg"
            ? "JPEG"
            : undefined;
      if (imageType) {
        ensureSpace(70);
          pdf.addImage(signatureEvidence.signatureDataUrl, imageType, margin, y, 160, 48);
        y += 60;
      }
    } catch {
        addLine("서명 이미지는 별도 저장되었고 해시로 검증됩니다.");
      }
    }
  }

  return Buffer.from(pdf.output("arraybuffer"));
};

const buildContractDocumentPdf = async ({
  contract,
  signatureEvidence,
}: {
  contract: Contract;
  signatureEvidence?: ContractDocumentSignatureEvidence;
}) => {
  const { jsPDF } = await import("jspdf");
  const pdf = new jsPDF({ unit: "pt", format: "a4" });
  const regularFont = await loadSignedPdfFont();
  const boldFont = regularFont ? await loadSignedPdfBoldFont() : undefined;
  const fontFamily = regularFont?.familyName ?? "helvetica";

  if (regularFont) {
    pdf.addFileToVFS(regularFont.fileName, regularFont.base64);
    pdf.addFont(regularFont.fileName, regularFont.familyName, "normal");
    if (boldFont) {
      pdf.addFileToVFS(boldFont.fileName, boldFont.base64);
      pdf.addFont(boldFont.fileName, regularFont.familyName, "bold");
    }
  }

  const canUseBold = !regularFont || Boolean(boldFont);
  const pageWidth = pdf.internal.pageSize.getWidth();
  const pageHeight = pdf.internal.pageSize.getHeight();
  const marginX = 62;
  const topMargin = 56;
  const bottomMargin = 58;
  const contentWidth = pageWidth - marginX * 2;
  let y = topMargin;

  const setFont = (bold = false) => {
    pdf.setFont(fontFamily, bold && canUseBold ? "bold" : "normal");
  };

  const setTextColor = (color: number) => {
    pdf.setTextColor(color, color, color);
  };

  const ensureSpace = (height: number) => {
    if (y + height <= pageHeight - bottomMargin) return;
    pdf.addPage();
    y = topMargin;
  };

  const splitText = (text: string, width: number) =>
    pdf.splitTextToSize(formatPdfValue(text), width) as string[];

  const drawTextLines = ({
    lines,
    x,
    width,
    size = 10.5,
    lineHeight = 17,
    bold = false,
    color = 35,
    align,
  }: {
    lines: string[];
    x: number;
    width?: number;
    size?: number;
    lineHeight?: number;
    bold?: boolean;
    color?: number;
    align?: "left" | "center" | "right";
  }) => {
    setFont(bold);
    pdf.setFontSize(size);
    setTextColor(color);
    lines.forEach((line) => {
      ensureSpace(lineHeight);
      pdf.text(line, x, y, align ? { align } : undefined);
      y += lineHeight;
    });
    return width;
  };

  const addParagraph = (text: string, options: { indent?: number; top?: number } = {}) => {
    const indent = options.indent ?? 0;
    y += options.top ?? 0;
    const lines = splitText(text, contentWidth - indent);
    drawTextLines({
      lines,
      x: marginX + indent,
      width: contentWidth - indent,
      size: 10.5,
      lineHeight: 17,
      color: 38,
    });
    y += 4;
  };

  const addSectionTitle = (title: string, top = 20) => {
    ensureSpace(top + 26);
    y += top;
    setFont(true);
    pdf.setFontSize(12.5);
    setTextColor(18);
    pdf.text(title, marginX, y);
    y += 10;
    pdf.setDrawColor(24, 24, 24);
    pdf.setLineWidth(0.6);
    pdf.line(marginX, y, marginX + contentWidth, y);
    y += 16;
  };

  const addDefinitionRows = (rows: Array<[string, string]>) => {
    const labelWidth = 110;
    rows.forEach(([label, rawValue]) => {
      const valueLines = splitText(formatPdfValue(rawValue), contentWidth - labelWidth - 18);
      const rowHeight = Math.max(29, valueLines.length * 14 + 14);
      ensureSpace(rowHeight + 1);

      pdf.setDrawColor(214, 214, 214);
      pdf.setLineWidth(0.4);
      pdf.line(marginX, y, marginX + contentWidth, y);

      setFont(true);
      pdf.setFontSize(9.5);
      setTextColor(70);
      pdf.text(label, marginX + 2, y + 18);

      setFont(false);
      pdf.setFontSize(10.2);
      setTextColor(28);
      valueLines.forEach((line, index) => {
        pdf.text(line, marginX + labelWidth, y + 18 + index * 14);
      });

      y += rowHeight;
    });
    pdf.setDrawColor(214, 214, 214);
    pdf.line(marginX, y, marginX + contentWidth, y);
    y += 10;
  };

  const addClauseBlock = (heading: string, body: string) => {
    ensureSpace(48);
    setFont(true);
    pdf.setFontSize(10.8);
    setTextColor(22);
    pdf.text(heading, marginX, y);
    y += 17;
    addParagraph(body, { indent: 12 });
  };

  const addSignatureArea = () => {
    const gap = 18;
    const boxWidth = (contentWidth - gap) / 2;
    const boxHeight = 86;
    ensureSpace(boxHeight + 20);

    const boxes: Array<[string, string]> = [
      ["광고주", formatPdfValue(contract.advertiser_info?.name ?? contract.advertiser_id)],
      [
        "인플루언서",
        formatPdfValue(signatureEvidence?.signerName ?? contract.influencer_info.name, "서명 전"),
      ],
    ];

    boxes.forEach(([label, value], index) => {
      const x = marginX + index * (boxWidth + gap);
      pdf.setDrawColor(185, 185, 185);
      pdf.setLineWidth(0.5);
      pdf.rect(x, y, boxWidth, boxHeight, "S");

      setFont(true);
      pdf.setFontSize(10);
      setTextColor(35);
      pdf.text(label, x + 14, y + 21);

      pdf.setDrawColor(205, 205, 205);
      pdf.line(x + 14, y + 56, x + boxWidth - 14, y + 56);

      setFont(false);
      pdf.setFontSize(10.5);
      setTextColor(28);
      pdf.text(value, x + 14, y + 73);
    });

    y += boxHeight + 6;
  };

  const addPageNumbers = () => {
    const totalPages = pdf.getNumberOfPages();
    for (let pageNo = 1; pageNo <= totalPages; pageNo += 1) {
      pdf.setPage(pageNo);
      setFont(false);
      pdf.setFontSize(8.5);
      setTextColor(120);
      pdf.text(`- ${pageNo} -`, pageWidth / 2, pageHeight - 30, { align: "center" });
    }
  };

  const campaign = contract.campaign ?? {};
  const advertiserName = formatPdfValue(contract.advertiser_info?.name ?? contract.advertiser_id);
  const influencerName = formatPdfValue(contract.influencer_info.name);
  const platformText = formatPdfValue(
    (campaign.platforms ?? []).map((platform) => pdfPlatformLabels[platform] ?? platform),
  );
  const deliverableText = formatPdfValue(campaign.deliverables, "제공 콘텐츠 조건이 입력되지 않았습니다.");
  const periodText = formatPdfValue(
    campaign.period ??
      [formatContractPdfDate(campaign.start_date), formatContractPdfDate(campaign.end_date)]
        .filter((value) => value !== "-")
        .join(" - "),
  );

  setFont(true);
  pdf.setFontSize(22);
  setTextColor(12);
  pdf.text("광고 계약서", pageWidth / 2, y, { align: "center" });
  y += 34;

  setFont(false);
  pdf.setFontSize(10);
  setTextColor(90);
  pdf.text(`계약명: ${formatPdfValue(contract.title)}`, pageWidth / 2, y, { align: "center" });
  y += 14;
  pdf.text(`작성일: ${formatContractPdfDate(contract.created_at)}`, pageWidth / 2, y, {
    align: "center",
  });
  y += 28;

  addParagraph(
    `본 계약은 광고주 ${advertiserName} 및 인플루언서 ${influencerName} 사이에서 광고 콘텐츠 제작 및 게시와 관련하여 체결된다.`,
  );

  addSectionTitle("제1조 계약 당사자");
  addDefinitionRows([
    ["광고주", advertiserName],
    ["광고주 담당자", formatPdfValue(contract.advertiser_info?.manager)],
    ["인플루언서", influencerName],
    [
      "인플루언서 이메일",
      formatPdfValue(
        contract.influencer_info.email ?? contract.influencer_info.contact,
      ),
    ],
    ...(contract.influencer_info.phone
      ? [["인플루언서 휴대전화", formatPdfValue(contract.influencer_info.phone)] as [
          string,
          string,
        ]]
      : []),
    ["대표 채널", formatPdfValue(contract.influencer_info.channel_url)],
  ]);

  addSectionTitle("제2조 계약 목적 및 범위");
  addParagraph(
    `본 계약은 ${formatPdfValue(contract.title)}의 수행을 위하여 인플루언서가 광고 콘텐츠를 제작·게시하고, 광고주가 그 대가를 지급하는 데 필요한 조건을 정하는 것을 목적으로 한다.`,
  );

  addSectionTitle("제3조 플랫폼 및 콘텐츠");
  addDefinitionRows([
    ["계약 종류", formatPdfValue(contract.type)],
    ["플랫폼", platformText],
    ["콘텐츠", deliverableText],
  ]);

  addSectionTitle("제4조 일정 및 검수");
  addDefinitionRows([
    ["캠페인 기간", periodText],
    ["업로드 마감일", formatPdfValue(campaign.upload_due_at ?? campaign.deadline)],
    ["광고주 검수 회신", formatPdfValue(campaign.review_due_at)],
    ["수정 가능 횟수", formatPdfValue(campaign.revision_limit)],
    ["수정 요청 기준", formatPdfValue(campaign.revision_request_policy)],
  ]);

  addSectionTitle("제5조 광고 표시 및 제출");
  addDefinitionRows([
    [
      "광고 표시 문구",
      formatPdfValue(
        campaign.disclosure_text,
        "광고 표시는 관련 법령과 플랫폼 정책에 따라 명확하게 표시한다.",
      ),
    ],
  ]);
  if ((campaign.required_hashtags ?? []).length || (campaign.brand_account_tags ?? []).length) {
    addDefinitionRows([
      ["필수 해시태그", formatPdfValue(campaign.required_hashtags)],
      ["브랜드 태그", formatPdfValue(campaign.brand_account_tags)],
    ]);
  }
  if (hasText(campaign.tracking_link)) {
    addDefinitionRows([["추적 링크", campaign.tracking_link]]);
  }
  if ((campaign.reference_links ?? []).length) {
    addDefinitionRows([["예시 레퍼런스", formatPdfValue(campaign.reference_links)]]);
  }

  addSectionTitle("제6조 지급 조건");
  addDefinitionRows([
    ["지급 방식", formatPdfPaymentMethod(campaign.payment_method)],
    [
      "원천징수",
      campaign.withholding_tax_enabled === true
        ? "3.3% 원천징수/소득신고 확인"
        : "당사자 직접 확인",
    ],
    ["지급 금액/조건", formatPdfValue(campaign.budget, "지급 조건이 입력되지 않았습니다.")],
  ]);

  addSectionTitle("제7조 특약 및 추가 조항");
  if (contract.clauses.length > 0) {
    contract.clauses.forEach((clause, index) => {
      addClauseBlock(`7.${index + 1} ${formatPdfValue(clause.category)}`, clause.content);
    });
  } else {
    addParagraph("별도 특약 사항이 없습니다.");
  }

  addSectionTitle("제8조 서명");
  addParagraph(
    "계약 당사자는 본 계약의 내용을 확인하였으며, 전자서명 또는 이에 준하는 방식으로 본 계약 체결에 동의한다.",
  );
  addSignatureArea();

  if (signatureEvidence) {
    addSectionTitle("전자서명 증빙");
    addDefinitionRows([
      ["서명자", signatureEvidence.signerName],
      ["서명자 이메일", signatureEvidence.signerEmail],
      ["서명 시각", signatureEvidence.signedAt],
      ["서명 IP", signatureEvidence.clientIp],
      ["계약 해시", signatureEvidence.contractHash],
      ["서명 이미지 해시", signatureEvidence.signatureHash],
      ["동의 문구 버전", signatureConsentVersion],
      [
        "동의 문구",
        signatureEvidence.consentText ||
          "서명자는 계약 내용을 확인하고 전자서명에 동의했습니다.",
      ],
    ]);

    if (signatureEvidence.signatureDataUrl && signatureEvidence.signatureContentType) {
      try {
        const imageType =
          signatureEvidence.signatureContentType === "image/png"
            ? "PNG"
            : signatureEvidence.signatureContentType === "image/jpeg"
              ? "JPEG"
              : undefined;
        if (imageType) {
          ensureSpace(66);
          pdf.addImage(signatureEvidence.signatureDataUrl, imageType, marginX, y, 150, 45);
          y += 54;
        }
      } catch {
        addParagraph("서명 이미지는 별도 저장되었고 해시로 검증됩니다.");
      }
    }
  }

  addPageNumbers();
  return Buffer.from(pdf.output("arraybuffer"));
};

const buildSignedContractPdf = async ({
  contract,
  signedAt,
  contractHash,
  signatureHash,
  signatureDataUrl,
  signatureContentType,
  signerName,
  signerEmail,
  clientIp,
  consentText,
}: {
  contract: Contract;
  signedAt: string;
  contractHash: string;
  signatureHash: string;
  signatureDataUrl?: string;
  signatureContentType?: string;
  signerName: string;
  signerEmail: string;
  clientIp: string;
  consentText?: string;
}) =>
  buildContractDocumentPdf({
    contract,
    signatureEvidence: {
      signedAt,
      contractHash,
      signatureHash,
      signatureDataUrl,
      signatureContentType,
      signerName,
      signerEmail,
      clientIp,
      consentText,
    },
  });

const stableUuid = (seed: string) => {
  const chars = sha256Hex(seed).slice(0, 32).split("");
  chars[12] = "5";
  chars[16] = ((Number.parseInt(chars[16], 16) & 0x3) | 0x8).toString(16);
  const hex = chars.join("");
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(
    16,
    20,
  )}-${hex.slice(20)}`;
};

const isUuid = (value: string) =>
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
    value,
  );

const toDateOnly = (value: string | undefined) => {
  if (!hasText(value)) return undefined;
  const match = value.match(/\d{4}-\d{2}-\d{2}/);
  return match?.[0];
};

const toIsoDateTime = (value: string | undefined) => {
  if (!hasText(value)) return undefined;
  const time = new Date(value).getTime();
  return Number.isNaN(time) ? undefined : new Date(time).toISOString();
};

const parseMoneyAmount = (value: string | undefined) => {
  const text = value?.trim();
  if (
    !text ||
    /%|협의|미정|수수료|commission|판매\s*수익|성과\s*형|매월|월별|회당|건당/i.test(
      text,
    ) ||
    /[~–—-]|부터|이상|이하|최대|최소|범위/i.test(text)
  ) {
    return undefined;
  }

  const matches = Array.from(
    text.matchAll(
      /(\d+(?:\.\d+)?)\s*억\s*원?|(\d+(?:\.\d+)?)\s*만\s*원?|([0-9][0-9,]{0,})\s*원/g,
    ),
  );
  if (matches.length !== 1) return undefined;

  const match = matches[0];
  const amount = match[1]
    ? Number(match[1]) * 100_000_000
    : match[2]
      ? Number(match[2]) * 10_000
      : Number((match[3] ?? "").replace(/,/g, ""));
  return Number.isFinite(amount) && amount >= 0 ? Math.round(amount) : undefined;
};

const legacyContractStatusLabels: Record<Contract["status"], string> = {
  DRAFT: "초안",
  REVIEWING: "검토",
  NEGOTIATING: "수정",
  APPROVED: "서명",
  SIGNED: "서명 완료",
  CLOSED: "계약 마감",
};

const buildContractReviewPdf = async (contract: Contract) =>
  buildContractDocumentPdf({ contract });

const formatWonCompact = (amount: number) => {
  if (!amount || amount <= 0) return "-";
  if (amount >= 100000000) {
    const value = amount / 100000000;
    return `${Number.isInteger(value) ? value : value.toFixed(1)}억원`;
  }
  if (amount >= 10000) {
    return `${Math.round(amount / 10000).toLocaleString("ko-KR")}만원`;
  }
  return `${amount.toLocaleString("ko-KR")}원`;
};

const buildAdminMetrics = async (
  contracts: Contract[],
  supportAccessRequests: SupportAccessRequestRecord[],
) => {
  const statusCounts = Array.from(contractStatuses).map((status) => ({
    status,
    label: legacyContractStatusLabels[status as Contract["status"]] ?? status,
    count: contracts.filter((contract) => contract.status === status).length,
  }));
  const totalFixedFeeAmount = contracts.reduce((total, contract) => {
    const amount = parseMoneyAmount(contract.campaign?.budget);
    return total + (amount ?? 0);
  }, 0);
  const activeSupportAccessRequests = supportAccessRequests.filter(isSupportAccessActive);

  return {
    contract_count: contracts.length,
    active_contract_count: contracts.filter((contract) => contract.status !== "CLOSED").length,
    completed_contract_count: contracts.filter((contract) => contract.status === "CLOSED").length,
    active_share_link_count: contracts.filter(
      (contract) => contract.evidence?.share_token_status === "active",
    ).length,
    total_fixed_fee_amount: totalFixedFeeAmount,
    total_fixed_fee_label: formatWonCompact(totalFixedFeeAmount),
    status_counts: statusCounts,
    support_access: {
      active_count: activeSupportAccessRequests.length,
      total_count: supportAccessRequests.length,
    },
    source: useSupabase ? "supabase" : "file",
    demo_mode: demoMode,
  };
};

