const campaignProposalTypes = new Set<CampaignProposalType>(
  campaignProposalTypeOptions,
);
const campaignRequiredConsentLimit = 8;
const campaignRequiredConsentTextLimit = 300;
const campaignRequiredConsentIdLimit = 80;
const campaignApplicationContactFieldValues = new Set<CampaignApplicationContactField>([
  "phone",
  "email",
]);
const campaignApplicationContactPurpose =
  "캠페인 지원자 확인, 선정 및 진행 안내";
const campaignApplicationContactRetentionPolicy =
  "campaign_end_plus_90_days" as const;

const normalizeCampaignApplicationContactFields = (
  value: unknown,
): CampaignApplicationContactField[] => {
  if (!Array.isArray(value)) return [];
  return Array.from(
    new Set(
      value.filter(
        (item): item is CampaignApplicationContactField =>
          typeof item === "string" &&
          campaignApplicationContactFieldValues.has(
            item as CampaignApplicationContactField,
          ),
      ),
    ),
  ).sort();
};

const validateCampaignApplicationContactFields = (value: unknown) => {
  if (value === undefined || value === null) {
    return { ok: true as const, fields: [] as CampaignApplicationContactField[] };
  }
  if (!Array.isArray(value) || value.length > campaignApplicationContactFieldValues.size) {
    return {
      ok: false as const,
      error: "지원자 연락처 수집 항목을 다시 확인해 주세요.",
    };
  }
  const fields = normalizeCampaignApplicationContactFields(value);
  if (fields.length !== value.length) {
    return {
      ok: false as const,
      error: "지원자 연락처는 휴대전화와 이메일만 중복 없이 선택할 수 있습니다.",
    };
  }
  return { ok: true as const, fields };
};

const buildCampaignApplicationContactConsentVersion = ({
  campaignId,
  fields,
}: {
  campaignId: string;
  fields: CampaignApplicationContactField[];
}) =>
  sha256Hex(
    JSON.stringify({
      policyVersion: CAMPAIGN_APPLICATION_CONTACT_POLICY_VERSION,
      campaignId,
      fields: normalizeCampaignApplicationContactFields(fields),
      purpose: campaignApplicationContactPurpose,
      retentionPolicy: campaignApplicationContactRetentionPolicy,
    }),
  );

const normalizeCampaignRequiredConsentText = (value: unknown) =>
  normalizeRequiredText(value).replace(/\r\n?/g, "\n");

const normalizeCampaignRequiredConsents = (
  value: unknown,
): CampaignRequiredConsent[] => {
  if (!Array.isArray(value)) return [];

  const ids = new Set<string>();
  const normalized: CampaignRequiredConsent[] = [];
  for (const item of value) {
    if (!item || typeof item !== "object") continue;
    const record = item as Record<string, unknown>;
    const id = normalizeRequiredText(record.id);
    const text = normalizeCampaignRequiredConsentText(record.text);
    if (
      !id ||
      id.length > campaignRequiredConsentIdLimit ||
      !text ||
      text.length > campaignRequiredConsentTextLimit ||
      ids.has(id)
    ) {
      continue;
    }
    ids.add(id);
    normalized.push({ id, text });
    if (normalized.length === campaignRequiredConsentLimit) break;
  }
  return normalized;
};

const buildCampaignConsentVersion = (items: CampaignRequiredConsent[]) =>
  sha256Hex(JSON.stringify(items.map(({ id, text }) => ({ id, text }))));

const validateCampaignRequiredConsents = (value: unknown) => {
  if (value === undefined || value === null) {
    const items: CampaignRequiredConsent[] = [];
    return {
      ok: true as const,
      items,
      version: buildCampaignConsentVersion(items),
    };
  }
  if (!Array.isArray(value) || value.length > campaignRequiredConsentLimit) {
    return {
      ok: false as const,
      error: `필수 동의 항목은 ${campaignRequiredConsentLimit}개까지 추가할 수 있습니다.`,
    };
  }

  const ids = new Set<string>();
  const items: CampaignRequiredConsent[] = [];
  for (const item of value) {
    if (!item || typeof item !== "object") {
      return { ok: false as const, error: "필수 동의 항목을 다시 확인해 주세요." };
    }
    const record = item as Record<string, unknown>;
    const id = normalizeRequiredText(record.id);
    const text = normalizeCampaignRequiredConsentText(record.text);
    if (!id || id.length > campaignRequiredConsentIdLimit || ids.has(id)) {
      return { ok: false as const, error: "필수 동의 항목 식별값을 다시 확인해 주세요." };
    }
    if (!text || text.length > campaignRequiredConsentTextLimit) {
      return {
        ok: false as const,
        error: `필수 동의 내용은 항목당 ${campaignRequiredConsentTextLimit}자 이내로 입력해 주세요.`,
      };
    }
    ids.add(id);
    items.push({ id, text });
  }

  return {
    ok: true as const,
    items,
    version: buildCampaignConsentVersion(items),
  };
};

const normalizeStringArrayForStorage = (
  value: unknown,
  fallback: string[] = [],
  maxItems = 8,
) => {
  if (!Array.isArray(value)) return fallback;

  const normalized = value
    .map((item) => normalizeRequiredText(item))
    .filter(hasText)
    .slice(0, maxItems);

  return normalized.length > 0 ? normalized : fallback;
};

const normalizeCampaignProposalTypes = (
  value: unknown,
  fallback: CampaignProposalType[] = ["sponsored_post", "product_seeding"],
) => {
  if (!Array.isArray(value)) return fallback;

  const normalized = value.filter(
    (item): item is CampaignProposalType =>
      typeof item === "string" && campaignProposalTypes.has(item as CampaignProposalType),
  );

  return normalized.length > 0 ? Array.from(new Set(normalized)) : fallback;
};

const normalizeMarketplaceCountries = (
  value: unknown,
  fallback: MarketplaceCountryCode[] = [],
  maxItems = 8,
) => {
  if (!Array.isArray(value)) return fallback;

  const normalized = value.filter(
    (item): item is MarketplaceCountryCode =>
      isMarketplaceCountryCode(item),
  );

  return normalized.length > 0
    ? Array.from(new Set(normalized)).slice(0, maxItems)
    : fallback;
};

const normalizeMarketplacePortfolio = (
  value: unknown,
): MarketplaceInfluencerProfile["portfolio"] => {
  if (!Array.isArray(value)) {
    return [
      {
        title: "공개 프로필",
        brand: productName,
        result: "광고주 컨택 접수 가능",
      },
    ];
  }

  return value
    .map((item) => {
      if (!item || typeof item !== "object") return undefined;
      const record = item as Record<string, unknown>;
      const title = normalizeRequiredText(record.title);
      const brand = normalizeRequiredText(record.brand);
      const result = normalizeRequiredText(record.result);
      if (!title || !brand || !result) return undefined;
      return { title, brand, result };
    })
    .filter((item): item is MarketplaceInfluencerProfile["portfolio"][number] =>
      Boolean(item),
    )
    .slice(0, 6);
};

const marketplaceCampaignStatuses = new Set(["open", "draft", "closed", "ended"]);
const advertiserCampaignStatusUpdates = new Set<MarketplaceCampaignStatus>([
  "open",
  "closed",
  "ended",
]);
const isAdvertiserCampaignStatusUpdate = (
  value: string,
): value is MarketplaceCampaignStatus =>
  advertiserCampaignStatusUpdates.has(value as MarketplaceCampaignStatus);

const normalizeCampaignPlatforms = (
  value: unknown,
  fallback: InfluencerPlatform[] = [],
) => {
  const { selected } = normalizeSelectedValues(value, influencerPlatforms);
  return selected.length > 0 ? selected : fallback;
};

const normalizeBrandCampaignActivityEvents = (
  value: unknown,
): NonNullable<MarketplaceBrandCampaign["activityEvents"]> => {
  if (!Array.isArray(value)) return [];

  return value
    .map((item) => {
      if (!item || typeof item !== "object") return undefined;
      const record = item as Record<string, unknown>;
      const id = normalizeOptionalText(record.id)?.slice(0, 80);
      const actor = normalizeOptionalText(record.actor)?.slice(0, 120);
      const action = normalizeOptionalText(record.action)?.slice(0, 80);
      const description = normalizeOptionalText(record.description)?.slice(0, 500);
      const createdAt = normalizeOptionalText(record.createdAt ?? record.created_at);
      if (!id || !actor || !action || !description || !createdAt) return undefined;
      return { id, actor, action, description, createdAt };
    })
    .filter(
      (item): item is NonNullable<MarketplaceBrandCampaign["activityEvents"]>[number] =>
        Boolean(item),
    )
    .slice(0, 80);
};

const normalizeBrandCampaigns = (
  value: unknown,
  maxItems = 20,
): MarketplaceBrandProfile["activeCampaigns"] => {
  if (!Array.isArray(value)) return [];

  return value
    .map((item) => {
      if (!item || typeof item !== "object") return undefined;
      const record = item as Record<string, unknown>;
      const id = normalizeOptionalText(record.id)?.slice(0, 80);
      const explicitRelativeTestDates =
        typeof record.relativeTestDates === "boolean"
          ? record.relativeTestDates
          : typeof record.relative_test_dates === "boolean"
            ? record.relative_test_dates
            : undefined;
      const relativeTestDates =
        explicitRelativeTestDates ??
        !normalizeOptionalText(
          record.statusUpdatedByProfileId ?? record.status_updated_by_profile_id,
        );
      const title = normalizeRequiredText(record.title);
      const type = normalizeRequiredText(record.type) as CampaignProposalType;
      const otherTypeLabel = normalizeOptionalText(
        record.otherTypeLabel ?? record.other_type_label,
      )?.slice(0, 80);
      const budget = normalizeRequiredText(record.budget);
      const applicantLimit = normalizeOptionalText(
        record.applicantLimit ?? record.applicant_limit,
      )?.slice(0, 40);
      const location = normalizeOptionalText(record.location)?.slice(0, 80);
      const offer = normalizeOptionalText(
        record.offer ?? record.offeredProduct ?? record.offered_product,
      )?.slice(0, 120);
      const summary = normalizeOptionalText(record.summary)?.slice(0, 1000);
      const mission = normalizeOptionalText(record.mission)?.slice(0, 500);
      const targetCountries = normalizeMarketplaceCountries(
        record.targetCountries ?? record.target_countries,
      );
      const thumbnailUrl = normalizeMarketplacePublicImageUrl(
        record.thumbnailUrl ?? record.thumbnail_url,
      );
      const deadline = normalizeOptionalText(record.deadline)?.slice(0, 40);
      const uploadDeadline = normalizeOptionalText(
        record.uploadDeadline ?? record.upload_deadline,
      )?.slice(0, 40);
      const status = normalizeOptionalText(record.status);
      const createdAt = normalizeOptionalText(record.createdAt ?? record.created_at);
      const updatedAt = normalizeOptionalText(record.updatedAt ?? record.updated_at);
      const statusUpdatedAt = normalizeOptionalText(
        record.statusUpdatedAt ?? record.status_updated_at,
      );
      const statusUpdatedBy = normalizeOptionalText(
        record.statusUpdatedBy ?? record.status_updated_by,
      )?.slice(0, 120);
      const closedAt = normalizeOptionalText(record.closedAt ?? record.closed_at);
      const endedAt = normalizeOptionalText(record.endedAt ?? record.ended_at);
      const reopenedAt = normalizeOptionalText(record.reopenedAt ?? record.reopened_at);
      const activityEvents = normalizeBrandCampaignActivityEvents(
        record.activityEvents ?? record.activity_events,
      );
      const platforms = normalizeCampaignPlatforms(record.platforms);
      const deliverables = normalizeStringArrayForStorage(record.deliverables, [], 6);
      const requiredConsents = normalizeCampaignRequiredConsents(
        record.requiredConsents ?? record.required_consents,
      );
      const consentVersion = buildCampaignConsentVersion(requiredConsents);
      const applicationContactFields = normalizeCampaignApplicationContactFields(
        record.applicationContactFields ?? record.application_contact_fields,
      );
      const applicationContactConsentVersion = id
        ? buildCampaignApplicationContactConsentVersion({
            campaignId: id,
            fields: applicationContactFields,
          })
        : undefined;
      if (
        !title ||
        !budget ||
        !campaignProposalTypes.has(type) ||
        (type === "other" && !otherTypeLabel)
      ) {
        return undefined;
      }
      const normalizedCampaign: MarketplaceBrandCampaign = {
        ...(id ? { id } : {}),
        relativeTestDates,
        title: title.slice(0, 100),
        type,
        ...(type === "other" && otherTypeLabel ? { otherTypeLabel } : {}),
        budget: budget.slice(0, 80),
        ...(applicantLimit ? { applicantLimit } : {}),
        ...(location ? { location } : {}),
        ...(offer ? { offer } : {}),
        ...(summary ? { summary } : {}),
        ...(mission ? { mission } : {}),
        ...(targetCountries.length > 0 ? { targetCountries } : {}),
        ...(thumbnailUrl ? { thumbnailUrl } : {}),
        ...(deadline ? { deadline } : {}),
        ...(uploadDeadline ? { uploadDeadline } : {}),
        ...(platforms.length > 0 ? { platforms } : {}),
        ...(deliverables.length > 0 ? { deliverables } : {}),
        ...(applicationContactFields.length > 0
          ? {
              applicationContactFields,
              applicationContactConsentVersion,
            }
          : {}),
        requiredConsents,
        consentVersion,
        ...(status && marketplaceCampaignStatuses.has(status)
          ? { status: status as MarketplaceCampaignStatus }
          : {}),
        ...(createdAt ? { createdAt } : {}),
        ...(updatedAt ? { updatedAt } : {}),
        ...(statusUpdatedAt ? { statusUpdatedAt } : {}),
        ...(statusUpdatedBy ? { statusUpdatedBy } : {}),
        ...(closedAt ? { closedAt } : {}),
        ...(endedAt ? { endedAt } : {}),
        ...(reopenedAt ? { reopenedAt } : {}),
        ...(activityEvents.length > 0 ? { activityEvents } : {}),
      };
      return normalizedCampaign;
    })
    .filter((item): item is MarketplaceBrandCampaign =>
      Boolean(item),
    )
    .slice(0, maxItems);
};

const marketplaceCampaignTable = "marketplace_campaigns";
let normalizedMarketplaceCampaignFallbackWarned = false;

const isMissingMarketplaceCampaignTableError = (error: unknown) =>
  error instanceof Error &&
  /marketplace_campaigns|schema cache|Could not find the table|relation/i.test(
    error.message,
  ) &&
  /404|400|PGRST205|does not exist|schema cache/i.test(error.message);

const readNormalizedMarketplaceCampaignRows = async (
  query: string,
): Promise<SupabaseMarketplaceCampaignRow[] | undefined> => {
  try {
    return await readSupabaseRows<SupabaseMarketplaceCampaignRow>(
      marketplaceCampaignTable,
      query,
      "normalized marketplace campaigns",
    );
  } catch (error) {
    if (!isMissingMarketplaceCampaignTableError(error)) throw error;
    if (!normalizedMarketplaceCampaignFallbackWarned) {
      console.warn(
        "[yeollock.me] marketplace_campaigns is unavailable; using the legacy brand campaign mirror until migrations are applied.",
      );
      normalizedMarketplaceCampaignFallbackWarned = true;
    }
    return undefined;
  }
};

const readAllNormalizedMarketplaceCampaignRows = async (query: string) => {
  const pageSize = 1000;
  const rows: SupabaseMarketplaceCampaignRow[] = [];
  for (let offset = 0; ; offset += pageSize) {
    const page = await readNormalizedMarketplaceCampaignRows(
      `${query}&limit=${pageSize}&offset=${offset}`,
    );
    if (!page) return undefined;
    rows.push(...page);
    if (page.length < pageSize) return rows;
  }
};

const mapNormalizedMarketplaceCampaignRow = (
  row: SupabaseMarketplaceCampaignRow,
) => {
  const data =
    row.campaign_data && typeof row.campaign_data === "object"
      ? row.campaign_data
      : {};
  return normalizeBrandCampaigns(
    [
      {
        ...data,
        id: row.id,
        status: row.status,
        createdAt: data.createdAt ?? row.created_at,
        updatedAt: data.updatedAt ?? row.updated_at,
      },
    ],
    1,
  )[0];
};

const hydrateBrandRowsWithNormalizedCampaigns = async (
  rows: SupabaseMarketplaceBrandProfileRow[],
  options: { readAll?: boolean } = {},
) => {
  if (rows.length === 0) return rows;
  const campaignQuery = `?select=*&brand_profile_id=in.${postgrestInFilter(
    rows.map((row) => row.id),
  )}&archived_at=is.null&order=created_at.desc`;
  const campaignRows = options.readAll
    ? await readAllNormalizedMarketplaceCampaignRows(campaignQuery)
    : await readNormalizedMarketplaceCampaignRows(campaignQuery);
  if (!campaignRows) return rows;

  const campaignsByBrand = new Map<string, MarketplaceBrandCampaign[]>();
  for (const row of campaignRows) {
    const campaign = mapNormalizedMarketplaceCampaignRow(row);
    if (!campaign) continue;
    const campaigns = campaignsByBrand.get(row.brand_profile_id) ?? [];
    campaigns.push(campaign);
    campaignsByBrand.set(row.brand_profile_id, campaigns);
  }

  return rows.map((row) => ({
    ...row,
    active_campaigns: campaignsByBrand.get(row.id) ?? [],
  }));
};

const upsertNormalizedMarketplaceCampaign = async (
  organizationId: string,
  brandProfileId: string,
  campaign: MarketplaceBrandCampaign,
  actorProfileId: string,
) => {
  if (!campaign.id) return false;
  const now = new Date().toISOString();
  try {
    await upsertSupabaseV2Rows(
      marketplaceCampaignTable,
      [
        {
          id: campaign.id,
          brand_profile_id: brandProfileId,
          organization_id: organizationId,
          campaign_data: {
            ...campaign,
            statusUpdatedByProfileId: actorProfileId,
          },
          status: campaign.status ?? "open",
          created_at: campaign.createdAt ?? now,
          updated_at: campaign.updatedAt ?? now,
          archived_at: null,
        },
      ],
      "id",
    );
    return true;
  } catch (error) {
    if (!isMissingMarketplaceCampaignTableError(error)) throw error;
    if (!normalizedMarketplaceCampaignFallbackWarned) {
      console.warn(
        "[yeollock.me] marketplace_campaigns is unavailable; campaign writes remain on the legacy brand mirror until migrations are applied.",
      );
      normalizedMarketplaceCampaignFallbackWarned = true;
    }
    return false;
  }
};

const normalizeCampaignAccessInteger = (value: unknown, fallback = 0) => {
  const parsed = typeof value === "number" ? value : Number(value);
  return Number.isFinite(parsed) && parsed >= 0 ? Math.floor(parsed) : fallback;
};

const buildAdvertiserCampaignAccess = ({
  publishedCount,
  businessVerified,
}: {
  publishedCount: unknown;
  businessVerified: unknown;
}): AdvertiserCampaignAccess => {
  const normalizedPublishedCount = normalizeCampaignAccessInteger(publishedCount);
  const normalizedBusinessVerified = businessVerified === true;
  return {
    published_count: normalizedPublishedCount,
    unverified_campaign_limit: ADVERTISER_UNVERIFIED_CAMPAIGN_LIMIT,
    next_campaign_number: normalizedPublishedCount + 1,
    business_verified: normalizedBusinessVerified,
    can_publish:
      normalizedBusinessVerified ||
      normalizedPublishedCount < ADVERTISER_UNVERIFIED_CAMPAIGN_LIMIT,
    verification_required:
      !normalizedBusinessVerified &&
      normalizedPublishedCount >= ADVERTISER_UNVERIFIED_CAMPAIGN_LIMIT,
    next_path: "/advertiser/verification",
  };
};

const emptyAdvertiserCampaignAccess = (): AdvertiserCampaignAccess =>
  buildAdvertiserCampaignAccess({
    publishedCount: 0,
    businessVerified: false,
  });

const readProgressiveCampaignAccess = async (
  organizationId: string,
): Promise<AdvertiserCampaignAccess> => {
  const rpcResponse = await fetchSupabase(
    "rpc/get_progressive_campaign_access",
    "",
    {
      method: "POST",
      headers: { Prefer: "return=representation" },
      body: JSON.stringify({ p_organization_id: organizationId }),
    },
  );
  await assertSupabaseOk(rpcResponse, "Supabase progressive campaign access");
  const rows = (await rpcResponse.json()) as ProgressiveCampaignAccessRpcRow[];
  const row = rows[0];
  if (!row) {
    throw new Error("Supabase progressive campaign access returned no row");
  }
  return buildAdvertiserCampaignAccess({
    publishedCount: row.published_count,
    businessVerified: row.business_verified,
  });
};

const publishMarketplaceCampaignAtomically = async ({
  organizationId,
  brandProfileId,
  actorProfileId,
  campaign,
  publicationRequestKey,
}: {
  organizationId: string;
  brandProfileId: string;
  actorProfileId: string;
  campaign: MarketplaceBrandCampaign;
  publicationRequestKey: string;
}) => {
  if (!campaign.id) throw new Error("Campaign id is required for publication");
  const rpcResponse = await fetchSupabase("rpc/publish_marketplace_campaign", "", {
    method: "POST",
    headers: { Prefer: "return=representation" },
    body: JSON.stringify({
      p_campaign_id: campaign.id,
      p_brand_profile_id: brandProfileId,
      p_organization_id: organizationId,
      p_actor_profile_id: actorProfileId,
      p_campaign_data: {
        ...campaign,
        statusUpdatedByProfileId: actorProfileId,
      },
      p_publication_request_key: publicationRequestKey,
    }),
  });
  await assertSupabaseOk(rpcResponse, "Supabase atomic campaign publication");
  const rows = (await rpcResponse.json()) as PublishMarketplaceCampaignRpcRow[];
  const row = rows[0];
  if (!row) {
    throw new Error("Supabase atomic campaign publication returned no row");
  }

  const campaignAccess = buildAdvertiserCampaignAccess({
    publishedCount: row.result_published_count,
    businessVerified: row.result_business_verified,
  });
  if (row.result_allowed !== true) {
    return {
      allowed: false as const,
      campaignAccess,
    };
  }

  const campaignId = normalizeOptionalText(row.result_campaign_id);
  const brandId = normalizeOptionalText(row.result_brand_profile_id);
  const organizationCampaignSequence = normalizeCampaignAccessInteger(
    row.result_organization_campaign_sequence,
  );
  const gateBasis = normalizeOptionalText(
    row.result_verification_gate_basis,
  ) as CampaignVerificationGateBasis | undefined;
  const status = normalizeOptionalText(row.result_status);
  const campaignData =
    row.result_campaign_data && typeof row.result_campaign_data === "object"
      ? (row.result_campaign_data as Record<string, unknown>)
      : {};
  if (
    !campaignId ||
    !brandId ||
    !status ||
    !marketplaceCampaignStatuses.has(status) ||
    organizationCampaignSequence < 1 ||
    !gateBasis
  ) {
    throw new Error("Supabase atomic campaign publication returned invalid data");
  }
  const savedRow: SupabaseMarketplaceCampaignRow = {
    id: campaignId,
    brand_profile_id: brandId,
    organization_id: organizationId,
    campaign_data: campaignData,
    status: status as MarketplaceCampaignStatus,
    first_published_at: normalizeOptionalText(row.result_first_published_at),
    organization_campaign_sequence: organizationCampaignSequence,
    verification_gate_basis: gateBasis,
    created_at:
      normalizeOptionalText(campaignData.createdAt) ?? new Date().toISOString(),
    updated_at:
      normalizeOptionalText(campaignData.updatedAt) ?? new Date().toISOString(),
    archived_at: null,
  };
  const savedCampaign = mapNormalizedMarketplaceCampaignRow(savedRow);
  if (!savedCampaign) {
    throw new Error("Supabase atomic campaign publication returned invalid campaign");
  }

  return {
    allowed: true as const,
    created: row.result_created === true,
    campaign: savedCampaign,
    campaignAccess,
  };
};

const finalizeMarketplaceCampaignRecruitmentAtomically = async ({
  organizationId,
  brandProfileId,
  actorProfileId,
  campaign,
}: {
  organizationId: string;
  brandProfileId: string;
  actorProfileId: string;
  campaign: MarketplaceBrandCampaign;
}) => {
  if (!campaign.id) throw new Error("Campaign id is required for finalization");
  const rpcResponse = await fetchSupabase(
    "rpc/finalize_marketplace_campaign_recruitment",
    "",
    {
      method: "POST",
      headers: { Prefer: "return=representation" },
      body: JSON.stringify({
        p_campaign_id: campaign.id,
        p_brand_profile_id: brandProfileId,
        p_organization_id: organizationId,
        p_actor_profile_id: actorProfileId,
        p_campaign_data: {
          ...campaign,
          status: "closed",
          statusUpdatedByProfileId: actorProfileId,
        },
      }),
    },
  );
  await assertSupabaseOk(
    rpcResponse,
    "Supabase atomic campaign recruitment finalization",
  );
  const rows =
    (await rpcResponse.json()) as FinalizeMarketplaceCampaignRecruitmentRpcRow[];
  const row = rows[0];
  if (!row) {
    throw new Error("Supabase campaign recruitment finalization returned no row");
  }

  const campaignId = normalizeOptionalText(row.result_campaign_id);
  const status = normalizeOptionalText(row.result_status);
  const campaignData =
    row.result_campaign_data && typeof row.result_campaign_data === "object"
      ? (row.result_campaign_data as Record<string, unknown>)
      : {};
  if (!campaignId || status !== "closed") {
    throw new Error("Supabase campaign recruitment finalization returned invalid data");
  }
  const savedCampaign = mapNormalizedMarketplaceCampaignRow({
    id: campaignId,
    brand_profile_id: brandProfileId,
    organization_id: organizationId,
    campaign_data: campaignData,
    status: "closed",
    created_at:
      normalizeOptionalText(campaignData.createdAt) ?? new Date().toISOString(),
    updated_at:
      normalizeOptionalText(campaignData.updatedAt) ?? new Date().toISOString(),
    archived_at: null,
  });
  if (!savedCampaign) {
    throw new Error("Supabase campaign recruitment finalization returned invalid campaign");
  }

  return {
    campaign: savedCampaign,
    notSelectedCount: normalizeCampaignAccessInteger(
      row.result_not_selected_count,
    ),
  };
};

const reserveMarketplaceCampaignApplicationSelectionAtomically = async ({
  proposalId,
  campaignId,
  brandProfileId,
  organizationId,
  actorProfileId,
}: {
  proposalId: string;
  campaignId: string;
  brandProfileId: string;
  organizationId: string;
  actorProfileId: string;
}) => {
  const rpcResponse = await fetchSupabase(
    "rpc/reserve_marketplace_campaign_application_selection",
    "",
    {
      method: "POST",
      headers: { Prefer: "return=representation" },
      body: JSON.stringify({
        p_proposal_id: proposalId,
        p_campaign_id: campaignId,
        p_brand_profile_id: brandProfileId,
        p_organization_id: organizationId,
        p_actor_profile_id: actorProfileId,
      }),
    },
  );
  await assertSupabaseOk(
    rpcResponse,
    "Supabase atomic campaign applicant selection reservation",
  );
  const rows =
    (await rpcResponse.json()) as ReserveMarketplaceCampaignSelectionRpcRow[];
  const row = rows[0];
  const proposalStatus = normalizeOptionalText(row?.result_current_status);
  const knownProposalStatuses: MarketplaceProposalStatus[] = [
    "submitted",
    "reviewed",
    "accepted",
    "declined",
    "converted_to_contract",
    "closed",
  ];
  if (
    !row ||
    normalizeOptionalText(row.result_proposal_id) !== proposalId ||
    !knownProposalStatuses.includes(proposalStatus as MarketplaceProposalStatus)
  ) {
    throw new Error("Supabase campaign applicant selection reservation returned invalid data");
  }

  return {
    reserved: row.result_reserved === true,
    reason: normalizeOptionalText(row.result_reason),
    campaignStatus: normalizeOptionalText(row.result_campaign_status),
    proposalStatus: proposalStatus as MarketplaceProposalStatus,
  };
};

const isCampaignContractVerificationExempt = async ({
  contractId,
  organizationId,
  actorProfileId,
}: {
  contractId: string;
  organizationId: string;
  actorProfileId: string;
}) => {
  if (!isUuid(contractId) || !isUuid(organizationId) || !isUuid(actorProfileId)) {
    return false;
  }
  const rpcResponse = await fetchSupabase(
    "rpc/directsign_campaign_contract_verification_exempt",
    "",
    {
      method: "POST",
      body: JSON.stringify({
        p_contract_id: contractId,
        p_organization_id: organizationId,
        p_actor_profile_id: actorProfileId,
      }),
    },
  );
  await assertSupabaseOk(
    rpcResponse,
    "Supabase campaign contract verification exemption",
  );
  const result = (await rpcResponse.json()) as boolean | boolean[];
  return result === true || (Array.isArray(result) && result[0] === true);
};

const buildMarketplaceAvatarLabel = (name: string, fallback = "IN") => {
  const normalized = name.trim();
  if (!normalized) return fallback;
  const ascii = normalized.replace(/[^a-zA-Z0-9]/g, "");
  if (ascii.length >= 2) return ascii.slice(0, 2).toUpperCase();
  if (ascii.length === 1) return ascii.toUpperCase();
  return normalized.slice(0, 2).toUpperCase();
};

const normalizeMarketplacePublicImageUrl = (value: unknown) => {
  const clean = normalizeOptionalText(value);
  if (!clean || clean.length > 2048) return undefined;
  return /^(https?:\/\/|\/)/i.test(clean) ? clean : undefined;
};

const formatStoredMarketplacePlatformHandle = (
  handle: string,
  platform: InfluencerPlatform,
) => {
  const clean = handle.trim();
  if (!clean) return "계정 미입력";
  if (platform === "naver_blog") return clean.replace(/^@/, "");
  return clean.startsWith("@") ? clean : `@${clean}`;
};

const buildMarketplacePlatformUrl = (
  platform: InfluencerPlatform,
  handle: string,
) => {
  const clean = normalizePublicProfileHandle(handle);
  if (platform === "instagram") return `https://instagram.com/${clean}`;
  if (platform === "youtube") return `https://youtube.com/@${clean}`;
  if (platform === "tiktok") return `https://tiktok.com/@${clean}`;
  if (platform === "naver_blog") return `https://blog.naver.com/${clean}`;
  return buildInfluencerPublicProfileUrl(clean);
};

const groupMarketplaceChannelsByProfileId = (
  rows: SupabaseMarketplaceInfluencerChannelRow[],
) => {
  const grouped = new Map<string, SupabaseMarketplaceInfluencerChannelRow[]>();

  for (const row of rows) {
    const current = grouped.get(row.profile_id) ?? [];
    current.push(row);
    grouped.set(row.profile_id, current);
  }

  for (const items of grouped.values()) {
    items.sort((a, b) => Number(a.sort_order ?? 0) - Number(b.sort_order ?? 0));
  }

  return grouped;
};

const hasMisplacedNaverSelfReportProvenance = (
  channel: SupabaseMarketplaceInfluencerChannelRow,
) => {
  if (channel.platform === "naver_blog") return false;
  const metadata = channel.follower_sync_metadata;
  return (
    channel.follower_sync_source === "creator_self_report" ||
    channel.follower_sync_source === "creator_self_report_required" ||
    metadata?.provider === "creator_self_report" ||
    metadata?.metric === "average_daily_visitors_4d" ||
    metadata?.trust === "self_reported"
  );
};

const mapInfluencerProfileRowToPublicSettings = (
  row: SupabaseMarketplaceInfluencerProfileRow,
  channels: SupabaseMarketplaceInfluencerChannelRow[] = [],
): InfluencerPublicProfileSettings => ({
  ownerId: row.owner_profile_id,
  handle: row.public_handle,
  displayName: row.display_name,
  headline: row.headline,
  bio: row.bio,
  location: row.location,
  audience: row.audience,
  avatarLabel: row.avatar_label,
  avatarUrl: row.avatar_url ?? undefined,
  categories: row.categories ?? [],
  brandFit: row.brand_fit ?? [],
  collaborationTypes: normalizeCampaignProposalTypes(row.collaboration_types),
  startingPriceLabel: row.starting_price_label,
  responseTimeLabel: row.response_time_label,
  platforms: channels.map((channel) => ({
    platform: channel.platform,
    handle: channel.handle,
    url: channel.url ?? undefined,
    ownershipStatus:
      channel.ownership_status === "unverified" ? "unverified" : "verified",
  })),
  published: row.is_published,
  publicIndexEnabled: row.public_index_enabled === true,
  profileState:
    row.profile_setup_state === "complete"
      ? "complete"
      : row.profile_setup_state === "minimal"
        ? "minimal"
        : "setup_required",
  representativeActivityPageUrl:
    row.representative_activity_page_url ?? undefined,
  updatedAt: row.updated_at ?? row.created_at ?? new Date().toISOString(),
});

const mapInfluencerProfileRowToMarketplaceProfile = (
  row: SupabaseMarketplaceInfluencerProfileRow,
  channels: SupabaseMarketplaceInfluencerChannelRow[] = [],
): MarketplaceInfluencerProfile => {
  const settings = mapInfluencerProfileRowToPublicSettings(row, channels);
  const base = createMarketplaceProfileFromPublicSettings(settings);
  const mappedChannels = channels.map((channel) => {
    const ownershipStatus: "unverified" | "verified" =
      channel.ownership_status === "unverified" ? "unverified" : "verified";
    if (ownershipStatus === "unverified") {
      return {
        platform: channel.platform,
        label: channel.label || platformLabels[channel.platform],
        handle: formatStoredMarketplacePlatformHandle(
          channel.handle,
          channel.platform,
        ),
        url:
          channel.url ??
          buildMarketplacePlatformUrl(channel.platform, channel.handle),
        followersLabel: "",
        performanceLabel: "계정 인증 전",
        ownershipStatus,
      };
    }
    const isProviderMinimizedPlatform =
      channel.platform === "youtube" || channel.platform === "naver_blog";
    const hasMisplacedNaverSelfReport =
      hasMisplacedNaverSelfReportProvenance(channel);
    const followersLabel = isProviderMinimizedPlatform
      ? "계정 연동"
      : hasMisplacedNaverSelfReport
        ? "계정 연동"
        : channel.followers_label ?? "계정 연동";
    const performanceLabel = isProviderMinimizedPlatform
      ? "프로필에서 확인"
      : hasMisplacedNaverSelfReport
        ? "프로필에서 확인"
        : channel.performance_label ?? "프로필에서 확인";
    return {
      platform: channel.platform,
      label: channel.label || platformLabels[channel.platform],
      handle: formatStoredMarketplacePlatformHandle(channel.handle, channel.platform),
      url: channel.url ?? buildMarketplacePlatformUrl(channel.platform, channel.handle),
      followersLabel,
      performanceLabel,
      ownershipStatus,
    };
  });

  return {
    ...base,
    id: row.id,
    avatarUrl: row.avatar_url ?? base.avatarUrl,
    categories: normalizeMarketplaceCreatorCategories({ categories: settings.categories }),
    audienceCountries: normalizeMarketplaceCountries(row.audience_countries),
    audienceTags: row.audience_tags ?? settings.categories,
    platforms: mappedChannels.length > 0 ? mappedChannels : base.platforms,
    verifiedLabel: row.verified_label,
    recentBrands: row.recent_brands ?? base.recentBrands,
    portfolio: normalizeMarketplacePortfolio(row.portfolio),
    proposalHints: normalizeStringArrayForStorage(
      row.proposal_hints,
      base.proposalHints,
      6,
    ),
    source: "registered",
    platformVerified: mappedChannels.some(
      (channel) => channel.ownershipStatus === "verified",
    ),
    publicProfilePublished: row.is_published,
    publicProfileHandle: row.is_published ? row.public_handle : undefined,
  };
};

const formatDiscoveredMetricLabel = (value: number | null | undefined) => {
  if (!Number.isFinite(value ?? Number.NaN)) return undefined;
  const amount = Number(value);
  if (amount >= 100_000_000) {
    const label = (amount / 100_000_000).toFixed(amount >= 1_000_000_000 ? 0 : 1);
    return `${label.replace(/\.0$/, "")}억`;
  }
  if (amount >= 10_000) {
    const label = (amount / 10_000).toFixed(amount >= 100_000 ? 0 : 1);
    return `${label.replace(/\.0$/, "")}만`;
  }
  return Math.round(amount).toLocaleString("ko-KR");
};

const getDiscoveredCategoryLabel = (categories: string[]) => {
  if (categories.some((category) => /game|게임|게이머|gaming/i.test(category))) {
    return "게임";
  }
  if (categories.some((category) => /beauty|뷰티|미용|화장/i.test(category))) {
    return "뷰티";
  }
  if (
    categories.some((category) =>
      /living|리빙|라이프|생활|홈|인테리어/i.test(category),
    )
  ) {
    return "리빙";
  }
  return "콘텐츠";
};

const normalizeDiscoveredInfluencerDisplayName = (
  row: SupabaseDiscoveredInfluencerProfileRow,
) => {
  const fallback = row.platform_handle || row.public_handle || row.id;
  const rawName = normalizeRequiredText(row.display_name) || fallback;
  const handle = normalizeRequiredText(row.platform_handle || row.public_handle);
  const handleWithoutAt = handle.replace(/^@/, "");
  let name = rawName
    .replace(/\s*[|｜]\s*(?:TikTok|YouTube|Instagram|NAVER|Naver(?: Blog)?|네이버(?:\s*블로그)?)\s*$/i, "")
    .replace(/\s*[-–—]\s*(?:TikTok|YouTube|Instagram|NAVER|Naver(?: Blog)?|네이버(?:\s*블로그)?)\s*$/i, "")
    .replace(/\s*\((?:@[^)]+|[^)]*TikTok[^)]*|[^)]*YouTube[^)]*)\)\s*$/i, "")
    .replace(/\s*@[\w.]{2,32}\s*$/i, "")
    .replace(/\s{2,}/g, " ")
    .trim();

  if (!name || /^[@\W_]+$/.test(name)) {
    name = handle ? handle.replace(/^@/, "") : fallback;
  }

  if (handleWithoutAt && name.toLowerCase() === handleWithoutAt.toLowerCase()) {
    return handle.replace(/^@/, "");
  }

  return name;
};

const mapDiscoveredInfluencerRowToMarketplaceProfile = (
  row: SupabaseDiscoveredInfluencerProfileRow,
): MarketplaceInfluencerProfile => {
  const categories = normalizeMarketplaceCreatorCategories(row);
  const categoryLabel = getDiscoveredCategoryLabel(categories);
  const averageViewsLabel = formatDiscoveredMetricLabel(row.average_views);
  const postCountLabel = formatDiscoveredMetricLabel(row.post_count);
  const followerLabel =
    row.platform === "naver_blog"
      ? ""
      : normalizeOptionalText(row.followers_label) ||
        (row.follower_count
          ? `${formatDiscoveredMetricLabel(row.follower_count)}명`
          : "공개 지표 확인");
  const performanceLabel =
    row.platform === "naver_blog"
      ? "프로필에서 확인"
      : averageViewsLabel
        ? `평균 조회 ${averageViewsLabel}`
        : postCountLabel
          ? `포스트 ${postCountLabel}`
          : "채널 확인 필요";
  const displayName = normalizeDiscoveredInfluencerDisplayName(row);
  const audienceCountries = normalizeMarketplaceCountries(row.audience_countries);
  const countryLabel = formatMarketplaceCountries(audienceCountries, "국가 미확인");
  const audienceTags = normalizeStringArrayForStorage(row.audience_tags, [], 6);
  const recentPosts =
    row.platform === "naver_blog"
      ? normalizeNaverBlogRecentPosts(row.source_evidence?.recentPosts, 3)
      : [];

  return {
    id: `discovered-${row.id}`,
    handle: row.public_handle,
    displayName,
    headline:
      normalizeOptionalText(row.headline) ?? `${categoryLabel} 콘텐츠 크리에이터`,
    bio: normalizeOptionalText(row.bio) ?? "",
    location: countryLabel,
    avatarLabel: buildMarketplaceAvatarLabel(displayName),
    avatarUrl: normalizeMarketplacePublicImageUrl(row.avatar_url),
    categories: categories.length > 0 ? categories : [categoryLabel],
    audience: audienceTags.length > 0 ? audienceTags.join(" · ") : categoryLabel,
    audienceCountries,
    audienceTags: audienceTags.length > 0 ? audienceTags : categories,
    platforms: [
      {
        platform: row.platform,
        label: platformLabels[row.platform],
        handle: formatStoredMarketplacePlatformHandle(
          row.platform_handle,
          row.platform,
        ),
        url: row.profile_url,
        followersLabel: followerLabel,
        performanceLabel,
      },
    ],
    collaborationTypes: ["sponsored_post", "product_seeding", "supporters"],
    startingPriceLabel: "제안 가능",
    responseTimeLabel: "연락처 확인 필요",
    verifiedLabel: "공개 후보",
    brandFit: categories.length > 0 ? categories : [categoryLabel],
    recentBrands: [],
    portfolio: [],
    proposalHints: ["공개 채널을 확인한 뒤 광고 조건을 제안하세요."],
    recentPosts,
    source: "discovered",
  };
};

const mapBrandProfileRowToMarketplaceProfile = (
  row: SupabaseMarketplaceBrandProfileRow,
  maxCampaignItems = 20,
): MarketplaceBrandProfile => ({
  id: row.id,
  organizationId: row.organization_id,
  handle: row.public_handle,
  displayName: row.display_name,
  category: row.category,
  headline: row.headline,
  description: row.description,
  location: row.location,
  logoLabel: row.logo_label,
  logoUrl: row.logo_url ?? undefined,
  preferredPlatforms: row.preferred_platforms ?? [],
  proposalTypes: normalizeCampaignProposalTypes(row.proposal_types),
  budgetRangeLabel: row.budget_range_label,
  responseTimeLabel: row.response_time_label,
  statusLabel: row.status_label,
  fitTags: row.fit_tags ?? [],
  audienceTargets: row.audience_targets ?? [],
  activeCampaigns: normalizeBrandCampaigns(
    row.active_campaigns,
    maxCampaignItems,
  ),
  recentCreators: row.recent_creators ?? [],
  isDefault: Boolean(row.is_default),
  archivedAt: row.archived_at ?? undefined,
});

const readMarketplaceInfluencerRows = async (query: string) => {
  if (!useSupabase) {
    return {
      profiles: [] as SupabaseMarketplaceInfluencerProfileRow[],
      channels: new Map<string, SupabaseMarketplaceInfluencerChannelRow[]>(),
    };
  }

  const profiles = await readSupabaseRows<SupabaseMarketplaceInfluencerProfileRow>(
    "marketplace_influencer_profiles",
    query,
    "marketplace influencer profiles",
  );

  if (profiles.length === 0) {
    return {
      profiles,
      channels: new Map<string, SupabaseMarketplaceInfluencerChannelRow[]>(),
    };
  }

  const profileFilter = postgrestInFilter(profiles.map((profile) => profile.id));
  const channelRows = await readSupabaseRows<SupabaseMarketplaceInfluencerChannelRow>(
    "marketplace_influencer_channels",
    `?select=*&profile_id=in.${profileFilter}&order=sort_order.asc`,
    "marketplace influencer channels",
  );

  return {
    profiles,
    channels: groupMarketplaceChannelsByProfileId(channelRows),
  };
};

const marketplaceInfluencerPageSize = 100;

const clampMarketplaceInfluencerPageNumber = (
  value: unknown,
  fallback: number,
  min: number,
  max: number,
) => {
  const rawValue = Array.isArray(value) ? value[0] : value;
  const parsed =
    typeof rawValue === "string" || typeof rawValue === "number"
      ? Number.parseInt(String(rawValue), 10)
      : NaN;
  if (!Number.isFinite(parsed)) return fallback;
  return Math.min(Math.max(parsed, min), max);
};

const readMarketplaceInfluencerPage = (query: express.Request["query"]) =>
  clampMarketplaceInfluencerPageNumber(query.page, 1, 1, 100000);

const readMarketplaceInfluencerSort = (
  value: express.Request["query"][string],
): MarketplaceInfluencerSort | undefined => {
  const rawValue = Array.isArray(value) ? value[0] : value;
  return rawValue === "audience_desc" ||
    rawValue === "audience_asc" ||
    rawValue === "name_asc"
    ? rawValue
    : undefined;
};

const readMarketplaceInfluencerPlatformFilter = (
  value: express.Request["query"][string],
) => {
  const rawValue = Array.isArray(value) ? value[0] : value;
  if (typeof rawValue !== "string") return undefined;
  return influencerPlatforms.has(rawValue as InfluencerPlatform)
    ? (rawValue as InfluencerPlatform)
    : undefined;
};

const readMarketplaceInfluencerFilterValues = (
  value: express.Request["query"][string],
) => {
  const values = Array.isArray(value) ? value : value === undefined ? [] : [value];
  return values
    .filter((item): item is string => typeof item === "string")
    .map((item) => item.trim())
    .filter(Boolean);
};

const readMarketplaceInfluencerSearchFilters = (
  query: express.Request["query"],
) => {
  const rawSearch = Array.isArray(query.search) ? query.search[0] : query.search;
  const search = typeof rawSearch === "string" ? rawSearch.trim().slice(0, 120) : "";
  const categoryValues = readMarketplaceInfluencerFilterValues(query.category);
  const categories = categoryValues
    .map((category) => normalizeMarketplaceCreatorCategory(category))
    .filter(Boolean);
  const countryValues = readMarketplaceInfluencerFilterValues(query.country);
  const countries = countryValues.filter(
    (country): country is MarketplaceCountryCode => isMarketplaceCountryCode(country),
  );

  return {
    filters: {
      search: search || undefined,
      categories: [...new Set(categories)],
      countries: [...new Set(countries)],
    } satisfies MarketplaceInfluencerSearchFilters,
    invalid: [
      ...categoryValues.filter(
        (category) => !normalizeMarketplaceCreatorCategory(category),
      ),
      ...countryValues.filter((country) => !isMarketplaceCountryCode(country)),
    ],
  };
};

const sortMarketplaceInfluencerProfiles = (
  profiles: MarketplaceInfluencerProfile[],
  sort: MarketplaceInfluencerSort,
  platform?: InfluencerPlatform,
) =>
  [...profiles].sort((left, right) => {
    if (sort === "name_asc") {
      return (
        left.displayName.localeCompare(right.displayName, "ko-KR", {
          numeric: true,
          sensitivity: "base",
        }) || left.handle.localeCompare(right.handle, "en")
      );
    }

    const channelsForSort = (profile: MarketplaceInfluencerProfile) =>
      platform
        ? profile.platforms.filter((channel) => channel.platform === platform)
        : profile.platforms;
    return (
      compareChannelAudienceValues(
        getChannelAudienceSortValue(channelsForSort(left)),
        getChannelAudienceSortValue(channelsForSort(right)),
        sort === "audience_asc" ? "asc" : "desc",
      ) ||
      left.displayName.localeCompare(right.displayName, "ko-KR", {
        numeric: true,
        sensitivity: "base",
      }) ||
      left.handle.localeCompare(right.handle, "en")
    );
  });

const hydrateMarketplaceInfluencerDirectoryReferences = async (
  references: MarketplaceInfluencerDirectoryReference[],
) => {
  if (references.length === 0) return [] as MarketplaceInfluencerProfile[];

  const registeredIds = references
    .filter((item) => item.sourceType === "registered")
    .map((item) => item.sourceId);
  const discoveredIds = references
    .filter((item) => item.sourceType === "discovered")
    .map((item) => item.sourceId);
  const registeredPromise = registeredIds.length
    ? readMarketplaceInfluencerRows(
        `?select=*&id=in.${postgrestInFilter(registeredIds)}`,
      )
    : Promise.resolve({
        profiles: [] as SupabaseMarketplaceInfluencerProfileRow[],
        channels: new Map<string, SupabaseMarketplaceInfluencerChannelRow[]>(),
      });
  const discoveredPromise = discoveredIds.length
    ? readSupabaseRows<SupabaseDiscoveredInfluencerProfileRow>(
        "discovered_influencer_profiles",
        `?select=*&id=in.${postgrestInFilter(discoveredIds)}`,
        "indexed discovered influencer profiles",
      )
    : Promise.resolve([] as SupabaseDiscoveredInfluencerProfileRow[]);
  const [{ profiles: registeredRows, channels }, discoveredRows] =
    await Promise.all([registeredPromise, discoveredPromise]);
  const hydrated = new Map<string, MarketplaceInfluencerProfile>();

  for (const row of registeredRows) {
    const profile = mapInfluencerProfileRowToMarketplaceProfile(
      row,
      channels.get(row.id) ?? [],
    );
    if (
      row.is_published &&
      (!filterOperationalMarketplaceTestData ||
        (row.data_origin === "production" && !hasOperationalTestMarker(profile)))
    ) {
      hydrated.set(`registered:${row.id}`, profile);
    }
  }
  for (const row of discoveredRows) {
    const profile = mapDiscoveredInfluencerRowToMarketplaceProfile(row);
    const eligibility = classifyMarketplacePublicInfluencerEligibility(row);
    if (
      eligibility.eligible &&
      (!filterOperationalMarketplaceTestData || !hasOperationalTestMarker(profile))
    ) {
      hydrated.set(`discovered:${row.id}`, profile);
    }
  }

  const ordered = references
    .map((item) => hydrated.get(item.listingKey))
    .filter((profile): profile is MarketplaceInfluencerProfile => Boolean(profile));
  if (ordered.length !== references.length) {
    throw new Error("Marketplace influencer directory is out of sync");
  }
  return ordered;
};

const parseMarketplaceInfluencerDirectoryPayload = (
  value: unknown,
): {
  references: MarketplaceInfluencerDirectoryReference[];
  total: number;
  page: number;
  totalPages: number;
  hasMore: boolean;
} => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("Marketplace influencer directory response was invalid");
  }
  const payload = value as MarketplaceInfluencerDirectoryRpcPayload;
  const references = (Array.isArray(payload.items) ? payload.items : []).map(
    (item) => {
      const listingKey = typeof item.listing_key === "string" ? item.listing_key : "";
      const sourceType = item.source_type;
      const sourceId = typeof item.source_id === "string" ? item.source_id : "";
      const publicHandle =
        typeof item.public_handle === "string" ? item.public_handle : "";
      if (
        !listingKey ||
        (sourceType !== "registered" && sourceType !== "discovered") ||
        !isUuid(sourceId) ||
        !normalizePublicProfileHandle(publicHandle)
      ) {
        throw new Error("Marketplace influencer directory item was invalid");
      }
      return {
        listingKey,
        sourceType,
        sourceId,
        publicHandle,
      } satisfies MarketplaceInfluencerDirectoryReference;
    },
  );
  const total = Number(payload.total);
  const page = Number(payload.page);
  const pageSize = Number(payload.page_size);
  const totalPages = Number(payload.total_pages);
  if (
    !Number.isSafeInteger(total) ||
    total < 0 ||
    !Number.isSafeInteger(page) ||
    page < 1 ||
    pageSize !== marketplaceInfluencerPageSize ||
    !Number.isSafeInteger(totalPages) ||
    totalPages !== Math.ceil(total / marketplaceInfluencerPageSize) ||
    references.length > marketplaceInfluencerPageSize
  ) {
    throw new Error("Marketplace influencer directory pagination was invalid");
  }
  return {
    references,
    total,
    page,
    totalPages,
    hasMore: page < totalPages,
  };
};

type MarketplaceAuthenticatedInfluencerDirectoryItem =
  | MarketplaceInfluencerDirectoryReference
  | MarketplaceRegisteredInfluencerDirectoryItem;

const readMarketplaceRpcStringArray = (value: unknown, limit = 20) =>
  Array.isArray(value)
    ? Array.from(
        new Set(
          value
            .filter((item): item is string => typeof item === "string")
            .map((item) => item.trim())
            .filter(Boolean),
        ),
      ).slice(0, limit)
    : [];

const parseMarketplaceRegisteredInfluencerDirectoryItem = (
  item: NonNullable<MarketplaceInfluencerDirectoryRpcPayload["items"]>[number],
): MarketplaceRegisteredInfluencerDirectoryItem => {
  const listingKey = typeof item.listing_key === "string" ? item.listing_key : "";
  const publicHandle =
    typeof item.public_handle === "string"
      ? normalizePublicProfileHandle(item.public_handle)
      : "";
  const displayName =
    typeof item.display_name === "string" ? item.display_name.trim() : "";
  const categoryKeys = readMarketplaceRpcStringArray(item.category_keys).map(
    (category) => normalizeMarketplaceCreatorCategory(category),
  ).filter(Boolean);
  const creatorCountries = readMarketplaceRpcStringArray(item.creator_countries)
    .filter(
      (country): country is MarketplaceCountryCode =>
        isMarketplaceCountryCode(country),
    );
  const platforms = readMarketplaceRpcStringArray(item.platforms).filter(
    (platform): platform is InfluencerPlatform =>
      influencerPlatforms.has(platform as InfluencerPlatform),
  );
  const verifiedChannels = (Array.isArray(item.verified_channels)
    ? item.verified_channels
    : []
  ).map((value) => {
    if (!value || typeof value !== "object" || Array.isArray(value)) {
      throw new Error("Registered influencer verified channel was invalid");
    }
    const channel = value as Record<string, unknown>;
    const platform = channel.platform;
    const handle =
      typeof channel.handle === "string" ? channel.handle.trim().replace(/^@+/, "") : "";
    if (
      typeof platform !== "string" ||
      !influencerPlatforms.has(platform as InfluencerPlatform) ||
      !handle ||
      handle.length > 160
    ) {
      throw new Error("Registered influencer verified channel was invalid");
    }
    const url = normalizeMarketplacePublicImageUrl(channel.url);
    const followerCountValue = Number(channel.follower_count);
    const followerCount =
      platform !== "youtube" &&
      platform !== "naver_blog" &&
      channel.follower_count !== undefined &&
      channel.follower_count !== null &&
      Number.isSafeInteger(followerCountValue) &&
      followerCountValue >= 0
        ? followerCountValue
        : undefined;
    return {
      platform: platform as InfluencerPlatform,
      handle,
      ...(url ? { url } : {}),
      ...(followerCount !== undefined ? { followerCount } : {}),
    };
  });
  const maxAudienceCount = verifiedChannels.reduce<number | undefined>(
    (maximum, channel) => {
      if (
        channel.platform === "youtube" ||
        channel.platform === "naver_blog" ||
        channel.followerCount === undefined
      ) {
        return maximum;
      }
      return maximum === undefined
        ? channel.followerCount
        : Math.max(maximum, channel.followerCount);
    },
    undefined,
  );
  const platformVerified = item.platform_verified === true;
  const publicProfilePublished = item.public_profile_published === true;
  const publicProfileHandle =
    typeof item.public_profile_handle === "string"
      ? normalizePublicProfileHandle(item.public_profile_handle)
      : "";
  const avatarUrl = normalizeMarketplacePublicImageUrl(item.avatar_url);
  const countryDisplayLabel =
    typeof item.country_display_label === "string"
      ? item.country_display_label.trim()
      : "";

  if (
    item.source_type !== "registered_member" ||
    !/^rm-[a-f0-9]{27}$/.test(publicHandle) ||
    listingKey !== `registered_member:${publicHandle}` ||
    !displayName ||
    displayName.length > 120 ||
    item.registered_member_visibility !== "authenticated_advertisers" ||
    platformVerified !== (platforms.length > 0 && verifiedChannels.length > 0) ||
    verifiedChannels.some((channel) => !platforms.includes(channel.platform)) ||
    (creatorCountries.length === 0 && countryDisplayLabel !== "국가 미확인") ||
    (creatorCountries.length > 0 && countryDisplayLabel !== "") ||
    publicProfilePublished !== Boolean(publicProfileHandle)
  ) {
    throw new Error("Registered influencer directory item was invalid");
  }

  return {
    listingKey,
    sourceType: "registered_member",
    publicHandle,
    displayName,
    ...(avatarUrl ? { avatarUrl } : {}),
    categoryKeys,
    creatorCountries,
    countryDisplayLabel,
    platforms,
    verifiedChannels,
    ...(maxAudienceCount !== undefined ? { maxAudienceCount } : {}),
    registeredMemberVisibility: "authenticated_advertisers",
    platformVerified,
    publicProfilePublished,
    ...(publicProfileHandle ? { publicProfileHandle } : {}),
  };
};

const parseAuthenticatedMarketplaceInfluencerDirectoryPayload = (
  value: unknown,
): {
  items: MarketplaceAuthenticatedInfluencerDirectoryItem[];
  total: number;
  page: number;
  totalPages: number;
  hasMore: boolean;
} => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("Authenticated influencer directory response was invalid");
  }
  const payload = value as MarketplaceInfluencerDirectoryRpcPayload;
  const rawItems = Array.isArray(payload.items) ? payload.items : [];
  const items = rawItems.map((item) => {
    if (item.source_type === "registered_member") {
      return parseMarketplaceRegisteredInfluencerDirectoryItem(item);
    }
    const listingKey = typeof item.listing_key === "string" ? item.listing_key : "";
    const sourceType = item.source_type;
    const sourceId = typeof item.source_id === "string" ? item.source_id : "";
    const publicHandle =
      typeof item.public_handle === "string" ? item.public_handle : "";
    if (
      !listingKey ||
      (sourceType !== "registered" && sourceType !== "discovered") ||
      !isUuid(sourceId) ||
      !normalizePublicProfileHandle(publicHandle)
    ) {
      throw new Error("Authenticated influencer directory item was invalid");
    }
    return {
      listingKey,
      sourceType,
      sourceId,
      publicHandle,
    } satisfies MarketplaceInfluencerDirectoryReference;
  });
  const total = Number(payload.total);
  const page = Number(payload.page);
  const pageSize = Number(payload.page_size);
  const totalPages = Number(payload.total_pages);
  if (
    !Number.isSafeInteger(total) ||
    total < 0 ||
    !Number.isSafeInteger(page) ||
    page < 1 ||
    pageSize !== marketplaceInfluencerPageSize ||
    !Number.isSafeInteger(totalPages) ||
    totalPages !== Math.ceil(total / marketplaceInfluencerPageSize) ||
    items.length > marketplaceInfluencerPageSize
  ) {
    throw new Error("Authenticated influencer directory pagination was invalid");
  }
  return {
    items,
    total,
    page,
    totalPages,
    hasMore: page < totalPages,
  };
};

const mapRegisteredInfluencerDirectoryItemToMarketplaceProfile = (
  item: MarketplaceRegisteredInfluencerDirectoryItem,
): MarketplaceInfluencerProfile => {
  const categories = normalizeMarketplaceCreatorCategories({
    categories: item.categoryKeys,
  });
  const verifiedChannels = item.verifiedChannels.map((channel) => ({
    platform: channel.platform,
    label: platformLabels[channel.platform],
    handle: formatStoredMarketplacePlatformHandle(channel.handle, channel.platform),
    url: channel.url ?? buildMarketplacePlatformUrl(channel.platform, channel.handle),
    followersLabel:
      channel.platform === "youtube" ||
      channel.platform === "naver_blog" ||
      channel.followerCount === undefined
        ? ""
        : `${channel.followerCount.toLocaleString("ko-KR")}명`,
    performanceLabel: "계정 인증 완료",
  }));

  return {
    id: item.listingKey,
    handle: item.publicHandle,
    displayName: item.displayName,
    headline: "",
    bio: "",
    location:
      item.creatorCountries.length > 0
        ? formatMarketplaceCountries(item.creatorCountries)
        : item.countryDisplayLabel,
    avatarLabel: buildMarketplaceAvatarLabel(item.displayName),
    avatarUrl: item.avatarUrl,
    categories,
    audience: "",
    audienceCountries: item.creatorCountries,
    audienceTags: [],
    platforms: verifiedChannels,
    collaborationTypes: [],
    startingPriceLabel: "정보 미입력",
    responseTimeLabel: "정보 미입력",
    verifiedLabel: item.platformVerified ? "계정 인증 완료" : "계정 인증 전",
    brandFit: [],
    recentBrands: [],
    portfolio: [],
    proposalHints: [],
    source: "registered",
    registrationVisibility: item.registeredMemberVisibility,
    platformVerified: item.platformVerified,
    publicProfilePublished: item.publicProfilePublished,
    publicProfileHandle: item.publicProfileHandle,
  };
};

const hydrateAuthenticatedMarketplaceInfluencerDirectoryItems = async (
  items: MarketplaceAuthenticatedInfluencerDirectoryItem[],
) => {
  const publicReferences = items.filter(
    (item): item is MarketplaceInfluencerDirectoryReference =>
      item.sourceType !== "registered_member",
  );
  const publicProfiles = await hydrateMarketplaceInfluencerDirectoryReferences(
    publicReferences,
  );
  const publicProfilesByListingKey = new Map(
    publicReferences.map((reference, index) => [
      reference.listingKey,
      publicProfiles[index],
    ]),
  );

  return items.map((item) => {
    if (item.sourceType === "registered_member") {
      return mapRegisteredInfluencerDirectoryItemToMarketplaceProfile(item);
    }
    const profile = publicProfilesByListingKey.get(item.listingKey);
    if (!profile) throw new Error("Authenticated influencer directory is out of sync");
    return profile;
  });
};

const readIndexedMarketplaceInfluencerPage = async ({
  page,
  sort,
  filters,
  savedOnly = false,
  organizationId,
}: {
  page: number;
  sort: MarketplaceInfluencerSort;
  filters: MarketplaceInfluencerSearchFilters;
  savedOnly?: boolean;
  organizationId?: string;
}) => {
  if (!useSupabase) {
    const fallbackProfiles = sortMarketplaceInfluencerProfiles(
      fallbackMarketplaceInfluencerProfiles(),
      sort,
      filters.platform,
    );
    const fallbackPage = paginateMarketplaceInfluencerProfiles(fallbackProfiles, {
      ...filters,
      limit: marketplaceInfluencerPageSize,
      offset: (page - 1) * marketplaceInfluencerPageSize,
    });
    return {
      ...fallbackPage,
      page,
      pageSize: marketplaceInfluencerPageSize,
      totalPages: Math.ceil(fallbackPage.total / marketplaceInfluencerPageSize),
    };
  }

  const rpcResponse = await fetchSupabase(
    "rpc/list_marketplace_influencers",
    "",
    {
      method: "POST",
      body: JSON.stringify({
        p_search: filters.search ?? null,
        p_platform: filters.platform ?? null,
        p_categories: filters.categories ?? [],
        p_countries: filters.countries ?? [],
        p_sort: sort,
        p_page: page,
        p_saved_only: savedOnly,
        p_organization_id: organizationId ?? null,
      }),
    },
  );
  await assertSupabaseOk(rpcResponse, "Supabase influencer directory search");
  const parsed = parseMarketplaceInfluencerDirectoryPayload(
    await rpcResponse.json(),
  );
  const profiles = await hydrateMarketplaceInfluencerDirectoryReferences(
    parsed.references,
  );
  return {
    profiles,
    total: parsed.total,
    page: parsed.page,
    pageSize: marketplaceInfluencerPageSize,
    totalPages: parsed.totalPages,
    hasMore: parsed.hasMore,
  };
};

const readAuthenticatedMarketplaceInfluencerPage = async ({
  accessToken,
  organizationId,
  page,
  sort,
  filters,
  savedOnly = false,
}: {
  accessToken: string;
  organizationId: string;
  page: number;
  sort: MarketplaceInfluencerSort;
  filters: MarketplaceInfluencerSearchFilters;
  savedOnly?: boolean;
}) => {
  if (!useSupabase) {
    return readIndexedMarketplaceInfluencerPage({
      page,
      sort,
      filters,
      savedOnly,
      organizationId,
    });
  }

  const rpcResponse = await fetchSupabaseAsUser(
    "rpc/list_authenticated_marketplace_influencers",
    accessToken,
    "",
    {
      method: "POST",
      body: JSON.stringify({
        p_organization_id: organizationId,
        p_search: filters.search ?? null,
        p_platform: filters.platform ?? null,
        p_categories: filters.categories ?? [],
        p_countries: filters.countries ?? [],
        p_sort: sort,
        p_page: page,
        p_page_size: marketplaceInfluencerPageSize,
        p_saved_only: savedOnly,
      }),
      signal: AbortSignal.timeout(
        authenticatedMarketplaceInfluencerDirectoryTimeoutMs,
      ),
    },
  );
  const accessError =
    rpcResponse.status === 403
      ? await rpcResponse
          .clone()
          .json()
          .catch(() => undefined)
      : undefined;
  if (
    accessError &&
    typeof accessError === "object" &&
    "code" in accessError &&
    accessError.code === "42501" &&
    "message" in accessError &&
    accessError.message === "authenticated production advertiser profile required"
  ) {
    await rpcResponse.arrayBuffer();
    throw new AuthenticatedInfluencerDirectoryAccessError();
  }
  await assertSupabaseOk(
    rpcResponse,
    "Supabase authenticated influencer directory search",
  );
  const parsed = parseAuthenticatedMarketplaceInfluencerDirectoryPayload(
    await rpcResponse.json(),
  );
  const profiles = await hydrateAuthenticatedMarketplaceInfluencerDirectoryItems(
    parsed.items,
  );
  return {
    profiles,
    total: parsed.total,
    page: parsed.page,
    pageSize: marketplaceInfluencerPageSize,
    totalPages: parsed.totalPages,
    hasMore: parsed.hasMore,
  };
};

class AuthenticatedInfluencerDirectoryAccessError extends Error {
  constructor() {
    super("Authenticated production advertiser profile required");
    this.name = "AuthenticatedInfluencerDirectoryAccessError";
  }
}

export const isAuthenticatedInfluencerDirectoryTimeoutError = (
  error: unknown,
) => error instanceof Error && error.name === "TimeoutError";

const readPublicMarketplaceInfluencerProfileByHandle = async (handle: string) => {
  const normalizedHandle = normalizePublicProfileHandle(handle);
  if (!normalizedHandle) return undefined;

  if (useSupabase) {
    const directoryRows = await readSupabaseRows<{
      listing_key: string;
      source_type: "registered" | "discovered";
      source_id: string;
      public_handle: string;
    }>(
      "marketplace_public_influencer_directory",
      `?select=listing_key,source_type,source_id,public_handle&public_handle=eq.${encodeURIComponent(
        normalizedHandle,
      )}&limit=4`,
      "marketplace influencer directory handle",
    );
    const directoryRow = directoryRows.sort((left, right) =>
      left.source_type === right.source_type
        ? left.listing_key.localeCompare(right.listing_key)
        : left.source_type === "registered"
          ? -1
          : 1,
    )[0];
    if (directoryRow) {
      const profiles = await hydrateMarketplaceInfluencerDirectoryReferences([
        {
          listingKey: directoryRow.listing_key,
          sourceType: directoryRow.source_type,
          sourceId: directoryRow.source_id,
          publicHandle: directoryRow.public_handle,
        },
      ]);
      return profiles[0];
    }

    let profileQuery = `?select=*&public_handle=eq.${encodeURIComponent(
      normalizedHandle,
    )}&is_published=eq.true&data_origin=eq.production&limit=1`;
    if (/^rm-[a-f0-9]{27}$/.test(normalizedHandle)) {
      const aliases = await readSupabaseRows<{
        public_marketplace_profile_id: string;
      }>(
        "marketplace_registered_influencer_directory",
        `?select=public_marketplace_profile_id&registered_handle=eq.${encodeURIComponent(
          normalizedHandle,
        )}&public_profile_published=eq.true&limit=1`,
        "registered influencer direct-profile alias",
      );
      const aliasProfileId = aliases[0]?.public_marketplace_profile_id;
      if (!isUuid(aliasProfileId)) return undefined;
      profileQuery = `?select=*&id=eq.${encodeURIComponent(
        aliasProfileId,
      )}&is_published=eq.true&data_origin=eq.production&limit=1`;
    }

    const { profiles: directRows, channels } =
      await readMarketplaceInfluencerRows(profileQuery);
    const directRow = directRows[0];
    if (!directRow) return undefined;
    const profile = mapInfluencerProfileRowToMarketplaceProfile(
      directRow,
      channels.get(directRow.id) ?? [],
    );
    if (filterOperationalMarketplaceTestData && hasOperationalTestMarker(profile)) {
      return undefined;
    }
    return profile;
  }

  return findInfluencerProfileByHandle(
    normalizedHandle,
    fallbackMarketplaceInfluencerProfiles(),
  );
};

const readRegisteredMarketplaceInfluencerByStableHandle = async (handle: string) => {
  const normalizedHandle = normalizePublicProfileHandle(handle);
  if (!useSupabase || !/^rm-[a-f0-9]{27}$/.test(normalizedHandle)) {
    return undefined;
  }

  const rows = await readSupabaseRows<
    SupabaseMarketplaceRegisteredInfluencerDirectoryRow
  >(
    "marketplace_registered_influencer_directory",
    `?select=registered_handle,display_name,avatar_url,category_keys,creator_countries,country_display_label,platforms,verified_channels,max_audience_count,registered_member_visibility,platform_verified,public_marketplace_profile_id,public_profile_published,public_profile_handle&registered_handle=eq.${encodeURIComponent(
      normalizedHandle,
    )}&limit=1`,
    "registered influencer stable-handle lookup",
  );
  const row = rows[0];
  if (!row || !isUuid(row.public_marketplace_profile_id)) return undefined;

  const item = parseMarketplaceRegisteredInfluencerDirectoryItem({
    listing_key: `registered_member:${row.registered_handle}`,
    source_type: "registered_member",
    public_handle: row.registered_handle,
    display_name: row.display_name,
    avatar_url: row.avatar_url,
    category_keys: row.category_keys,
    creator_countries: row.creator_countries,
    country_display_label: row.country_display_label,
    platforms: row.platforms,
    verified_channels: row.verified_channels,
    max_audience_count: row.max_audience_count,
    registered_member_visibility: row.registered_member_visibility,
    platform_verified: row.platform_verified,
    public_profile_published: row.public_profile_published,
    public_profile_handle: row.public_profile_handle,
  });
  return {
    profile: mapRegisteredInfluencerDirectoryItemToMarketplaceProfile(item),
    marketplaceProfileId: row.public_marketplace_profile_id,
  };
};

const readAdvertiserVisibleMarketplaceInfluencerByHandle = async (handle: string) => {
  const publicProfile = await readPublicMarketplaceInfluencerProfileByHandle(handle);
  if (publicProfile) {
    return {
      profile: publicProfile,
      marketplaceProfileId:
        publicProfile.source === "registered" && isUuid(publicProfile.id)
          ? publicProfile.id
          : undefined,
    };
  }
  return readRegisteredMarketplaceInfluencerByStableHandle(handle);
};

const readAdvertiserSavedInfluencerRows = async (organizationId: string) => {
  if (!useSupabase) return [] as SupabaseAdvertiserSavedInfluencerRow[];
  const pageSize = 1000;
  const rows: SupabaseAdvertiserSavedInfluencerRow[] = [];
  for (let offset = 0; ; offset += pageSize) {
    const page = await readSupabaseRows<SupabaseAdvertiserSavedInfluencerRow>(
      "advertiser_saved_influencers",
      `?select=*&organization_id=eq.${encodeURIComponent(
        organizationId,
      )}&order=created_at.desc&limit=${pageSize}&offset=${offset}`,
      "advertiser saved influencers",
    );
    rows.push(...page);
    if (page.length < pageSize) break;
  }
  return rows;
};

const mutateAdvertiserSavedInfluencer = async ({
  organizationId,
  profileId,
  requestedHandle,
  saved,
}: {
  organizationId: string;
  profileId: string;
  requestedHandle: string;
  saved: boolean;
}) => {
  const response = await fetchSupabase(
    "rpc/mutate_marketplace_saved_influencer",
    "",
    {
      method: "POST",
      body: JSON.stringify({
        p_organization_id: organizationId,
        p_created_by_profile_id: profileId,
        p_requested_handle: requestedHandle,
        p_saved: saved,
      }),
    },
  );
  await assertSupabaseOk(
    response,
    "Supabase saved influencer mutation",
  );
  const payload = (await response.json()) as unknown;
  const row = Array.isArray(payload) ? payload[0] : undefined;
  const canonicalHandle = normalizePublicProfileHandle(
    row && typeof row === "object" && "handle" in row
      ? String(row.handle ?? "")
      : "",
  );
  if (!canonicalHandle) {
    throw new Error("Supabase returned an invalid saved influencer mutation");
  }
  return {
    handle: canonicalHandle,
    requested_handle: requestedHandle,
    saved,
  };
};

const readMarketplaceBrandProfiles = async () => {
  if (!useSupabase) return fallbackMarketplaceBrandProfiles();

  const rawRows = await readSupabaseRows<SupabaseMarketplaceBrandProfileRow>(
    "marketplace_brand_profiles",
    `?select=*&is_published=eq.true&archived_at=is.null${
      filterOperationalMarketplaceTestData ? "&data_origin=eq.production" : ""
    }&order=updated_at.desc`,
    "marketplace brand profiles",
  );
  const rows = await hydrateBrandRowsWithNormalizedCampaigns(rawRows, {
    readAll: true,
  });

  const dbProfiles = rows.map(mapBrandProfileRowToMarketplaceProfile);
  const visibleDbProfiles = dbProfiles.filter(
    (profile) =>
      !filterOperationalMarketplaceTestData || !hasOperationalTestMarker(profile),
  );
  if (allowPublicMarketplaceCatalogFallback) {
    return mergeMarketplaceBrandProfiles(visibleDbProfiles);
  }
  return visibleDbProfiles.length > 0
    ? visibleDbProfiles
    : fallbackMarketplaceBrandProfiles();
};

const readMarketplaceCampaignPosts = async () => {
  if (!useSupabase) {
    return buildMarketplaceCampaignPosts(fallbackMarketplaceBrandProfiles());
  }

  const campaignRows = await readAllNormalizedMarketplaceCampaignRows(
    "?select=*&status=eq.open&archived_at=is.null&order=created_at.desc",
  );
  if (!campaignRows) {
    return buildMarketplaceCampaignPosts(await readMarketplaceBrandProfiles());
  }
  if (campaignRows.length === 0) {
    return allowPublicMarketplaceCatalogFallback
      ? buildMarketplaceCampaignPosts(fallbackMarketplaceBrandProfiles())
      : [];
  }

  const brandIds = Array.from(
    new Set(campaignRows.map((campaign) => campaign.brand_profile_id)),
  );
  const rawBrandRows = await readSupabaseRows<SupabaseMarketplaceBrandProfileRow>(
    "marketplace_brand_profiles",
    `?select=*&id=in.${postgrestInFilter(
      brandIds,
    )}&is_published=eq.true&archived_at=is.null${
      filterOperationalMarketplaceTestData ? "&data_origin=eq.production" : ""
    }&order=updated_at.desc`,
    "marketplace campaign brand profiles",
  );
  const campaignsByBrand = new Map<string, MarketplaceBrandCampaign[]>();
  for (const row of campaignRows) {
    const campaign = mapNormalizedMarketplaceCampaignRow(row);
    if (!campaign) continue;
    const campaigns = campaignsByBrand.get(row.brand_profile_id) ?? [];
    campaigns.push(campaign);
    campaignsByBrand.set(row.brand_profile_id, campaigns);
  }

  const dbProfiles = rawBrandRows.map((row) =>
    mapBrandProfileRowToMarketplaceProfile({
      ...row,
      active_campaigns: campaignsByBrand.get(row.id) ?? [],
    }),
  );
  const visibleDbProfiles = dbProfiles.filter(
    (profile) =>
      !filterOperationalMarketplaceTestData || !hasOperationalTestMarker(profile),
  );
  const profiles = allowPublicMarketplaceCatalogFallback
    ? mergeMarketplaceBrandProfiles(visibleDbProfiles)
    : visibleDbProfiles;
  return buildMarketplaceCampaignPosts(profiles);
};

const publicMarketplaceCacheMaxAgeSeconds = 60;
const publicMarketplaceCacheStaleSeconds = 300;
const publicMarketplaceRuntimeCacheSeconds =
  publicMarketplaceCacheMaxAgeSeconds + publicMarketplaceCacheStaleSeconds;
const publicMarketplaceCacheControl = `public, max-age=${publicMarketplaceCacheMaxAgeSeconds}, stale-while-revalidate=${publicMarketplaceCacheStaleSeconds}`;
const publicMarketplaceCdnCacheControl = `public, s-maxage=${publicMarketplaceCacheMaxAgeSeconds}, stale-while-revalidate=${publicMarketplaceCacheStaleSeconds}`;

type PublicMarketplaceCacheKey =
  | "marketplace-influencers"
  | "marketplace-brands"
  | "marketplace-campaigns";

type RuntimeCacheClient = {
  get: <T>(key: string) => Promise<T | undefined>;
  set: <T>(
    key: string,
    value: T,
    options?: { ttl?: number; tags?: string[]; name?: string },
  ) => Promise<void>;
  delete: (key: string) => Promise<void>;
  expireTag: (tag: string | string[]) => Promise<void>;
};
type RuntimeCachePurgeModule = {
  invalidateByTag?: (tag: string | string[]) => Promise<void>;
};

type PublicMarketplaceCacheEntry<T> = {
  value?: T;
  expiresAt: number;
  staleUntil: number;
  refresh?: Promise<T>;
};

type PublicMarketplaceCacheOptions<T> = {
  fallback?: () => T;
};

const fallbackMarketplaceInfluencerProfiles = () =>
  allowPublicMarketplaceCatalogFallback ? mergeMarketplaceInfluencerProfiles() : [];

const fallbackMarketplaceBrandProfiles = () =>
  allowPublicMarketplaceCatalogFallback ? mergeMarketplaceBrandProfiles() : [];

const fallbackMarketplaceCampaignPosts = () =>
  buildMarketplaceCampaignPosts(fallbackMarketplaceBrandProfiles());

const isEmptyPublicMarketplaceValue = (value: unknown) =>
  Array.isArray(value) && value.length === 0;

const applyPublicMarketplaceFallback = <T,>(
  value: T,
  options: PublicMarketplaceCacheOptions<T>,
) => {
  if (!isEmptyPublicMarketplaceValue(value) || !options.fallback) return value;
  const fallbackValue = options.fallback();
  return isEmptyPublicMarketplaceValue(fallbackValue) ? value : fallbackValue;
};

const publicMarketplaceCache = new Map<
  PublicMarketplaceCacheKey,
  PublicMarketplaceCacheEntry<unknown>
>();

const publicMarketplaceCacheTags: Record<PublicMarketplaceCacheKey, string[]> = {
  "marketplace-influencers": ["marketplace", "marketplace:influencers"],
  "marketplace-brands": ["marketplace", "marketplace:brands"],
  "marketplace-campaigns": [
    "marketplace",
    "marketplace:campaigns",
    "marketplace:brands",
  ],
};
const publicMarketplaceAllTags = Array.from(
  new Set(Object.values(publicMarketplaceCacheTags).flat()),
);
let runtimeCachePromise: Promise<RuntimeCacheClient | undefined> | undefined;

const getPublicMarketplaceRuntimeCacheKey = (key: PublicMarketplaceCacheKey) =>
  `public-marketplace:${key}:v3`;

const getVercelRuntimeCache = async () => {
  if (process.env.DISABLE_VERCEL_RUNTIME_CACHE === "1") return undefined;
  runtimeCachePromise ??= import("@vercel/functions")
    .then(({ getCache }) =>
      getCache({
        namespace: "yeollock-api-v1",
      }) as RuntimeCacheClient,
    )
    .catch((error) => {
      console.warn(
        `[${productName}] Vercel runtime cache unavailable: ${
          operationalErrorLabel(error)
        }`,
      );
      return undefined;
    });
  return runtimeCachePromise;
};

const readPublicMarketplaceRuntimeCache = async <T,>(
  key: PublicMarketplaceCacheKey,
) => {
  const cache = await getVercelRuntimeCache();
  if (!cache) return undefined;
  const value = await cache.get<T | null>(getPublicMarketplaceRuntimeCacheKey(key));
  return value === null ? undefined : value;
};

const writePublicMarketplaceRuntimeCache = async <T,>(
  key: PublicMarketplaceCacheKey,
  value: T,
) => {
  const cache = await getVercelRuntimeCache();
  if (!cache) return;
  await cache.set(getPublicMarketplaceRuntimeCacheKey(key), value, {
    ttl: publicMarketplaceRuntimeCacheSeconds,
    tags: publicMarketplaceCacheTags[key],
    name: key,
  });
};

const expirePublicMarketplaceRuntimeCache = async (tags = publicMarketplaceAllTags) => {
  if (process.env.DISABLE_VERCEL_RUNTIME_CACHE === "1") return;
  const cache = await getVercelRuntimeCache();
  await cache?.expireTag(tags).catch((error) => {
    console.warn(
      `[${productName}] public marketplace runtime cache invalidation failed: ${
        operationalErrorLabel(error)
      }`,
    );
  });
  await import("@vercel/functions")
    .then((module: RuntimeCachePurgeModule) => module.invalidateByTag?.(tags))
    .catch((error) => {
      console.warn(
        `[${productName}] public marketplace CDN cache invalidation failed: ${
          operationalErrorLabel(error)
        }`,
      );
    });
};

const rememberPublicMarketplaceMemoryCache = <T,>(
  key: PublicMarketplaceCacheKey,
  value: T,
) => {
  const now = Date.now();
  publicMarketplaceCache.set(key, {
    value,
    expiresAt: now + publicMarketplaceCacheMaxAgeSeconds * 1000,
    staleUntil:
      now +
      publicMarketplaceRuntimeCacheSeconds *
        1000,
  });
};

const refreshPublicMarketplaceCache = async <T,>(
  key: PublicMarketplaceCacheKey,
  loader: () => Promise<T>,
  options: PublicMarketplaceCacheOptions<T> = {},
) => {
  const value = applyPublicMarketplaceFallback(await loader(), options);
  rememberPublicMarketplaceMemoryCache(key, value);
  void writePublicMarketplaceRuntimeCache(key, value).catch((error) => {
    console.warn(
      `[${productName}] public marketplace runtime cache write failed: ${
        operationalErrorLabel(error)
      }`,
    );
  });
  return value;
};

const readPublicMarketplaceCache = async <T,>(
  key: PublicMarketplaceCacheKey,
  loader: () => Promise<T>,
  options: PublicMarketplaceCacheOptions<T> = {},
) => {
  const now = Date.now();
  const cached = publicMarketplaceCache.get(
    key,
  ) as PublicMarketplaceCacheEntry<T> | undefined;

  if (cached?.value !== undefined && cached.expiresAt > now) {
    return cached.value;
  }

  if (cached?.value !== undefined && cached.staleUntil > now) {
    if (!cached.refresh) {
      cached.refresh = refreshPublicMarketplaceCache(key, loader, options)
        .catch((error) => {
          console.warn(
            `[${productName}] public marketplace cache refresh failed: ${
              operationalErrorLabel(error)
            }`,
          );
          return cached.value as T;
        })
        .finally(() => {
          const latest = publicMarketplaceCache.get(key);
          if (latest) delete (latest as PublicMarketplaceCacheEntry<T>).refresh;
        });
      publicMarketplaceCache.set(key, cached);
    }
    return cached.value;
  }

  const runtimeCached = await readPublicMarketplaceRuntimeCache<T>(key).catch(
    (error) => {
      console.warn(
        `[${productName}] public marketplace runtime cache read failed: ${
          operationalErrorLabel(error)
        }`,
      );
      return undefined;
    },
  );
  if (runtimeCached !== undefined) {
    const value = applyPublicMarketplaceFallback(runtimeCached, options);
    rememberPublicMarketplaceMemoryCache(key, value);
    return value;
  }

  if (cached?.refresh) return cached.refresh;

  const refresh = refreshPublicMarketplaceCache(key, loader, options).catch((error) => {
    publicMarketplaceCache.delete(key);
    if (cached?.value !== undefined) return cached.value;
    if (!options.fallback) throw error;

    const value = options.fallback();
    rememberPublicMarketplaceMemoryCache(key, value);
    console.warn(
      `[${productName}] public marketplace cache cold fallback for ${key}: ${
        operationalErrorLabel(error)
      }`,
    );
    return value;
  });
  publicMarketplaceCache.set(key, {
    value: cached?.value,
    expiresAt: cached?.expiresAt ?? 0,
    staleUntil: cached?.staleUntil ?? 0,
    refresh,
  });
  return refresh;
};

const clearPublicMarketplaceCache = () => {
  publicMarketplaceCache.clear();
  return expirePublicMarketplaceRuntimeCache().catch((error) => {
    console.warn(
      `[${productName}] public marketplace runtime cache invalidation failed: ${
        operationalErrorLabel(error)
      }`,
    );
  });
};

const sendPublicMarketplaceJson = <T,>(
  response: express.Response,
  payload: T,
  key: PublicMarketplaceCacheKey,
) => {
  response.setHeader("Cache-Control", publicMarketplaceCacheControl);
  response.setHeader("CDN-Cache-Control", publicMarketplaceCdnCacheControl);
  response.setHeader("Vercel-CDN-Cache-Control", publicMarketplaceCdnCacheControl);
  response.setHeader("Vercel-Cache-Tag", publicMarketplaceCacheTags[key].join(","));
  response.json(payload);
};

const warmPublicMarketplaceCache = () => {
  if (process.env.DISABLE_PUBLIC_MARKETPLACE_CACHE_WARMUP === "1") return;
  if (process.env.VERCEL === "1") return;

  setTimeout(() => {
    void readPublicMarketplaceCache(
      "marketplace-brands",
      readMarketplaceBrandProfiles,
      { fallback: fallbackMarketplaceBrandProfiles },
    )
      .then(() =>
        readPublicMarketplaceCache(
          "marketplace-campaigns",
          readMarketplaceCampaignPosts,
          { fallback: fallbackMarketplaceCampaignPosts },
        ),
      )
      .catch((error) => {
        console.warn(
          `[${productName}] public marketplace cache warmup failed: ${
            operationalErrorLabel(error)
          }`,
        );
      });
  }, 0);
};

warmPublicMarketplaceCache();

type MarketplaceFollowerSyncStatus =
  | "synced"
  | "failed"
  | "skipped"
  | "not_configured";

type MarketplaceFollowerSyncEventStatus =
  | "updated"
  | "unchanged"
  | "failed"
  | "skipped"
  | "not_configured";

type MarketplaceFollowerSyncSnapshot = {
  status: MarketplaceFollowerSyncStatus;
  checkedAt: string;
  provider: string;
  followerCount?: number;
  followersLabel?: string;
  httpStatus?: number;
  error?: string;
  metadata?: Record<string, unknown>;
};

type MarketplaceFollowerSyncQueueItem = {
  profile: SupabaseMarketplaceInfluencerProfileRow;
  channel: SupabaseMarketplaceInfluencerChannelRow;
};

type MarketplaceFollowerSyncResult = {
  run_id: string;
  status: SupabaseMarketplaceFollowerSyncRunRow["status"];
  started_at: string;
  finished_at: string;
  requested_by: string;
  channels_checked: number;
  channels_updated: number;
  channels_failed: number;
  channels_skipped: number;
};

const marketplaceFollowerSyncConcurrency = 5;
let marketplaceFollowerSyncInFlight:
  | Promise<MarketplaceFollowerSyncResult>
  | undefined;

const truncateMarketplaceSyncText = (value: string | undefined, max = 500) => {
  if (!value) return undefined;
  return value.length > max ? `${value.slice(0, max - 1)}...` : value;
};

const normalizeFollowerCount = (value: unknown) => {
  const parsed =
    typeof value === "number"
      ? value
      : typeof value === "string"
        ? Number(value.replace(/[^\d]/g, ""))
        : Number.NaN;

  if (!Number.isFinite(parsed) || parsed < 0) return undefined;
  return Math.floor(parsed);
};

const formatMarketplaceFollowerCountLabel = (count: number) => {
  if (count >= 10_000) {
    const tenThousands = count / 10_000;
    const formatted =
      tenThousands >= 100
        ? Math.round(tenThousands).toLocaleString("ko-KR")
        : tenThousands.toFixed(1).replace(/\.0$/, "");
    return `${formatted}\ub9cc`;
  }

  return `${count.toLocaleString("ko-KR")}\uba85`;
};

const buildFollowerSnapshot = (
  snapshot: Omit<MarketplaceFollowerSyncSnapshot, "checkedAt"> & {
    checkedAt?: string;
  },
): MarketplaceFollowerSyncSnapshot => ({
  ...snapshot,
  checkedAt: snapshot.checkedAt ?? new Date().toISOString(),
  error: truncateMarketplaceSyncText(snapshot.error),
});

const fetchYoutubeFollowerSnapshot = async (
  channel: SupabaseMarketplaceInfluencerChannelRow,
): Promise<MarketplaceFollowerSyncSnapshot> => {
  const apiKey = process.env.YOUTUBE_DATA_API_KEY?.trim();
  if (!apiKey) {
    return buildFollowerSnapshot({
      status: "not_configured",
      provider: "youtube_data_api",
      error: "YOUTUBE_DATA_API_KEY is not configured.",
    });
  }

  const target = parseYoutubeChannelTarget(channel.url ?? "", channel.handle);
  if (!target.value) {
    return buildFollowerSnapshot({
      status: "skipped",
      provider: "youtube_data_api",
      error: "YouTube channel handle or channel id is missing.",
    });
  }

  try {
    const response = await fetchYoutubeChannelForTarget(apiKey, target, 4500, true);
    const item = response.payload.items?.[0];
    const followerCount = normalizeFollowerCount(item?.statistics?.subscriberCount);

    if (!response.ok) {
      return buildFollowerSnapshot({
        status: "failed",
        provider: "youtube_data_api",
        httpStatus: response.status,
        error: "YouTube Data API request failed.",
      });
    }

    if (!item) {
      return buildFollowerSnapshot({
        status: "failed",
        provider: "youtube_data_api",
        httpStatus: response.status,
        error: "YouTube channel was not found.",
      });
    }

    if (item.statistics?.hiddenSubscriberCount || followerCount === undefined) {
      return buildFollowerSnapshot({
        status: "skipped",
        provider: "youtube_data_api",
        httpStatus: response.status,
        error: "YouTube subscriber count is hidden.",
        metadata: {
          channel_id: item.id,
          title: item.snippet?.title,
          hidden_subscriber_count: item.statistics?.hiddenSubscriberCount ?? false,
        },
      });
    }

    return buildFollowerSnapshot({
      status: "synced",
      provider: "youtube_data_api",
      httpStatus: response.status,
      followerCount,
      metadata: {
        channel_id: item.id,
        title: item.snippet?.title,
        custom_url: item.snippet?.customUrl,
        video_count: normalizeFollowerCount(item.statistics?.videoCount),
      },
    });
  } catch (error) {
    return buildFollowerSnapshot({
      status: "failed",
      provider: "youtube_data_api",
      error: error instanceof Error ? error.message : "YouTube sync failed.",
    });
  }
};

const fetchInstagramFollowerSnapshot = async (
  channel: SupabaseMarketplaceInfluencerChannelRow,
): Promise<MarketplaceFollowerSyncSnapshot> => {
  const accessToken = process.env.META_GRAPH_ACCESS_TOKEN?.trim();
  const igUserId = process.env.META_IG_USER_ID?.trim();
  const graphVersion = process.env.META_GRAPH_API_VERSION?.trim() || "v24.0";
  const username = normalizeHandleForComparison(channel.handle).replace(
    /[^a-z0-9._]/g,
    "",
  );

  if (!accessToken || !igUserId) {
    return buildFollowerSnapshot({
      status: "not_configured",
      provider: "instagram_graph_api",
      error: "META_GRAPH_ACCESS_TOKEN/META_IG_USER_ID is not configured.",
      metadata: { username: username || undefined },
    });
  }

  if (!username) {
    return buildFollowerSnapshot({
      status: "skipped",
      provider: "instagram_graph_api",
      error: "Instagram username is missing.",
    });
  }

  try {
    const url = new URL(`https://graph.facebook.com/${graphVersion}/${igUserId}`);
    url.searchParams.set(
      "fields",
      `business_discovery.username(${username}){id,username,followers_count,media_count}`,
    );
    url.searchParams.set("access_token", accessToken);
    const response = await fetchJsonWithTimeout<{
      business_discovery?: {
        id?: string;
        username?: string;
        followers_count?: number;
        media_count?: number;
      };
      error?: unknown;
    }>(url.toString(), {}, 4500);
    const profile = response.payload.business_discovery;
    const followerCount = normalizeFollowerCount(profile?.followers_count);

    if (!response.ok) {
      return buildFollowerSnapshot({
        status: "failed",
        provider: "instagram_graph_api",
        httpStatus: response.status,
        error: "Instagram Graph API request failed.",
        metadata: { username },
      });
    }

    if (!profile || followerCount === undefined) {
      return buildFollowerSnapshot({
        status: "failed",
        provider: "instagram_graph_api",
        httpStatus: response.status,
        error: "Instagram business discovery did not return a follower count.",
        metadata: { username },
      });
    }

    return buildFollowerSnapshot({
      status: "synced",
      provider: "instagram_graph_api",
      httpStatus: response.status,
      followerCount,
      metadata: {
        id: profile.id,
        username: profile.username,
        media_count: profile.media_count,
      },
    });
  } catch (error) {
    return buildFollowerSnapshot({
      status: "failed",
      provider: "instagram_graph_api",
      error: error instanceof Error ? error.message : "Instagram sync failed.",
      metadata: { username },
    });
  }
};

const fetchTikTokFollowerSnapshot = async (
  channel: SupabaseMarketplaceInfluencerChannelRow,
): Promise<MarketplaceFollowerSyncSnapshot> => {
  const token = process.env.TIKTOK_ACCOUNT_ACCESS_TOKEN?.trim();
  const expectedHandle = normalizeHandleForComparison(channel.handle);

  if (!token) {
    return buildFollowerSnapshot({
      status: "not_configured",
      provider: "tiktok_login_kit",
      error: "TIKTOK_ACCOUNT_ACCESS_TOKEN is not configured.",
      metadata: { expected_handle: expectedHandle || undefined },
    });
  }

  try {
    const url = new URL("https://open.tiktokapis.com/v2/user/info/");
    url.searchParams.set(
      "fields",
      ["username", "display_name", "follower_count", "video_count"].join(","),
    );
    const response = await fetchJsonWithTimeout<{
      data?: {
        user?: {
          username?: string;
          display_name?: string;
          follower_count?: number;
          video_count?: number;
        };
      };
      error?: unknown;
    }>(
      url.toString(),
      {
        headers: {
          Authorization: `Bearer ${token}`,
          Accept: "application/json",
        },
      },
      4500,
    );
    const user = response.payload.data?.user;
    const userHandle = normalizeHandleForComparison(user?.username);
    const followerCount = normalizeFollowerCount(user?.follower_count);

    if (!response.ok) {
      return buildFollowerSnapshot({
        status: "failed",
        provider: "tiktok_login_kit",
        httpStatus: response.status,
        error: "TikTok user info request failed.",
        metadata: { expected_handle: expectedHandle || undefined },
      });
    }

    if (expectedHandle && userHandle && expectedHandle !== userHandle) {
      return buildFollowerSnapshot({
        status: "skipped",
        provider: "tiktok_login_kit",
        httpStatus: response.status,
        error: "TikTok token user does not match the marketplace channel handle.",
        metadata: {
          expected_handle: expectedHandle,
          token_username: userHandle,
        },
      });
    }

    if (!user || followerCount === undefined) {
      return buildFollowerSnapshot({
        status: "failed",
        provider: "tiktok_login_kit",
        httpStatus: response.status,
        error: "TikTok user info did not return a follower count.",
        metadata: { expected_handle: expectedHandle || undefined },
      });
    }

    return buildFollowerSnapshot({
      status: "synced",
      provider: "tiktok_login_kit",
      httpStatus: response.status,
      followerCount,
      metadata: {
        username: user.username,
        display_name: user.display_name,
        video_count: user.video_count,
      },
    });
  } catch (error) {
    return buildFollowerSnapshot({
      status: "failed",
      provider: "tiktok_login_kit",
      error: error instanceof Error ? error.message : "TikTok sync failed.",
      metadata: { expected_handle: expectedHandle || undefined },
    });
  }
};

const fetchMarketplaceFollowerSnapshot = (
  channel: SupabaseMarketplaceInfluencerChannelRow,
) => {
  if (channel.platform === "youtube") return fetchYoutubeFollowerSnapshot(channel);
  if (channel.platform === "instagram") return fetchInstagramFollowerSnapshot(channel);
  if (channel.platform === "tiktok") return fetchTikTokFollowerSnapshot(channel);
  if (channel.platform === "naver_blog") {
    return Promise.resolve(
      buildFollowerSnapshot({
        status: "skipped",
        provider: "creator_self_report",
        error: "Naver Blog visitor metrics require a creator self-report.",
      }),
    );
  }

  return Promise.resolve(
    buildFollowerSnapshot({
      status: "skipped",
      provider: "public_url_challenge",
      error: `${channel.platform} follower sync is not supported by a configured provider.`,
    }),
  );
};

const getMarketplaceFollowerSyncChannelStatus = (
  snapshot: MarketplaceFollowerSyncSnapshot,
): NonNullable<SupabaseMarketplaceInfluencerChannelRow["follower_sync_status"]> => {
  if (snapshot.status === "synced") return "synced";
  return snapshot.status;
};

const getMarketplaceFollowerSyncEventStatus = ({
  snapshot,
  previousCount,
}: {
  snapshot: MarketplaceFollowerSyncSnapshot;
  previousCount?: number;
}): MarketplaceFollowerSyncEventStatus => {
  if (snapshot.status === "synced") {
    return previousCount === snapshot.followerCount ? "unchanged" : "updated";
  }
  return snapshot.status;
};

const isMarketplaceFollowerSyncDue = (
  channel: SupabaseMarketplaceInfluencerChannelRow,
  nowMs = Date.now(),
) => {
  if (channel.follower_sync_status !== "synced") return true;
  if (!channel.follower_count_synced_at) return true;
  const syncedAt = Date.parse(channel.follower_count_synced_at);
  return !Number.isFinite(syncedAt) || nowMs - syncedAt >= marketplaceFollowerSyncStaleMs;
};

const compareMarketplaceFollowerSyncQueue = (
  left: MarketplaceFollowerSyncQueueItem,
  right: MarketplaceFollowerSyncQueueItem,
) => {
  const leftSynced = left.channel.follower_count_synced_at
    ? Date.parse(left.channel.follower_count_synced_at)
    : 0;
  const rightSynced = right.channel.follower_count_synced_at
    ? Date.parse(right.channel.follower_count_synced_at)
    : 0;

  return leftSynced - rightSynced;
};

const readMarketplaceFollowerSyncQueue = async (limit: number) => {
  const { profiles, channels } = await readMarketplaceInfluencerRows(
    "?select=*&is_published=eq.true&order=updated_at.desc",
  );
  const queue = profiles.flatMap((profile) =>
    (channels.get(profile.id) ?? []).map((channel) => ({ profile, channel })),
  );

  return queue
    .filter(
      ({ channel }) =>
        channel.platform !== "naver_blog" &&
        channel.platform !== "youtube" &&
        isMarketplaceFollowerSyncDue(channel),
    )
    .sort(compareMarketplaceFollowerSyncQueue)
    .slice(0, limit);
};

const syncMarketplaceFollowerChannel = async ({
  runId,
  item,
}: {
  runId: string;
  item: MarketplaceFollowerSyncQueueItem;
}) => {
  const snapshot = await fetchMarketplaceFollowerSnapshot(item.channel);
  const previousCount = item.channel.follower_count ?? undefined;
  const nextFollowersLabel =
    snapshot.status === "synced" && snapshot.followerCount !== undefined
      ? (snapshot.followersLabel ??
        formatMarketplaceFollowerCountLabel(snapshot.followerCount))
      : item.channel.followers_label;
  const eventStatus = getMarketplaceFollowerSyncEventStatus({
    snapshot,
    previousCount,
  });
  const channelSyncStatus = getMarketplaceFollowerSyncChannelStatus(snapshot);
  const checkedAt = snapshot.checkedAt;

  await patchSupabaseRecord(
    "marketplace_influencer_channels",
    `?id=eq.${encodeURIComponent(item.channel.id)}`,
    {
      ...(snapshot.status === "synced"
        ? {
            follower_count: snapshot.followerCount,
            followers_label: nextFollowersLabel,
            follower_count_synced_at: checkedAt,
          }
        : {}),
      follower_sync_status: channelSyncStatus,
      follower_sync_source: snapshot.provider,
      follower_sync_error: snapshot.error ?? null,
      follower_sync_metadata: {
        ...(snapshot.metadata ?? {}),
        checked_at: checkedAt,
        http_status: snapshot.httpStatus ?? null,
      },
      updated_at: checkedAt,
    },
    "Supabase marketplace follower channel sync",
  );

  return {
    event: {
      id: randomUUID(),
      run_id: runId,
      channel_id: item.channel.id,
      profile_id: item.profile.id,
      platform: item.channel.platform,
      handle: item.channel.handle,
      status: eventStatus,
      previous_follower_count: previousCount ?? null,
      follower_count: snapshot.followerCount ?? null,
      previous_followers_label: item.channel.followers_label ?? null,
      followers_label: nextFollowersLabel ?? null,
      provider: snapshot.provider,
      http_status: snapshot.httpStatus ?? null,
      error_message: snapshot.error ?? null,
      checked_at: checkedAt,
      metadata: snapshot.metadata ?? {},
    },
    snapshot,
    eventStatus,
  };
};

const runMarketplaceFollowerSyncInternal = async ({
  requestedBy,
  maxChannels = marketplaceFollowerSyncMaxChannels,
}: {
  requestedBy: string;
  maxChannels?: number;
}): Promise<MarketplaceFollowerSyncResult> => {
  if (!useSupabase) {
    throw new Error("Supabase is not configured");
  }

  const startedAt = new Date().toISOString();
  const runId = randomUUID();
  const effectiveMaxChannels = Math.max(1, Math.min(Math.floor(maxChannels), 100));

  await upsertSupabaseV2Rows("marketplace_follower_sync_runs", [
    {
      id: runId,
      requested_by: requestedBy,
      status: "running",
      started_at: startedAt,
      channels_checked: 0,
      channels_updated: 0,
      channels_failed: 0,
      channels_skipped: 0,
      metadata: {
        max_channels: effectiveMaxChannels,
        stale_days: marketplaceFollowerSyncStaleMs / dayMs,
      },
    },
  ]);

  try {
    const queue = await readMarketplaceFollowerSyncQueue(effectiveMaxChannels);
    const channelResults: Awaited<
      ReturnType<typeof syncMarketplaceFollowerChannel>
    >[] = [];

    for (let index = 0; index < queue.length; index += marketplaceFollowerSyncConcurrency) {
      const chunk = queue.slice(index, index + marketplaceFollowerSyncConcurrency);
      channelResults.push(
        ...(await Promise.all(
          chunk.map((item) => syncMarketplaceFollowerChannel({ runId, item })),
        )),
      );
    }

    await insertSupabaseV2Rows(
      "marketplace_follower_sync_events",
      channelResults.map((result) => result.event),
    );

    const channelsUpdated = channelResults.filter((result) =>
      ["updated", "unchanged"].includes(result.eventStatus),
    ).length;
    const channelsFailed = channelResults.filter(
      (result) => result.eventStatus === "failed",
    ).length;
    const channelsSkipped = channelResults.length - channelsUpdated - channelsFailed;
    const finishedAt = new Date().toISOString();
    const status: SupabaseMarketplaceFollowerSyncRunRow["status"] =
      channelsFailed > 0 && channelsUpdated + channelsSkipped > 0
        ? "partial_failed"
        : channelsFailed > 0
          ? "failed"
          : "completed";

    await patchSupabaseRecord(
      "marketplace_follower_sync_runs",
      `?id=eq.${encodeURIComponent(runId)}`,
      {
        status,
        finished_at: finishedAt,
        channels_checked: channelResults.length,
        channels_updated: channelsUpdated,
        channels_failed: channelsFailed,
        channels_skipped: channelsSkipped,
        metadata: {
          max_channels: effectiveMaxChannels,
          queued_channels: queue.length,
          stale_days: marketplaceFollowerSyncStaleMs / dayMs,
        },
      },
      "Supabase marketplace follower sync run update",
    );

    if (channelsUpdated > 0) clearPublicMarketplaceCache();

    return {
      run_id: runId,
      status,
      started_at: startedAt,
      finished_at: finishedAt,
      requested_by: requestedBy,
      channels_checked: channelResults.length,
      channels_updated: channelsUpdated,
      channels_failed: channelsFailed,
      channels_skipped: channelsSkipped,
    };
  } catch (error) {
    clearPublicMarketplaceCache();
    const finishedAt = new Date().toISOString();
    const message = truncateMarketplaceSyncText(
      error instanceof Error ? error.message : "Marketplace follower sync failed.",
    );

    await patchSupabaseRecord(
      "marketplace_follower_sync_runs",
      `?id=eq.${encodeURIComponent(runId)}`,
      {
        status: "failed",
        finished_at: finishedAt,
        error_message: message,
      },
      "Supabase marketplace follower sync failure update",
    );

    throw error;
  }
};

const runMarketplaceFollowerSync = (options: {
  requestedBy: string;
  maxChannels?: number;
}) => {
  if (!marketplaceFollowerSyncInFlight) {
    marketplaceFollowerSyncInFlight = runMarketplaceFollowerSyncInternal(options).finally(
      () => {
        marketplaceFollowerSyncInFlight = undefined;
      },
    );
  }

  return marketplaceFollowerSyncInFlight;
};

const buildMarketplaceBrandHandle = (
  organization: SupabaseOrganizationRow,
  profile: SupabaseProfileRow,
  options: { name?: string; suffix?: string } = {},
) => {
  const source = `${options.name || organization.name || profile.company_name || profile.name || "brand"}`;
  const normalized = source
    .normalize("NFKD")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  const suffix = (options.suffix || organization.id).replace(/-/g, "").slice(0, 6);
  const base = normalized.length >= 3 ? normalized.slice(0, 20).replace(/-+$/g, "") : "brand";

  return `${base}-${suffix}`.slice(0, 30).replace(/-+$/g, "");
};

const readAdvertiserMarketplaceBrandRows = async (
  organizationId: string,
  options: { includeArchived?: boolean } = {},
) => {
  if (!useSupabase) return [] as SupabaseMarketplaceBrandProfileRow[];

  const rows = await readSupabaseRows<SupabaseMarketplaceBrandProfileRow>(
    "marketplace_brand_profiles",
    `?select=*&organization_id=eq.${encodeURIComponent(organizationId)}${
      options.includeArchived ? "" : "&archived_at=is.null"
    }&order=is_default.desc,created_at.asc`,
    "advertiser marketplace brand profiles",
  );
  return hydrateBrandRowsWithNormalizedCampaigns(rows, { readAll: true });
};

const readAdvertiserMarketplaceBrandRow = async (
  organizationId: string,
  brandId?: string,
) => {
  if (!useSupabase) return undefined;

  if (brandId && isUuid(brandId)) {
    const rows = await readSupabaseRows<SupabaseMarketplaceBrandProfileRow>(
      "marketplace_brand_profiles",
      `?select=*&organization_id=eq.${encodeURIComponent(
        organizationId,
      )}&id=eq.${encodeURIComponent(brandId)}&archived_at=is.null&limit=1`,
      "advertiser marketplace selected brand profile",
    );
    if (rows[0]) {
      return (
        await hydrateBrandRowsWithNormalizedCampaigns(rows, { readAll: true })
      )[0];
    }
  }

  const rows = await readAdvertiserMarketplaceBrandRows(organizationId);
  return rows[0];
};

const buildAdvertiserBrandProfileFromAuth = (
  auth: AdvertiserSession,
  organization: SupabaseOrganizationRow,
  row?: SupabaseMarketplaceBrandProfileRow,
): MarketplaceBrandProfile => {
  if (row) {
    return mapBrandProfileRowToMarketplaceProfile(
      row,
      Number.MAX_SAFE_INTEGER,
    );
  }

  const name = organization.name || auth.profile.company_name || auth.profile.name || "광고주";

  return {
    id: stableUuid(`marketplace:brand:${organization.id}`),
    organizationId: organization.id,
    handle: buildMarketplaceBrandHandle(organization, auth.profile),
    displayName: name,
    category: "캠페인 모집",
    headline: "인플루언서 협업 캠페인을 모집합니다",
    description:
      "모집글을 등록하면 인플루언서가 캠페인 조건을 확인하고 신청할 수 있습니다.",
    location: "운영 지역 미입력",
    logoLabel: buildMarketplaceAvatarLabel(name, "BR"),
    preferredPlatforms: [],
    proposalTypes: ["sponsored_post", "product_seeding", "supporters"],
    budgetRangeLabel: "협의 가능",
    responseTimeLabel: "제안 확인 후 응답",
    statusLabel: "모집 준비",
    fitTags: ["캠페인 모집", "전자계약 가능"],
    audienceTargets: [],
    activeCampaigns: [],
    recentCreators: [],
    isDefault: true,
  };
};

const ensureAdvertiserDefaultBrandRow = async (
  auth: AdvertiserSession,
  organization: SupabaseOrganizationRow,
  rows: SupabaseMarketplaceBrandProfileRow[],
) => {
  if (!useSupabase || rows.length > 0) return rows;

  const brand = buildAdvertiserBrandProfileFromAuth(auth, organization);
  const now = new Date().toISOString();
  await upsertSupabaseV2Rows(
    "marketplace_brand_profiles",
    [
      {
        id: brand.id,
        organization_id: organization.id,
        data_origin: await readTrustedProfileDataOrigin(auth.profile.id),
        public_handle: brand.handle,
        display_name: brand.displayName,
        category: brand.category,
        headline: brand.headline,
        description: brand.description,
        location: brand.location,
        logo_label: brand.logoLabel,
        logo_url: brand.logoUrl ?? null,
        preferred_platforms: brand.preferredPlatforms,
        proposal_types: brand.proposalTypes,
        budget_range_label: brand.budgetRangeLabel,
        response_time_label: brand.responseTimeLabel,
        status_label: brand.statusLabel,
        fit_tags: brand.fitTags,
        audience_targets: brand.audienceTargets,
        active_campaigns: brand.activeCampaigns,
        recent_creators: brand.recentCreators,
        is_published: false,
        is_default: true,
        archived_at: null,
        updated_at: now,
      },
    ],
    "id",
  );
  await clearPublicMarketplaceCache();
  return readAdvertiserMarketplaceBrandRows(organization.id);
};

const normalizeAdvertiserSelectedBrandId = (value: unknown) =>
  isUuid(normalizeRequiredText(value)) ? normalizeRequiredText(value) : undefined;

const readAdvertiserCampaignBoard = async (
  auth: AdvertiserSession,
  selectedBrandId?: string,
) => {
  const organization = await readDefaultOrganizationForProfile(auth.profile.id);
  if (!organization) {
    return {
      organization: undefined,
      brand: undefined,
      brands: [] as MarketplaceBrandProfile[],
      campaigns: [] as MarketplaceBrandCampaign[],
      campaignAccess: emptyAdvertiserCampaignAccess(),
    };
  }

  const rows = await ensureAdvertiserDefaultBrandRow(
    auth,
    organization,
    await readAdvertiserMarketplaceBrandRows(organization.id),
  );
  const row =
    selectedBrandId && rows.some((item) => item.id === selectedBrandId)
      ? rows.find((item) => item.id === selectedBrandId)
      : rows[0];
  const rawBrand = buildAdvertiserBrandProfileFromAuth(auth, organization, row);
  const brand =
    normalizeTestBrandProfileCampaignDatesForSession(auth, rawBrand) ?? rawBrand;
  const brands =
    rows.length > 0
      ? rows
          .map((item) => buildAdvertiserBrandProfileFromAuth(auth, organization, item))
          .map((item) => normalizeTestBrandProfileCampaignDatesForSession(auth, item) ?? item)
      : [brand];
  const campaignAccess = useSupabase
    ? await readProgressiveCampaignAccess(organization.id)
    : emptyAdvertiserCampaignAccess();

  return {
    organization,
    brand,
    brands,
    campaigns: brand.activeCampaigns,
    campaignAccess,
  };
};

const saveAdvertiserMarketplaceBrandImage = async (
  auth: AdvertiserSession,
  file: NonNullable<ReturnType<typeof parseEvidenceFile>>,
  selectedBrandId?: string,
) => {
  if (!useSupabase) {
    return {
      ok: false as const,
      status: 503,
      error: "Supabase is required for brand image upload",
    };
  }

  const organization = await readDefaultOrganizationForProfile(auth.profile.id);
  if (!organization) {
    return {
      ok: false as const,
      status: 409,
      error: "Advertiser organization is required",
    };
  }

  const existing = await readAdvertiserMarketplaceBrandRow(
    organization.id,
    selectedBrandId,
  );
  const currentBrand = buildAdvertiserBrandProfileFromAuth(
    auth,
    organization,
    existing,
  );
  const now = new Date().toISOString();
  const rowId = existing?.id ?? stableUuid(`marketplace:brand:${organization.id}`);
  const imageUrl = await storeMarketplacePublicImage({
    area: "brand-logos",
    ownerId: rowId,
    file,
  });
  const displayName = currentBrand.displayName || organization.name;

  await upsertSupabaseV2Rows(
    "marketplace_brand_profiles",
    [
      {
        id: rowId,
        organization_id: organization.id,
        data_origin:
          normalizeDataOrigin(auth.profile.data_origin) ??
          deriveDataOrigin([auth.profile.email, auth.user.email]),
        public_handle:
          existing?.public_handle ?? buildMarketplaceBrandHandle(organization, auth.profile),
        display_name: displayName,
        category: currentBrand.category,
        headline: currentBrand.headline,
        description: currentBrand.description,
        location: currentBrand.location,
        logo_label: currentBrand.logoLabel || buildMarketplaceAvatarLabel(displayName, "BR"),
        logo_url: imageUrl,
        preferred_platforms: currentBrand.preferredPlatforms,
        proposal_types: currentBrand.proposalTypes,
        budget_range_label: currentBrand.budgetRangeLabel,
        response_time_label: currentBrand.responseTimeLabel,
        status_label: currentBrand.statusLabel,
        fit_tags: currentBrand.fitTags,
        audience_targets: currentBrand.audienceTargets,
        active_campaigns: currentBrand.activeCampaigns,
        recent_creators: currentBrand.recentCreators,
        is_published: existing?.is_published ?? currentBrand.activeCampaigns.length > 0,
        is_default: existing?.is_default ?? true,
        archived_at: null,
        updated_at: now,
      },
    ],
    "id",
  );
  await clearPublicMarketplaceCache();

  const savedRow = await readAdvertiserMarketplaceBrandRow(organization.id, rowId);
  return {
    ok: true as const,
    image_url: imageUrl,
    brand: buildAdvertiserBrandProfileFromAuth(auth, organization, savedRow),
  };
};

